function JobContactModal({ contact, onSave, onClose }) {
  const ROLES = ['Spouse','Partner','Property Manager','Building Manager','HOA Contact','Assistant','Housekeeper','Other']
  const [vals, setVals] = React.useState({ name:contact?.name||'', role:contact?.role||'Spouse', phone:contact?.phone||'', email:contact?.email||'' })
  const inp = { width:'100%', padding:'9px 12px', border:'1.5px solid rgba(0,0,0,0.1)', borderRadius:'9px', fontSize:'16px', fontFamily:'inherit', color:'#1a2e2b', outline:'none', boxSizing:'border-box' }
  const lbl = { fontSize:'11px', fontWeight:700, color:'#4a5e5a', textTransform:'uppercase', letterSpacing:'0.5px', marginBottom:'5px', display:'block' }
  return (
    <div style={{ position:'fixed', inset:0, zIndex:10010, display:'flex', alignItems:'center', justifyContent:'center', padding:'24px' }} onClick={onClose}>
      <div style={{ background:'white', borderRadius:'20px', width:'100%', maxWidth:'400px', boxShadow:'0 24px 60px rgba(26,46,43,0.25)' }} onClick={e=>e.stopPropagation()}>
        <div style={{ padding:'18px 20px 14px', borderBottom:'1px solid rgba(0,0,0,0.06)', display:'flex', justifyContent:'space-between', alignItems:'center' }}>
          <p style={{ fontSize:'16px', fontWeight:700, color:'#1a2e2b', fontFamily:'Georgia,serif' }}>{contact ? 'Edit Contact' : 'Add Job Contact'}</p>
          <button onClick={onClose} style={{ background:'none', border:'none', fontSize:'22px', color:'#8a9e9a', cursor:'pointer', lineHeight:1 }}>×</button>
        </div>
        <div style={{ padding:'16px 20px', display:'grid', gap:'12px' }}>
          <div>
            <label style={lbl}>Name</label>
            <input style={inp} value={vals.name} onChange={e=>setVals(p=>({...p,name:e.target.value}))} placeholder='Full name' autoFocus />
          </div>
          <div>
            <label style={lbl}>Role</label>
            <select style={{...inp}} value={vals.role} onChange={e=>setVals(p=>({...p,role:e.target.value}))}>
              {ROLES.map(r=><option key={r}>{r}</option>)}
            </select>
          </div>
          <div>
            <label style={lbl}>Phone</label>
            <input style={inp} value={vals.phone} onChange={e=>setVals(p=>({...p,phone:e.target.value}))} placeholder='(303) 555-0000' />
          </div>
          <div>
            <label style={lbl}>Email</label>
            <input style={inp} type='email' value={vals.email} onChange={e=>setVals(p=>({...p,email:e.target.value}))} placeholder='name@email.com' />
          </div>
        </div>
        <div style={{ padding:'8px 20px 20px', display:'flex', gap:'8px' }}>
          <button onClick={onClose} style={{ flex:1, padding:'11px', background:'transparent', border:'1.5px solid rgba(0,0,0,0.1)', borderRadius:'10px', fontSize:'13px', fontFamily:'inherit', color:'#4a5e5a', cursor:'pointer' }}>Cancel</button>
          <button onClick={()=>{ if(vals.name.trim()) onSave({...vals, id:contact?.id||`jc${Date.now()}`}) }} disabled={!vals.name.trim()}
            style={{ flex:2, padding:'11px', background:vals.name.trim()?'#1a2e2b':'#e5e7eb', border:'none', borderRadius:'10px', fontSize:'13px', fontFamily:'inherit', fontWeight:700, color:vals.name.trim()?'white':'#9ca3af', cursor:vals.name.trim()?'pointer':'not-allowed' }}>
            Save
          </button>
        </div>
      </div>
    </div>
  )
}

