// ─── Header Chips (Project + Tags) ────────────────────────────────────────────
function HeaderChips({ person, update, children }) {
  const [editingProject, setEditingProject] = useState(false)
  const PROJECTS = ['Home Organization', 'Full Home', 'Kitchen + Pantry', 'Closet', 'Garage', 'Office', 'Move-In', 'Move-Out', 'Other']

  return (
    <div
      style={{
        display: 'flex',
        gap: '6px',
        flexWrap: 'wrap',
        marginTop: '4px',
        alignItems: 'center',
        position: 'relative',
      }}
    >
      {/* Project type — inline text + chevron, NOT a pill */}
      <div style={{ position: 'relative' }}>
        <button
          onClick={() => setEditingProject(v => !v)}
          aria-label="Edit project type"
          style={{
            display: 'inline-flex',
            alignItems: 'center',
            gap: '4px',
            background: 'none',
            border: 'none',
            cursor: 'pointer',
            padding: '2px 4px',
            fontFamily: 'inherit',
            fontSize: '10px',
            color: '#4a5e5a',
            fontWeight: 500,
            lineHeight: 1.2,
          }}
        >
          <span>🏠</span>
          <span style={{ opacity: person.project ? 1 : 0.5 }}>
            {person.project || 'Set project'}
          </span>
          <span style={{ fontSize: '9px', opacity: 0.5 }}>▾</span>
        </button>
        {editingProject && (
          <div
            style={{
              position: 'absolute',
              top: 'calc(100% + 4px)',
              left: 0,
              zIndex: 100,
              background: 'white',
              border: '1px solid rgba(0,0,0,0.1)',
              borderRadius: '10px',
              boxShadow: '0 4px 16px rgba(0,0,0,0.12)',
              padding: '6px',
              minWidth: '180px',
            }}
          >
            {PROJECTS.map(p => (
              <button
                key={p}
                onClick={() => {
                  update({ ...person, project: p })
                  setEditingProject(false)
                }}
                style={{
                  display: 'block',
                  width: '100%',
                  padding: '7px 10px',
                  background: person.project === p ? 'rgba(212,160,70,0.08)' : 'transparent',
                  border: 'none',
                  borderRadius: '7px',
                  fontSize: '12px',
                  fontFamily: 'inherit',
                  color: person.project === p ? '#b07a20' : '#1a2e2b',
                  cursor: 'pointer',
                  textAlign: 'left',
                  fontWeight: person.project === p ? 600 : 400,
                }}
              >
                {p}
              </button>
            ))}
          </div>
        )}
      </div>

      {/* Children: `|` separator + tag pills + `+ tag` button passed in from PersonPanel */}
      {children}

      {/* Backdrop to close the project dropdown on outside click */}
      {editingProject && (
        <div
          style={{ position: 'fixed', inset: 0, zIndex: 99 }}
          onClick={() => setEditingProject(false)}
        />
      )}
    </div>
  )
}



