// ─── Master drip content helpers ──────────────────────────────────────────────
// The 8 corp master paths in drip_paths (seed_master_drip_paths.sql) are the
// ONLY source of drip copy. Onboarding and Settings → Communications both read them via
// GET /api/drip-paths/masters, which returns each master's steps with their
// inline subject/body.
//
// Historical note: this file used to carry DEFAULT_TEMPLATES + DEFAULT_PATH_STEPS
// — prototype copy invented for the 5/23 build ("How We Help", "Real Results").
// Those constants seeded the legacy t1–t9 / ta1–td2 template rows AND were what
// the onboarding preview rendered and what savePathToDb() materialized into real
// per-location paths, so a first customization silently swapped an owner's live
// drip from Kevin's content to the prototype (Portland/moving-d, 7/13). Both
// constants are deleted: prototype copy no longer ships in the bundle at all.

function daysToDelayLabel(days) {
  if (!days || days <= 0) return 'Immediately'
  return `${days} day${days === 1 ? '' : 's'} later`
}

// One master path's steps → the shape the path editors render
// ({ id, order, name, type, delay, subject, body }). Steps carry their content
// INLINE — a master step has no template row behind it, which is exactly why a
// customization must copy subject/body rather than a template pointer.
function masterStepsToUi(master) {
  return (master?.steps || [])
    .filter(s => s?.is_active !== false)
    .map((s, i) => {
      const order = s.step_order ?? (i + 1)
      const type  = s.channel === 'sms' ? 'sms' : 'email'
      return {
        id: `master_${master.path_key}_${order}`,
        order,
        // Emails lead with their subject — it is the most honest one-line
        // summary of what the owner is about to send.
        name: s.subject || `${type === 'sms' ? 'Text' : 'Email'} ${order}`,
        type,
        delay: daysToDelayLabel(s.delay_days),
        delay_days: s.delay_days ?? 0,
        subject: s.subject ?? null,
        body: s.body ?? null,
        fromMaster: true,
        origin: 'master',
      }
    })
    .sort((a, b) => a.order - b.order)
}

// masters array from /api/drip-paths/masters → { [path_key]: uiSteps }
function masterStepsByKey(masters) {
  const out = {}
  for (const m of masters || []) {
    if (!m?.path_key) continue
    out[m.path_key] = masterStepsToUi(m)
  }
  return out
}

// ─── Template Editor Popup ────────────────────────────────────────────────────
// ─── Custom Path Builder ──────────────────────────────────────────────────────
const DELAY_OPTIONS = ['Immediately','1 day later','2 days later','3 days later','4 days later','5 days later','7 days later','10 days later','14 days later']

function CustomPathBuilder({ templates, onSave, onClose, smsEnabled=true }) {
  const [pathName, setPathName] = useState('')
  const [projectType, setProjectType] = useState('any')
  const [steps, setSteps] = useState([
    { id:`cs${Date.now()}`, order:1, name:'', type:'email', delay:'Immediately', templateId:null }
  ])
  const [pickingTemplateFor, setPickingTemplateFor] = useState(null)

  const typeConf = {
    email:{ icon:'📧', color:'#6366f1' },
    sms:  { icon:'💬', color:'#10b981' },
    call: { icon:'📞', color:'#f59e0b' },
  }

  function addStep() {
    setSteps(prev=>[...prev, {
      id:`cs${Date.now()}`,
      order:prev.length+1,
      name:'',
      type:'email',
      delay:'Immediately',
      templateId:null
    }])
  }

  function removeStep(id) {
    setSteps(prev=>prev.filter(s=>s.id!==id).map((s,i)=>({...s,order:i+1})))
  }

  function updateStep(id, key, val) {
    setSteps(prev=>prev.map(s=>s.id===id?{...s,[key]:val}:s))
  }

  function assignTemplate(stepId, templateId) {
    updateStep(stepId, 'templateId', templateId)
    setPickingTemplateFor(null)
  }

  function save() {
    if (!pathName.trim()) return
    const pathId = `custom-${Date.now()}`
    onSave({ pathId, pathName, projectType, steps })
  }

  const canSave = pathName.trim() && steps.length > 0 && steps.every(s=>s.name.trim())

  return (
    <div style={{ position:'fixed', top:0, left:0, right:0, bottom:0, zIndex:10005, display:'flex', alignItems:'flex-end' }}>
      <div style={{ position:'absolute', inset:0, background:'rgba(26,46,43,0.5)' }} onClick={onClose} />
      <div style={{ position:'relative', background:'white', width:'100%', maxWidth:'540px', borderRadius:'16px', zIndex:1, height:'88vh', display:'flex', flexDirection:'column', boxShadow:'0 -8px 40px rgba(26,46,43,0.2)' }}>
        {/* Header */}
        <div style={{ padding:'0.75rem 1.25rem', borderBottom:'1px solid rgba(0,0,0,0.06)', flexShrink:0 }}>
          <div style={{ display:'flex', alignItems:'center', justifyContent:'space-between' }}>
            <h3 style={{ fontSize:'16px', fontFamily:'Georgia,serif', color:'#1a2e2b' }}>Build your own sequence</h3>
            <button onClick={onClose} style={{ background:'none', border:'none', fontSize:'20px', color:'#8a9e9a', cursor:'pointer' }}>×</button>
          </div>
        </div>

        <div style={{ flex:1, overflowY:'auto', padding:'1rem 1.25rem', display:'grid', gap:'14px' }}>

          {/* Path name */}
          <div>
            <label style={{ fontSize:'11px', fontWeight:600, color:'#4a5e5a', textTransform:'uppercase', letterSpacing:'0.5px', display:'block', marginBottom:'5px' }}>Sequence name</label>
            <input
              autoFocus value={pathName} onChange={e=>setPathName(e.target.value)}
              placeholder='e.g. VIP Concierge, Referral Fast-Track...'
              style={{ width:'100%', padding:'10px 12px', border:'1.5px solid rgba(0,0,0,0.1)', borderRadius:'8px', fontSize:'16px', fontFamily:'inherit', color:'#1a2e2b', outline:'none', boxSizing:'border-box' }}
            />
          </div>

          {/* Project type */}
          <div>
            <label style={{ fontSize:'11px', fontWeight:600, color:'#4a5e5a', textTransform:'uppercase', letterSpacing:'0.5px', display:'block', marginBottom:'6px' }}>Applies To</label>
            <div style={{ display:'grid', gridTemplateColumns:'1fr 1fr 1fr', gap:'7px' }}>
              {[['any','🌐','All Clients'],['move','📦','Move Only'],['general','🏠','Organizing Only']].map(([v,icon,label])=>(
                <button key={v} onClick={()=>setProjectType(v)} style={{ padding:'9px', borderRadius:'9px', cursor:'pointer', border:'2px solid', borderColor:projectType===v?'#a8c9c4':'rgba(0,0,0,0.08)', background:projectType===v?'rgba(168,201,196,0.12)':'white', fontFamily:'inherit', display:'flex', flexDirection:'column', alignItems:'center', gap:'4px' }}>
                  <span style={{ fontSize:'18px' }}>{icon}</span>
                  <span style={{ fontSize:'11px', fontWeight:projectType===v?600:400, color:'#1a2e2b' }}>{label}</span>
                </button>
              ))}
            </div>
          </div>

          {/* Steps */}
          <div>
            <div style={{ display:'flex', alignItems:'center', justifyContent:'space-between', marginBottom:'8px' }}>
              <label style={{ fontSize:'11px', fontWeight:600, color:'#4a5e5a', textTransform:'uppercase', letterSpacing:'0.5px' }}>Steps ({steps.length})</label>
              <button onClick={addStep} style={{ fontSize:'12px', color:'#1a2e2b', background:'rgba(168,201,196,0.15)', border:'1px solid rgba(168,201,196,0.3)', borderRadius:'6px', padding:'4px 10px', cursor:'pointer', fontFamily:'inherit', fontWeight:600 }}>+ Add Step</button>
            </div>

            <div style={{ display:'grid', gap:'8px' }}>
              {steps.map((step, i)=>{
                const tc = typeConf[step.type]
                const tmpl = templates.find(t=>t.id===step.templateId)
                return (
                  <div key={step.id} style={{ background:'#f7f5f0', borderRadius:'10px', padding:'12px', border:'1px solid rgba(0,0,0,0.07)' }}>
                    {/* Step header */}
                    <div style={{ display:'flex', alignItems:'center', gap:'8px', marginBottom:'10px' }}>
                      <div style={{ width:'22px', height:'22px', borderRadius:'50%', background:'#1a2e2b', display:'flex', alignItems:'center', justifyContent:'center', flexShrink:0 }}>
                        <span style={{ fontSize:'11px', color:'white', fontWeight:700 }}>{step.order}</span>
                      </div>
                      <input
                        value={step.name} onChange={e=>updateStep(step.id,'name',e.target.value)}
                        placeholder={`Step ${step.order} name...`}
                        style={{ flex:1, padding:'6px 10px', border:'1.5px solid rgba(0,0,0,0.1)', borderRadius:'7px', fontSize:'13px', fontFamily:'inherit', color:'#1a2e2b', outline:'none', background:'white' }}
                      />
                      <button onClick={()=>removeStep(step.id)} style={{ fontSize:'16px', color:'#c8d8d4', background:'none', border:'none', cursor:'pointer', flexShrink:0 }}>×</button>
                    </div>

                    {/* Type + Delay */}
                    <div style={{ display:'grid', gridTemplateColumns:'1fr 1fr', gap:'7px', marginBottom:'8px' }}>
                      <div>
                        <p style={{ fontSize:'10px', color:'#8a9e9a', fontWeight:600, textTransform:'uppercase', letterSpacing:'0.4px', marginBottom:'4px' }}>Type</p>
                        <div style={{ display:'flex', gap:'5px' }}>
                          {Object.entries(typeConf).filter(([v])=>v!=='sms'||smsEnabled).map(([v,conf])=>(
                            <button key={v} onClick={()=>{ updateStep(step.id,'type',v); updateStep(step.id,'templateId',null) }} style={{ flex:1, padding:'6px', borderRadius:'7px', cursor:'pointer', border:'1.5px solid', borderColor:step.type===v?conf.color:'rgba(0,0,0,0.08)', background:step.type===v?`${conf.color}12`:'white', fontSize:'14px', display:'flex', alignItems:'center', justifyContent:'center' }}>
                              {conf.icon}
                            </button>
                          ))}
                        </div>
                      </div>
                      <div>
                        <p style={{ fontSize:'10px', color:'#8a9e9a', fontWeight:600, textTransform:'uppercase', letterSpacing:'0.4px', marginBottom:'4px' }}>Send</p>
                        <select value={step.delay} onChange={e=>updateStep(step.id,'delay',e.target.value)} style={{ width:'100%', padding:'6px 8px', border:'1.5px solid rgba(0,0,0,0.1)', borderRadius:'7px', fontSize:'12px', fontFamily:'inherit', color:'#1a2e2b', background:'white', outline:'none', appearance:'none' }}>
                          {DELAY_OPTIONS.map(d=><option key={d}>{d}</option>)}
                        </select>
                      </div>
                    </div>

                    {/* Template picker */}
                    <button onClick={()=>setPickingTemplateFor(step.id)} style={{ width:'100%', padding:'8px 12px', background:tmpl?'rgba(99,102,241,0.06)':'white', border:`1.5px solid ${tmpl?'rgba(99,102,241,0.2)':'rgba(0,0,0,0.1)'}`, borderRadius:'8px', cursor:'pointer', fontFamily:'inherit', display:'flex', alignItems:'center', gap:'8px', textAlign:'left' }}>
                      <span style={{ fontSize:'14px' }}>{tc.icon}</span>
                      <div style={{ flex:1, minWidth:0 }}>
                        <p style={{ fontSize:'12px', fontWeight:tmpl?600:400, color:tmpl?'#6366f1':'#8a9e9a', overflow:'hidden', textOverflow:'ellipsis', whiteSpace:'nowrap' }}>
                          {tmpl ? tmpl.name : 'Tap to pick a template'}
                        </p>
                        {tmpl&&<p style={{ fontSize:'10px', color:'#8a9e9a', overflow:'hidden', textOverflow:'ellipsis', whiteSpace:'nowrap' }}>{tmpl.type==='email'&&tmpl.subject?tmpl.subject:tmpl.body.slice(0,45)+'...'}</p>}
                      </div>
                      <span style={{ fontSize:'11px', color:'#c8d8d4', flexShrink:0 }}>›</span>
                    </button>
                  </div>
                )
              })}
            </div>
          </div>
        </div>

        {/* Footer */}
        <div style={{ padding:'1rem 1.25rem', borderTop:'1px solid rgba(0,0,0,0.06)', display:'flex', gap:'10px', flexShrink:0 }}>
          <button onClick={onClose} style={{ flex:1, padding:'12px', background:'transparent', border:'1.5px solid rgba(0,0,0,0.1)', borderRadius:'10px', fontSize:'14px', fontFamily:'inherit', color:'#4a5e5a', cursor:'pointer' }}>Cancel</button>
          <button onClick={save} disabled={!canSave} style={{ flex:2, padding:'12px', background:canSave?'#1a2e2b':'#e5e7eb', border:'none', borderRadius:'10px', fontSize:'14px', fontFamily:'inherit', fontWeight:500, color:canSave?'white':'#9ca3af', cursor:canSave?'pointer':'not-allowed' }}>
            ✅ Save Path
          </button>
        </div>
      </div>

      {/* Template picker for step */}
      {pickingTemplateFor&&(
        <StepTemplatePicker
          step={steps.find(s=>s.id===pickingTemplateFor)}
          templates={templates}
          smsEnabled={smsEnabled}
          onSelect={tid=>assignTemplate(pickingTemplateFor, tid)}
          onClose={()=>setPickingTemplateFor(null)}
        />
      )}
    </div>
  )
}

// ─── Template Editor Popup ────────────────────────────────────────────────────
function TemplateEditorPopup({ template, isNew=false, isMasterEdit=false, defaultName='', defaultType=null, settings=null, onSave, onClose }) {
  // defaultName/defaultType pre-fill a brand-new template (e.g. the step
  // picker's inline "+ Create" affordance, which knows the typed name and the
  // step's type). Existing callers pass neither, so behavior is unchanged.
  const [name, setName]       = useState(template?.name || defaultName || '')
  const [type, setType]       = useState(template?.type || defaultType || 'email')
  const [subject, setSubject] = useState(template?.subject||'')
  const [body, setBody]       = useState(template?.body||'')
  const [tab, setTab]         = useState('edit') // 'edit' | 'preview'
  const textareaRef = useRef(null)

  function insertVariable(key) {
    const el = textareaRef.current
    if (!el) return
    const start = el.selectionStart, end = el.selectionEnd
    const newBody = body.slice(0,start) + key + body.slice(end)
    setBody(newBody)
    setTimeout(()=>{ el.focus(); el.setSelectionRange(start+key.length, start+key.length) }, 0)
  }

  // ONE substitution pipeline for every preview surface: the full 14-variable
  // send-time context from lib/preview-vars — never a hand-rolled subset.
  // Rendering itself is delegated to RenderedTemplatePreview below.
  const previewVars = buildPreviewVars(settings)

  const typeConf = { email:{icon:'📧',color:'#6366f1'}, sms:{icon:'💬',color:'#10b981'}, call:{icon:'📞',color:'#f59e0b'} }
  const tc = typeConf[type]

  return (
    <div style={{ position:'fixed', top:0, left:0, right:0, bottom:0, zIndex:10005, display:'flex', alignItems:'flex-end' }}>
      <div style={{ position:'absolute', inset:0, background:'rgba(26,46,43,0.5)' }} onClick={onClose} />
      <div style={{ position:'relative', background:'white', width:'100%', maxWidth:'540px', borderRadius:'16px', zIndex:1, height:'88vh', display:'flex', flexDirection:'column', boxShadow:'0 -8px 40px rgba(26,46,43,0.2)' }}>
        {/* Header */}
        <div style={{ padding:'0.75rem 1.25rem 0', borderBottom:'1px solid rgba(0,0,0,0.06)', flexShrink:0 }}>
          <div style={{ display:'flex', alignItems:'center', justifyContent:'space-between', marginBottom:'10px' }}>
            <h3 style={{ fontSize:'16px', fontFamily:'Georgia,serif', color:'#1a2e2b' }}>{isNew?'New Template': isMasterEdit?'Edit Master Template':'Customize Template'}</h3>
            <button onClick={onClose} style={{ background:'none', border:'none', fontSize:'20px', color:'#8a9e9a', cursor:'pointer' }}>×</button>
          </div>
          <div style={{ display:'flex', gap:'0' }}>
            {['edit','preview'].map(t=>(
              <button key={t} onClick={()=>setTab(t)} style={{ flex:1, padding:'8px', border:'none', cursor:'pointer', fontFamily:'inherit', fontSize:'13px', fontWeight:tab===t?600:400, background:'transparent', color:tab===t?'#1a2e2b':'#8a9e9a', borderBottom:`2px solid ${tab===t?'#a8c9c4':'transparent'}` }}>
                {t==='edit'?'Edit':'Preview'}
              </button>
            ))}
          </div>
        </div>

        {isMasterEdit&&(
          <div style={{ margin:'12px 16px 0', padding:'8px 12px', background:'rgba(212,160,70,0.08)', border:'1px solid rgba(212,160,70,0.25)', borderRadius:'9px', display:'flex', gap:'8px', alignItems:'flex-start' }}>
            <span style={{ fontSize:'14px' }}>⚠️</span>
            <p style={{ fontSize:'11px', color:'#c8a050', lineHeight:1.5 }}>You're editing a <strong>master template</strong>. Changes become the new default for all locations that haven't customized their copy.</p>
          </div>
        )}

        <div style={{ flex:1, overflowY:'auto', padding:'1rem 1.25rem', display:'grid', gap:'12px' }}>
          {tab==='edit'&&(
            <>
              {/* Name */}
              <div>
                <label style={{ fontSize:'11px', fontWeight:600, color:'#4a5e5a', textTransform:'uppercase', letterSpacing:'0.5px', display:'block', marginBottom:'5px' }}>Template Name</label>
                <input value={name} onChange={e=>setName(e.target.value)} placeholder='e.g. Welcome Email' style={{ width:'100%', padding:'10px 12px', border:'1.5px solid rgba(0,0,0,0.1)', borderRadius:'8px', fontSize:'16px', fontFamily:'inherit', color:'#1a2e2b', outline:'none', boxSizing:'border-box' }} />
              </div>

              {/* Type */}
              <div>
                <label style={{ fontSize:'11px', fontWeight:600, color:'#4a5e5a', textTransform:'uppercase', letterSpacing:'0.5px', display:'block', marginBottom:'5px' }}>Type</label>
                {/* SMS is not offerable while it cannot send (issue 240 step
                    6). The picker used to list it unconditionally, so an owner
                    could open this from the unlocked Call Scripts section,
                    choose SMS, and save — POST /api/templates has no add-on
                    gate, so the row persisted. It then rendered only inside
                    the locked Text Templates accordion, where it could not be
                    edited or deleted. Step 6 removes that accordion, which
                    would have made such a row invisible outright, so the trap
                    is closed at the door instead. */}
                <div style={{ display:'grid', gridTemplateColumns:(settings?.location?.smsEnabled ? '1fr 1fr 1fr' : '1fr 1fr'), gap:'8px', maxWidth:CONTROL_W.field }}>
                  {[['email','📧','Email'],['sms','💬','SMS'],['call','📞','Call Script']]
                    .filter(([v])=> v!=='sms' || settings?.location?.smsEnabled)
                    .map(([v,icon,label])=>(
                    <button key={v} onClick={()=>setType(v)} style={{ padding:'10px', borderRadius:'9px', cursor:'pointer', border:'2px solid', borderColor:type===v?typeConf[v].color:'rgba(0,0,0,0.08)', background:type===v?`${typeConf[v].color}12`:'white', fontFamily:'inherit', display:'flex', flexDirection:'column', alignItems:'center', gap:'4px' }}>
                      <span style={{ fontSize:'18px' }}>{icon}</span>
                      <span style={{ fontSize:'11px', fontWeight:type===v?600:400, color:type===v?typeConf[v].color:'#4a5e5a' }}>{label}</span>
                    </button>
                  ))}
                </div>
              </div>

              {/* Subject (email only) */}
              {type==='email'&&(
                <div>
                  <label style={{ fontSize:'11px', fontWeight:600, color:'#4a5e5a', textTransform:'uppercase', letterSpacing:'0.5px', display:'block', marginBottom:'5px' }}>Subject Line</label>
                  <input value={subject} onChange={e=>setSubject(e.target.value)} placeholder='e.g. Welcome, {{first_name}} 🐝' style={{ width:'100%', padding:'10px 12px', border:'1.5px solid rgba(0,0,0,0.1)', borderRadius:'8px', fontSize:'16px', fontFamily:'inherit', color:'#1a2e2b', outline:'none', boxSizing:'border-box' }} />
                </div>
              )}

              {/* Variables */}
              <div>
                <label style={{ fontSize:'11px', fontWeight:600, color:'#4a5e5a', textTransform:'uppercase', letterSpacing:'0.5px', display:'block', marginBottom:'6px' }}>Insert Variable</label>
                <div style={{ display:'flex', gap:'5px', flexWrap:'wrap' }}>
                  {TEMPLATE_VARIABLES.map(v=>(
                    <button key={v.key} onClick={()=>insertVariable(v.key)} style={{ padding:'4px 9px', borderRadius:'20px', cursor:'pointer', border:'1px solid rgba(99,102,241,0.25)', background:'rgba(99,102,241,0.06)', fontSize:'11px', fontFamily:'inherit', color:'#6366f1', fontWeight:500 }}>
                      {v.label}
                    </button>
                  ))}
                </div>
              </div>

              {/* Body */}
              <div>
                <label style={{ fontSize:'11px', fontWeight:600, color:'#4a5e5a', textTransform:'uppercase', letterSpacing:'0.5px', display:'block', marginBottom:'5px' }}>
                  {type==='call'?'Script / Notes':'Message Body'}
                </label>
                <textarea
                  ref={textareaRef}
                  value={body}
                  onChange={e=>setBody(e.target.value)}
                  placeholder={type==='sms'?'Keep it brief and friendly...':type==='call'?'Write your call script or talking points...':'Write your email body here...'}
                  style={{ width:'100%', padding:'10px 12px', border:'1.5px solid rgba(0,0,0,0.1)', borderRadius:'8px', fontSize:'13px', fontFamily:'inherit', color:'#1a2e2b', outline:'none', boxSizing:'border-box', height:type==='sms'?'100px':'200px', resize:'vertical', lineHeight:1.6 }}
                />
                <p style={{ fontSize:'11px', color:'#b0c0bc', marginTop:'4px' }}>{body.length} chars{type==='sms'&&body.length>160?<span style={{ color:'#f59e0b' }}> · exceeds 1 SMS</span>:''}</p>
              </div>
            </>
          )}

          {tab==='preview'&&(
            <div>
              <div style={{ padding:'8px 12px', background:'rgba(99,102,241,0.06)', border:'1px solid rgba(99,102,241,0.12)', borderRadius:'8px', marginBottom:'12px', fontSize:'11px', color:'#6366f1' }}>
                Previewing with sample values — <strong>{previewVars.first_name}</strong> · {previewVars.location_name}. Every variable renders the way a real send fills it.
              </div>
              <div style={{ background:'white', borderRadius:'10px', overflow:'hidden', border:'1px solid rgba(0,0,0,0.08)' }}>
                <RenderedTemplatePreview type={type} subject={subject} body={body} settings={settings} />
              </div>
            </div>
          )}
        </div>

        {/* Footer */}
        <div style={{ padding:'1rem 1.25rem', borderTop:'1px solid rgba(0,0,0,0.06)', display:'flex', gap:'10px', flexShrink:0 }}>
          <button onClick={onClose} style={{ flex:1, padding:'12px', background:'transparent', border:'1.5px solid rgba(0,0,0,0.1)', borderRadius:'10px', fontSize:'14px', fontFamily:'inherit', color:'#4a5e5a', cursor:'pointer' }}>Cancel</button>
          <button onClick={()=>name.trim()&&body.trim()&&onSave({ name, type, subject, body })} disabled={!name.trim()||!body.trim()} style={{ flex:2, padding:'12px', background:name.trim()&&body.trim()?'#1a2e2b':'#e5e7eb', border:'none', borderRadius:'10px', fontSize:'14px', fontFamily:'inherit', fontWeight:500, color:name.trim()&&body.trim()?'white':'#9ca3af', cursor:name.trim()&&body.trim()?'pointer':'not-allowed' }}>
            Save Template
          </button>
        </div>
      </div>
    </div>
  )
}

// ─── Template Editor Popup ────────────────────────────────────────────────────

// ─── Rendered preview (shared) ────────────────────────────────────────────────
// THE one rendered-preview body. Every surface that shows an owner what an
// email/text/script will look like mounts this — TemplatePreviewModal, the
// TemplateEditorPopup preview tab, and TemplateQuickPeekModal — so the
// substitution pipeline (lib/preview-vars, all 14 send-time variables) can
// never drift between preview surfaces, or between preview and send.
function RenderedTemplatePreview({ type='email', subject, body, settings=null, viewMode='desktop' }) {
  const vars = buildPreviewVars(settings)
  const subj = applyPreviewVars(subject || '', vars)
  const rendered = applyPreviewVars(body || '', vars)
  const locName = vars.location_name
  const fromName = settings?.location?.sendFromName || `Bee Organized ${locName}`
  const fromEmail = settings?.location?.sendFromEmail || 'hello@beeorganized.com'

  if (type === 'sms') return (
    <div style={{ maxWidth:'320px', margin:'0 auto' }}>
      <div style={{ background:'#1a2e2b', borderRadius:'12px', padding:'10px 14px', marginLeft:'20%' }}>
        <p style={{ fontSize:'14px', color:'white', lineHeight:1.6, whiteSpace:'pre-wrap' }}>{rendered || '...'}</p>
      </div>
      <p style={{ fontSize:'10px', color:'#8a9e9a', textAlign:'right', marginTop:'4px' }}>Delivered · {fromName}</p>
    </div>
  )

  if (type === 'call') return (
    <div style={{ background:'white', borderRadius:'12px', padding:'12px', maxWidth:'480px', margin:'0 auto', border:'1px solid rgba(0,0,0,0.06)' }}>
      <div style={{ display:'flex', alignItems:'center', gap:'8px', marginBottom:'12px', paddingBottom:'10px', borderBottom:'1px solid rgba(0,0,0,0.06)' }}>
        <span style={{ fontSize:'20px' }}>📞</span>
        <p style={{ fontSize:'13px', fontWeight:700, color:'#1a2e2b' }}>Call Script</p>
      </div>
      <p style={{ fontSize:'13px', color:'#374151', lineHeight:1.8, whiteSpace:'pre-wrap' }}>{rendered || ''}</p>
    </div>
  )

  if (viewMode === 'text') return (
    <div style={{ background:'white', borderRadius:'12px', padding:'12px', maxWidth:'480px', margin:'0 auto' }}>
      {subj && <p style={{ fontSize:'14px', fontWeight:700, color:'#1a2e2b', marginBottom:'12px', paddingBottom:'10px', borderBottom:'1px solid rgba(0,0,0,0.06)' }}>Subject: {subj}</p>}
      <p style={{ fontSize:'13px', color:'#374151', lineHeight:1.8, whiteSpace:'pre-wrap', fontFamily:'monospace' }}>{rendered}</p>
    </div>
  )

  // Email frame — desktop/mobile width is the caller's container concern.
  return (
    <div style={{ fontFamily:'Georgia,serif', maxWidth:'520px', margin:'0 auto', background:'white' }}>
      <div style={{ background:'#1a2e2b', padding:'20px 24px', textAlign:'center' }}>
        <p style={{ color:'rgba(168,201,196,0.7)', fontSize:'11px', letterSpacing:'1px', textTransform:'uppercase', marginBottom:'4px' }}>Bee Organized</p>
        <p style={{ color:'white', fontSize:'18px', margin:0 }}>🐝</p>
      </div>
      <div style={{ padding:'28px 24px' }}>
        {subj && <p style={{ fontSize:'20px', fontWeight:700, color:'#1a2e2b', marginBottom:'18px' }}>{subj}</p>}
        <p style={{ fontSize:'14px', lineHeight:1.7, color:'#374151', whiteSpace:'pre-wrap' }}>{rendered}</p>
      </div>
      <div style={{ background:'#f7f5f0', padding:'16px 24px', borderTop:'1px solid #e5e7eb', textAlign:'center' }}>
        <p style={{ fontSize:'11px', color:'#8a9e9a', marginBottom:'4px' }}>{fromName} · {locName}</p>
        <p style={{ fontSize:'10px', color:'#b0c0bc' }}>This email was sent from {fromEmail}</p>
        <p style={{ fontSize:'10px', color:'#b0c0bc', marginTop:'4px' }}>Unsubscribe · View in browser</p>
      </div>
    </div>
  )
}

// Shared quick-peek preview — like a macOS file thumbnail. Shows a template's
// subject + body without committing a selection, rendered through the shared
// RenderedTemplatePreview (all 14 send-time variables filled with the
// location's real values / labelled samples). Used by both the
// StepTemplatePicker (showSelectButton=true, so the peek can commit a choice)
// and the Settings → Communications overview (showSelectButton=false, Close-only).
// Pass template=null to keep it closed.
function TemplateQuickPeekModal({ template, settings=null, showSelectButton=false, onSelect, onClose }) {
  if (!template) return null
  return (
    <div style={{ position:'fixed', inset:0, zIndex:10006, display:'flex', alignItems:'center', justifyContent:'center', padding:'14px' }}>
      <div style={{ position:'absolute', inset:0, background:'rgba(26,46,43,0.5)' }} onClick={onClose} />
      <div style={{ position:'relative', background:'white', width:'100%', maxWidth:'560px', maxHeight:'85vh', borderRadius:'14px', display:'flex', flexDirection:'column', zIndex:1, boxShadow:'0 8px 40px rgba(26,46,43,0.3)', overflow:'hidden' }}>
        <div style={{ padding:'14px 16px', borderBottom:'1px solid rgba(0,0,0,0.06)', display:'flex', alignItems:'center', gap:'8px', flexShrink:0 }}>
          <span style={{ fontSize:'16px' }}>{template.type==='email'?'📧':template.type==='sms'?'💬':'📞'}</span>
          <div style={{ flex:1, minWidth:0 }}>
            <p style={{ fontSize:'14px', fontWeight:700, color:'#1a2e2b', fontFamily:'Georgia,serif' }}>{template.name}</p>
            <p style={{ fontSize:'10px', color:'#8a9e9a' }}>Preview · variables filled the way a real send fills them</p>
          </div>
          <button onClick={onClose} style={{ background:'none', border:'none', fontSize:'20px', color:'#8a9e9a', cursor:'pointer', lineHeight:1 }}>×</button>
        </div>
        <div style={{ padding:'16px', overflowY:'auto', flex:1, background:'#f3f4f6' }}>
          <div style={{ background:'white', borderRadius:'12px', overflow:'hidden', boxShadow:'0 2px 12px rgba(0,0,0,0.08)' }}>
            <RenderedTemplatePreview type={template.type} subject={template.subject} body={template.body} settings={settings} />
          </div>
        </div>
        <div style={{ padding:'12px 16px', borderTop:'1px solid rgba(0,0,0,0.06)', display:'flex', gap:'8px', justifyContent:'flex-end', flexShrink:0 }}>
          <button onClick={onClose} style={{ padding:'8px 16px', background:'transparent', border:'1px solid rgba(0,0,0,0.1)', borderRadius:'8px', fontSize:'12px', fontFamily:'inherit', color:'#8a9e9a', cursor:'pointer' }}>Close</button>
          {showSelectButton && (
            <button onClick={()=>{ onSelect && onSelect(template.id) }} style={{ padding:'8px 16px', background:'#1a2e2b', border:'none', borderRadius:'8px', fontSize:'12px', fontFamily:'inherit', fontWeight:600, color:'white', cursor:'pointer' }}>Select this {template.type==='email'?'email':template.type==='sms'?'text':'template'}</button>
          )}
        </div>
      </div>
    </div>
  )
}

function StepTemplatePicker({ step, templates, onSelect, onClose, smsEnabled=true, onCreateTemplate=null }) {
  const [search, setSearch] = useState('')
  // Template being peeked at in the preview modal (does NOT commit a selection).
  const [previewTmpl, setPreviewTmpl] = useState(null)
  // When set, the inline "+ Create new template" editor is open. Holds the
  // name to pre-fill. Only reachable when onCreateTemplate is provided.
  const [creatingName, setCreatingName] = useState(null)
  // isActive gates the quarantine: a template flipped dark (the 17 Gen 1
  // prototype rows) stays resolvable for steps that already point at it, but
  // can never be newly assigned. `step.templateId===t.id` is kept visible so an
  // existing assignment still renders as "✓ Current" rather than vanishing.
  const compatible = templates.filter(t =>
    t.type === step.type &&
    (t.isActive || step.templateId === t.id) &&
    (smsEnabled || t.type !== 'sms') &&
    (!search || t.name.toLowerCase().includes(search.toLowerCase()))
  )
  // Show the inline create affordance only when the user has typed a name that
  // doesn't already exist (case-insensitive) among the step's compatible
  // templates. Mirrors the referrer picker's inline "+ Create X" pattern.
  const trimmedSearch = search.trim()
  const exactMatch = trimmedSearch !== '' && compatible.some(t => t.name.toLowerCase() === trimmedSearch.toLowerCase())
  const showCreateRow = !!onCreateTemplate && trimmedSearch !== '' && !exactMatch
  // Split into Master Templates vs My Templates so owners can clearly see
  // what's HQ-provided vs. their own customs. Falls back to a single group
  // when neither flag is present (legacy state from DEFAULT_TEMPLATES seed).
  const masters = compatible.filter(t => t.isMaster)
  const myTemplates = compatible.filter(t => t.isOwnCustom)
  const unflagged = compatible.filter(t => !t.isMaster && !t.isOwnCustom)

  // Row is a div (not a button) so the inline Preview button can nest legally.
  function renderRow(t) {
    return (
      <div key={t.dbId || t.id} onClick={()=>onSelect(t.id)} style={{ position:'relative', padding:'12px 14px', background:step.templateId===t.id?'rgba(168,201,196,0.12)':'white', border:`1.5px solid ${step.templateId===t.id?'#a8c9c4':'rgba(0,0,0,0.08)'}`, borderRadius:'10px', cursor:'pointer', fontFamily:'inherit', textAlign:'left' }}>
        <div style={{ display:'flex', alignItems:'center', gap:'8px', marginBottom:'3px' }}>
          <span style={{ fontSize:'14px' }}>{t.type==='email'?'📧':t.type==='sms'?'💬':'📞'}</span>
          <span style={{ fontSize:'13px', fontWeight:600, color:'#1a2e2b' }}>{t.name}</span>
          <div style={{ marginLeft:'auto', display:'flex', alignItems:'center', gap:'8px' }}>
            {step.templateId===t.id&&<span style={{ color:'#a8c9c4' }}>✓ Current</span>}
            <button
              onClick={(e)=>{ e.stopPropagation(); setPreviewTmpl(t) }}
              title="Preview this email"
              style={{ display:'flex', alignItems:'center', gap:'3px', padding:'3px 8px', background:'rgba(99,102,241,0.08)', border:'1px solid rgba(99,102,241,0.2)', borderRadius:'6px', fontSize:'11px', fontWeight:600, fontFamily:'inherit', color:'#6366f1', cursor:'pointer' }}>
              👁 Preview
            </button>
          </div>
        </div>
        <p style={{ fontSize:'12px', color:'#8a9e9a', marginLeft:'22px', overflow:'hidden', textOverflow:'ellipsis', whiteSpace:'nowrap' }}>
          {t.type==='email'&&t.subject?t.subject:(t.body||'').slice(0,60)+'...'}
        </p>
      </div>
    )
  }

  function renderGroupLabel(label) {
    return (
      <p style={{ fontSize:'10px', fontWeight:700, color:'#8a9e9a', textTransform:'uppercase', letterSpacing:'0.6px', padding:'8px 4px 4px' }}>{label}</p>
    )
  }

  return (
    <div style={{ position:'fixed', inset:0, zIndex:10004, display:'flex', alignItems:'center', justifyContent:'center', padding:'16px' }}>
      <div style={{ position:'absolute', inset:0, background:'rgba(26,46,43,0.45)' }} onClick={onClose} />
      <div onClick={e=>e.stopPropagation()} style={{ position:'relative', background:'white', width:'100%', maxWidth:'520px', maxHeight:'85vh', borderRadius:'16px', zIndex:1, display:'flex', flexDirection:'column', boxShadow:'0 20px 60px rgba(26,46,43,0.25)', boxSizing:'border-box', overflow:'hidden' }}>
        <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center', padding:'20px 24px', borderBottom:'1px solid #eee', flexShrink:0 }}>
          <h3 style={{ fontSize:'18px', fontFamily:'Georgia,serif', color:'#1a2e2b' }}>Pick Template</h3>
          <button onClick={onClose} style={{ background:'none', border:'none', fontSize:'22px', color:'#8a9e9a', cursor:'pointer' }}>×</button>
        </div>
        <div style={{ flex:1, overflowY:'auto', padding:'16px 24px', display:'flex', flexDirection:'column' }}>
          <input value={search} onChange={e=>setSearch(e.target.value)} placeholder='Search templates...' style={{ width:'100%', padding:'9px 12px', border:'1.5px solid rgba(0,0,0,0.09)', borderRadius:'9px', fontSize:'13px', fontFamily:'inherit', color:'#1a2e2b', outline:'none', boxSizing:'border-box', marginBottom:'10px', flexShrink:0 }} />
          {compatible.length===0 && <p style={{ fontSize:'13px', color:'#8a9e9a', textAlign:'center', padding:'1rem' }}>No {step.type} templates found</p>}
          {masters.length > 0 && (
            <>
              {renderGroupLabel('📚 Master Templates')}
              <div style={{ display:'grid', gap:'6px' }}>{masters.map(renderRow)}</div>
            </>
          )}
          {myTemplates.length > 0 && (
            <>
              {renderGroupLabel('✏️ My Templates')}
              <div style={{ display:'grid', gap:'6px' }}>{myTemplates.map(renderRow)}</div>
            </>
          )}
          {unflagged.length > 0 && masters.length === 0 && myTemplates.length === 0 && (
            <div style={{ display:'grid', gap:'6px' }}>{unflagged.map(renderRow)}</div>
          )}
          {/* Inline create affordance — mirrors the referrer picker's "+ Create X"
              row. Appears at the bottom of the results when the typed name isn't
              already a compatible template. Opens the template editor pre-filled
              with the typed name + the step's type; on save the new template is
              auto-selected and the picker closes. */}
          {showCreateRow && (
            <button
              type="button"
              onClick={()=>setCreatingName(trimmedSearch)}
              style={{ display:'flex', alignItems:'center', gap:'8px', width:'100%', marginTop:'8px', padding:'10px 14px', background:'rgba(168,201,196,0.08)', border:'1px solid rgba(168,201,196,0.3)', borderRadius:'10px', cursor:'pointer', fontFamily:'inherit', textAlign:'left' }}>
              <span style={{ fontSize:'14px', color:'#1a7a6e' }}>＋</span>
              <div style={{ minWidth:0 }}>
                <p style={{ fontSize:'12px', fontWeight:600, color:'#1a2e2b', overflow:'hidden', textOverflow:'ellipsis', whiteSpace:'nowrap' }}>Create new template “{trimmedSearch}”</p>
                <p style={{ fontSize:'11px', color:'#8a9e9a' }}>Add as a new {step.type==='sms'?'text':step.type} template</p>
              </div>
            </button>
          )}
        </div>
      </div>

      {/* Quick-peek preview (shared) — peeking does NOT commit a selection;
          the modal's "Select this …" button does, via onSelect. */}
      <TemplateQuickPeekModal
        template={previewTmpl}
        showSelectButton
        onSelect={(id)=>{ setPreviewTmpl(null); onSelect(id) }}
        onClose={()=>setPreviewTmpl(null)}
      />

      {/* Inline new-template editor. onCreateTemplate persists the template and
          returns its id; we then auto-select it (which closes the picker). */}
      {creatingName!==null && onCreateTemplate && (
        <TemplateEditorPopup
          template={null}
          isNew
          defaultName={creatingName}
          defaultType={step.type}
          onSave={async(data)=>{
            const newId = await onCreateTemplate(data)
            setCreatingName(null)
            if (newId) onSelect(newId)
          }}
          onClose={()=>setCreatingName(null)}
        />
      )}
    </div>
  )
}

