const FRANCHISE_ROLES = [
  { key:'owner',    label:'Zee Bee',       icon:'👑', color:'#d4a046', bg:'rgba(212,160,70,0.1)',  desc:'Full access — billing, settings, Jobber'  },
  { key:'manager',  label:'Hive Manager',  icon:'🍯', color:'#6366f1', bg:'rgba(99,102,241,0.1)',  desc:'Operational lead — no billing or Jobber'  },
  { key:'light',    label:'Worker Bee',    icon:'🐝', color:'#10b981', bg:'rgba(16,185,129,0.1)',  desc:'Front office — intake, scheduling, customer service'  },
  { key:'readonly', label:'Honey Watcher', icon:'👁',  color:'#8a9e9a', bg:'rgba(138,158,154,0.1)', desc:'Read-only — accountants, advisors'  },
]

// Restored from compiled BeeHub.js (commits a8690d2/5cf57aa/a3eb93c).
// Phase 0 cleanup deleted the .js artifact; those commits had only modified
// it, never BeeHub.jsx, so their work was lost. Translated from
// React.createElement back to JSX.
// Tier display metadata — keys mirror tier ids in the Supabase tier_prices table
// (and DEFAULT_TIER_PRICES in lib/subscription-math.ts). Kept colocated with
// TierPlansInline so seat icons/colors stay consistent.
const SUBSCRIPTION_TIER_META = [
  { key:'owner',    name:'Zee Bee',       icon:'👑', color:'#d4a046', detail:'Required · Up to 2 per location' },
  { key:'manager',  name:'Hive Manager',  icon:'🍯', color:'#6366f1', detail:'Operations & team leads' },
  { key:'light',    name:'Worker Bee',    icon:'🐝', color:'#10b981', detail:'Schedulers, customer service' },
  { key:'readonly', name:'Honey Watcher', icon:'👁',  color:'#8a9e9a', detail:'Read-only · Add as many as needed' },
]

// Worker Bee (light, $200/yr) is deferred — identical lite_user permissions to
// Honey Watcher ($50/yr) makes two read-only tiers at different prices confusing.
// Watcher is the live read-only option. Add 'light' back here to re-enable.
// The set + helper keeps all call sites untouched; 503 backstops in invite routes.
const DEFERRED_TIER_KEYS = new Set(['light'])
function isDeferredTier(key) { return DEFERRED_TIER_KEYS.has(key) }

// issue 161: open the Stripe Billing Portal for owner self-service (cards,
// invoices, cancellation). One POST → one hosted portal session; Bee Hub
// builds no billing UI for those. Pre-opens a blank tab so the async fetch
// doesn't trip the popup blocker, and closes it on any non-URL outcome.
async function openStripeBillingPortal(locationId) {
  if (!locationId) return
  const w = typeof window !== 'undefined' ? window.open('', '_blank', 'noopener') : null
  try {
    const res = await fetch(`/api/locations/${locationId}/billing-portal`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: '{}',
    })
    const j = await res.json().catch(() => ({}))
    if (res.ok && j?.url) {
      if (w) w.location.href = j.url
      else if (typeof window !== 'undefined') window.location.href = j.url
      return
    }
    if (w) w.close()
    if (typeof window !== 'undefined') {
      window.alert(
        j?.error === 'no_stripe_customer'
          ? 'The billing portal opens once your subscription is set up in Stripe.'
          : 'Could not open the billing portal right now. Please try again.',
      )
    }
  } catch {
    if (w) w.close()
    if (typeof window !== 'undefined') {
      window.alert('Could not open the billing portal right now. Please try again.')
    }
  }
}

function SubscriptionCalculator({
  initialSeats = [{ tier:'owner', count:1 }],
  paymentSource = 'direct',
  showSeatControls = true,
  onSeatsChange = null,
}) {
  const tierPricesCtx = useContext(TierPricesContext)
  const getTierPrice = tierPricesCtx?.getTierPrice ?? (() => 0)
  const livePrices = tierPricesCtx?.livePrices ?? DEFAULT_TIER_PRICES
  // 'none' is the DB default for locations corporate hasn't classified yet.
  // Treat as 'direct' (self-pay) for display purposes.
  const normalizedSource =
    paymentSource === 'prepaid_corporate' || paymentSource === 'corporate_sponsored'
      ? paymentSource
      : 'direct'

  const [seats, setSeats] = useState(initialSeats)

  // When parent's initialSeats changes (e.g. location switch in display-only
  // mode), sync local state. Skip for interactive mode — user edits are
  // authoritative there.
  const seatsKey = JSON.stringify(initialSeats)
  useEffect(() => {
    if (!showSeatControls) setSeats(initialSeats)
  }, [seatsKey, showSeatControls])

  const display = getSubscriptionDisplay(normalizedSource, seats, new Date(), livePrices)

  // Co-owner rule (2nd Zee Bee at Hive Manager rate) lives in calculateSeatTotal,
  // so display.annual / .dueToday already reflect it. Owner seats capped at 2 —
  // one primary owner + one co-owner.
  const SEAT_MAX = (tier) => tier === 'owner' ? 2 : 99
  const managerPrice = getTierPrice('manager')
  const effectiveAnnual = display.annual
  // issue 162: new-location signup pays a full year — "due today" is the full
  // annual (no proration), and the renewal is the signup anniversary.
  const effectiveDueToday = display.dueToday

  function adjustSeat(tier, delta) {
    // Deferred tiers (Worker Bee, Honey Watcher) are locked at 0 — buttons are
    // already disabled in the UI, this is a defense-in-depth backstop.
    if (isDeferredTier(tier)) return
    setSeats(prev => {
      const idx = prev.findIndex(s => s.tier === tier)
      const current = idx >= 0 ? prev[idx].count : 0
      const min = tier === 'owner' ? 1 : 0
      const max = SEAT_MAX(tier)
      const next = Math.max(min, Math.min(max, current + delta))
      if (next === current) return prev
      let nextSeats
      if (idx >= 0) {
        nextSeats = prev.map((s, i) => i === idx ? { ...s, count: next } : s)
      } else {
        nextSeats = [...prev, { tier, count: next }]
      }
      if (onSeatsChange) onSeatsChange(nextSeats)
      return nextSeats
    })
  }

  function getCount(tier) {
    const found = seats.find(s => s.tier === tier)
    return found?.count || 0
  }

  const renewalLabel = formatRenewalDate(display.renewalDate)

  // Header headline number depends on mode:
  // - direct: full annual they pay today (issue 162 — no proration at signup)
  // - prepaid: $0 today, annual is informational
  // - sponsored: $0 today, no math shown
  const heroNumber =
    display.mode === 'direct'
      ? formatCurrency(effectiveDueToday)
      : formatCurrency(0)

  const heroSub =
    display.mode === 'direct'
      ? `Full year · renews ${renewalLabel}`
      : display.mode === 'prepaid'
        ? `Prepaid through ${renewalLabel}`
        : 'Sponsored by corporate during testing'

  const costSummaryCard = (
    <div style={{ borderRadius:'14px', overflow:'hidden', boxShadow:'0 2px 16px rgba(26,46,43,0.08)', border:'1px solid rgba(168,201,196,0.2)' }}>
      <div style={{ background:'linear-gradient(135deg,#1a2e2b,#2a4a40)', padding:'16px 18px', color:'white' }}>
        <p style={{ fontSize:'10.5px', color:'rgba(168,201,196,0.65)', textTransform:'uppercase', letterSpacing:'0.6px', marginBottom:'6px', fontWeight:600 }}>
          {display.mode === 'direct' ? 'Due Today' : display.mode === 'prepaid' ? 'Due Today (Prepaid)' : 'Due Today (Sponsored)'}
        </p>
        <p style={{ fontSize:'34px', fontWeight:700, fontFamily:'Georgia,serif', lineHeight:1, marginBottom:'6px' }}>
          {heroNumber}
        </p>
        <p style={{ fontSize:'12px', color:'rgba(168,201,196,0.85)' }}>
          {heroSub}
        </p>
      </div>

      {/* Detail breakdown */}
      <div style={{ background:'white', padding:'14px 16px' }}>
        <p style={{ fontSize:'10px', fontWeight:700, color:'#8a9e9a', textTransform:'uppercase', letterSpacing:'0.6px', marginBottom:'8px' }}>
          Breakdown
        </p>
        <div style={{ display:'grid', gap:'6px', marginBottom:'10px' }}>
          {SUBSCRIPTION_TIER_META.map(t => {
            const count = getCount(t.key)
            if (count <= 0) return null
            const price = getTierPrice(t.key)
            // Co-owner rule: render the Zee Bee row as two lines when count≥2 —
            // primary at owner rate + extras at Hive Manager rate.
            if (t.key === 'owner' && count >= 2) {
              const primarySub = price
              const extraCount = count - 1
              const extraSub = extraCount * managerPrice
              return (
                <React.Fragment key={t.key}>
                  <div style={{ display:'flex', alignItems:'baseline', gap:'6px', fontSize:'12.5px', color:'#4a5e5a' }}>
                    <span style={{ fontSize:'13px', lineHeight:1 }}>{t.icon}</span>
                    <span style={{ flex:1 }}>
                      1 {t.name} × {formatCurrency(price, { showCents:'never' })}/yr
                    </span>
                    <span style={{ fontWeight:600, color:'#1a2e2b', fontFamily:'Georgia,serif' }}>
                      {formatCurrency(primarySub, { showCents:'never' })}
                    </span>
                  </div>
                  <div style={{ display:'flex', alignItems:'baseline', gap:'6px', fontSize:'12px', color:'#8a9e9a', paddingLeft:'19px' }}>
                    <span style={{ flex:1 }}>
                      + {extraCount} co-owner {t.name}{extraCount !== 1 ? 's' : ''} × {formatCurrency(managerPrice, { showCents:'never' })}/yr
                    </span>
                    <span style={{ fontWeight:600, color:'#1a2e2b', fontFamily:'Georgia,serif' }}>
                      {formatCurrency(extraSub, { showCents:'never' })}
                    </span>
                  </div>
                </React.Fragment>
              )
            }
            const subtotal = price * count
            return (
              <div key={t.key} style={{ display:'flex', alignItems:'baseline', gap:'6px', fontSize:'12.5px', color:'#4a5e5a' }}>
                <span style={{ fontSize:'13px', lineHeight:1 }}>{t.icon}</span>
                <span style={{ flex:1 }}>
                  {count} {t.name}{count !== 1 ? 's' : ''} × {formatCurrency(price, { showCents:'never' })}/yr
                </span>
                <span style={{ fontWeight:600, color:'#1a2e2b', fontFamily:'Georgia,serif' }}>
                  {formatCurrency(subtotal, { showCents:'never' })}
                </span>
              </div>
            )
          })}
        </div>
        <div style={{ borderTop:'1px solid rgba(0,0,0,0.08)', paddingTop:'8px', display:'flex', justifyContent:'space-between', alignItems:'baseline', marginBottom:'6px' }}>
          <span style={{ fontSize:'12px', color:'#4a5e5a', fontWeight:600 }}>Annual total</span>
          <span style={{ fontSize:'15px', fontWeight:700, color:'#1a2e2b', fontFamily:'Georgia,serif' }}>
            {formatCurrency(effectiveAnnual, { showCents:'never' })}
          </span>
        </div>
        {display.mode === 'direct' && (
          <>
            <div style={{ display:'flex', justifyContent:'space-between', alignItems:'baseline', padding:'6px 8px', background:'rgba(212,160,70,0.08)', border:'1px solid rgba(212,160,70,0.2)', borderRadius:'8px', marginBottom:'8px' }}>
              <span style={{ fontSize:'11px', color:'#b88820', fontWeight:600 }}>
                Full year today
              </span>
              <span style={{ fontSize:'13.5px', fontWeight:700, color:'#1a2e2b', fontFamily:'Georgia,serif' }}>
                {formatCurrency(effectiveDueToday, { showCents:'never' })}
              </span>
            </div>
            <p style={{ fontSize:'11px', color:'#8a9e9a', textAlign:'center' }}>
              Renews {renewalLabel} at {formatCurrency(effectiveAnnual, { showCents:'never' })}/year
            </p>
          </>
        )}
        {display.mode === 'prepaid' && (
          <p style={{ fontSize:'11px', color:'#4a5e5a', padding:'8px 10px', background:'rgba(99,102,241,0.06)', border:'1px solid rgba(99,102,241,0.2)', borderRadius:'8px' }}>
            Prepaid by corporate through {renewalLabel}. No charge today.
          </p>
        )}
        {display.mode === 'sponsored' && (
          <>
            <p style={{ fontSize:'11px', color:'#4a5e5a', padding:'8px 10px', background:'rgba(16,185,129,0.06)', border:'1px solid rgba(16,185,129,0.2)', borderRadius:'8px' }}>
              Corporate-sponsored during testing period. No charge today.
            </p>
            <div style={{ background:'#fef3c7', border:'1px solid #f59e0b', borderRadius:'8px', padding:'12px 14px', marginTop:'12px', fontSize:'13px', color:'#78350f', lineHeight:1.5 }}>
              {/* issue 162: renewal anchors to the location's own conversion
                  date, not a fleet-wide March 1. */}
              <strong>⚠️ Important:</strong> When testing concludes, you'll be responsible for a prorated subscription fee from that date through the end of your first paid year. Your annual renewal continues on that anniversary thereafter.
            </div>
          </>
        )}
      </div>
    </div>
  )

  const seatConfigBlock = showSeatControls && (
    <div style={{ background:'white', borderRadius:'14px', border:'1px solid rgba(0,0,0,0.08)', overflow:'hidden' }}>
      <div style={{ padding:'12px 14px', borderBottom:'1px solid rgba(0,0,0,0.06)', background:'rgba(26,46,43,0.03)' }}>
        <p style={{ fontSize:'10px', fontWeight:700, color:'#8a9e9a', textTransform:'uppercase', letterSpacing:'0.6px' }}>
          Configure Seats
        </p>
      </div>
      <div style={{ display:'grid' }}>
        {SUBSCRIPTION_TIER_META.map(t => {
          const deferred = isDeferredTier(t.key)
          const count = getCount(t.key)
          const price = getTierPrice(t.key)
          // Co-owner rule reflected in row subtotal: 1st at owner rate, 2nd at manager rate.
          const subtotal = t.key === 'owner'
            ? calculateOwnerSubtotal(count, livePrices)
            : price * count
          const minusDisabled = deferred || (t.key === 'owner' ? count <= 1 : count <= 0)
          const plusDisabled  = deferred || count >= SEAT_MAX(t.key)
          const detailText = deferred
            ? `TBD · ${t.detail}`
            : t.key === 'owner'
              ? `${formatCurrency(price, { showCents:'never' })}/yr · 2nd seat ${formatCurrency(managerPrice, { showCents:'never' })}/yr · Max 2`
              : `${formatCurrency(price, { showCents:'never' })}/yr · ${t.detail}`
          // Stepper renders identically in both branches — extracted so the
          // order swap below doesn't duplicate the button markup.
          const stepper = (
            <div style={{ display:'flex', alignItems:'center', gap:'6px', flexShrink:0 }}>
              <button
                type="button"
                onClick={() => adjustSeat(t.key, -1)}
                disabled={minusDisabled}
                aria-label={`Decrease ${t.name}`}
                style={{ width:'28px', height:'28px', borderRadius:'8px', border:'1px solid rgba(0,0,0,0.12)', background:minusDisabled?'#f3f4f6':'white', color:minusDisabled?'#c8d8d4':'#1a2e2b', fontSize:'15px', fontWeight:700, cursor:minusDisabled?'not-allowed':'pointer', fontFamily:'inherit', display:'flex', alignItems:'center', justifyContent:'center', padding:0 }}>
                −
              </button>
              <span style={{ minWidth:'24px', textAlign:'center', fontSize:'14px', fontWeight:700, color:'#1a2e2b', fontFamily:'Georgia,serif' }}>
                {count}
              </span>
              <button
                type="button"
                onClick={() => adjustSeat(t.key, 1)}
                disabled={plusDisabled}
                aria-label={`Increase ${t.name}`}
                style={{ width:'28px', height:'28px', borderRadius:'8px', border:'1px solid rgba(0,0,0,0.12)', background:plusDisabled?'#f3f4f6':'white', color:plusDisabled?'#c8d8d4':'#1a2e2b', fontSize:'15px', fontWeight:700, cursor:plusDisabled?'not-allowed':'pointer', fontFamily:'inherit', display:'flex', alignItems:'center', justifyContent:'center', padding:0 }}>
                +
              </button>
            </div>
          )
          return (
            <div key={t.key} style={{ padding:'12px 14px', borderBottom:'1px solid rgba(0,0,0,0.05)', borderLeft:`4px solid ${t.color}`, display:'flex', alignItems:'center', gap:'10px', opacity: deferred ? 0.55 : 1 }}>
              <span style={{ fontSize:'20px', lineHeight:1, flexShrink:0 }}>{t.icon}</span>
              <div style={{ flex:1, minWidth:0 }}>
                <p style={{ fontSize:'13px', fontWeight:700, color:'#1a2e2b', fontFamily:'Georgia,serif' }}>{t.name}</p>
                <p style={{ fontSize:'10.5px', color:'#8a9e9a', marginTop:'1px' }}>
                  {detailText}
                </p>
              </div>
              {/* Deferred rows put pill + $0 BEFORE the (disabled) stepper so
                  the price sits next to the name; non-deferred keep the
                  classic [stepper][subtotal] arrangement at the right edge. */}
              {deferred ? (
                <>
                  <span style={{ display:'inline-block', fontSize:'8px', fontWeight:700, color:'#d4a046', background:'rgba(212,160,70,0.12)', border:'1px solid rgba(212,160,70,0.3)', padding:'2px 7px', borderRadius:'10px', letterSpacing:'0.4px', textTransform:'uppercase', flexShrink:0 }}>Coming Soon</span>
                  <p style={{ fontSize:'12.5px', fontWeight:700, color:'#c8d8d4', fontFamily:'Georgia,serif', flexShrink:0 }}>$0</p>
                  {stepper}
                </>
              ) : (
                <>
                  {stepper}
                  <div style={{ minWidth:'62px', textAlign:'right', flexShrink:0 }}>
                    <p style={{ fontSize:'12.5px', fontWeight:700, color:count>0?'#1a2e2b':'#c8d8d4', fontFamily:'Georgia,serif' }}>
                      {formatCurrency(subtotal, { showCents:'never' })}
                    </p>
                    <p style={{ fontSize:'9.5px', color:'#b0c0bc' }}>subtotal</p>
                  </div>
                </>
              )}
            </div>
          )
        })}
      </div>
    </div>
  )

  // Direct mode: Configure Seats reads first (decision input), then the Cost
  // Summary card reflects that decision underneath. Prepaid + sponsored modes
  // keep the summary/acknowledgment up top since there's no decision to make.
  return (
    <div style={{ display:'grid', gap:'12px' }}>
      {display.mode === 'direct' ? (
        <>
          {seatConfigBlock}
          {costSummaryCard}
        </>
      ) : (
        <>
          {costSummaryCard}
          {seatConfigBlock}
        </>
      )}
    </div>
  )
}

function TierPlansInline() {
  const tierPricesCtx = useContext(TierPricesContext)
  const getTierPrice = tierPricesCtx?.getTierPrice ?? (() => 0)
  const tiers = [
    { key:'owner',    name:'Zee Bee',       icon:'👑', color:'#d4a046', level:'L1', price:getTierPrice('owner') },
    { key:'manager',  name:'Hive Manager',  icon:'🍯', color:'#6366f1', level:'L2', price:getTierPrice('manager') },
    { key:'readonly', name:'Honey Watcher', icon:'👁',  color:'#8a9e9a', level:'L3', price:getTierPrice('readonly') },
  ]
  const sections = [
    { title:'⚙ Account & Billing', rows:[
      ['Manage subscription & billing','Upgrade, payment methods, invoices',['y','n','n']],
      ['View billing & invoices','See current plan and past charges',['y','n','v']],
      ['Connect / disconnect Jobber',"OAuth to franchise's Jobber account",['y','n','n']],
      ['Edit location settings','Business hours, service area, branding',['y','n','n']],
    ]},
    { title:'👥 Team Management', rows:[
      ['Invite / remove Hive Managers','Add or revoke operational seats',['y','n','n']],
      ['Invite / remove Honey Watchers','Add or revoke read-only seats',['y','n','n']],
      ['Assign clients to team members','Set who owns each client',['y','y','n']],
    ]},
    { title:'🐝 Clients & Pipeline', rows:[
      ['View all clients in the location','Full Hive access',['y','y','y']],
      ['Edit client records','Update contact info, stage, tags',['y','y','n']],
      ['Add new clients','Capture incoming calls and inquiries',['y','y','n']],
      ['Schedule assessments & follow-ups','Set appointment times',['y','y','n']],
      ['Log Buzz Notes & Job Notes','Private + Jobber-synced notes',['y','y','n']],
      ['Complete jobs & mark stages done','Field-completion work',['y','y','n']],
    ]},
    { title:'🤝 Contacts & Partners', rows:[
      ['View partners, contacts, companies','Reference referral network',['y','y','y']],
      ['Add or edit partners & contacts','Build the relationship database',['y','y','n']],
    ]},
    { title:'📧 Drip Campaigns', rows:[
      ['Edit new lead emails & templates','Strategic outreach configuration',['y','n','n']],
      ['Pause / resume drips for a client','Per-client drip control',['y','y','n']],
    ]},
    { title:'📊 Reports & Financials', rows:[
      ['View revenue, royalty, pipeline reports','Financial dashboards',['y','y','y']],
      ['Export reports & client data','CSV downloads',['y','y','y']],
    ]},
  ]
  const renderAccess = (v) =>
    v === 'y' ? <span style={{ color:'#2d8659', fontWeight:700, fontSize:'15px', lineHeight:1 }}>✓</span>
  : v === 'n' ? <span style={{ color:'#b0c0bc', fontWeight:500, fontSize:'14px', lineHeight:1 }}>—</span>
  : v === 'v' ? <span style={{ display:'inline-block', background:'rgba(184,136,32,0.15)', color:'#b88820', fontSize:'8px', fontWeight:700, letterSpacing:'0.3px', padding:'2px 4px', borderRadius:'6px', textTransform:'uppercase' }}>View</span>
  : null

  const gridCols = 'minmax(120px, 1.35fr) repeat(3, minmax(54px, 1fr))'

  return (
    <div style={{ margin:'24px 12px 16px' }}>
      <p style={{ fontSize:'10px', fontWeight:700, color:'#8a9e9a', textTransform:'uppercase', letterSpacing:'0.6px', marginBottom:'10px' }}>Compare Plans</p>

      {/* Comparison matrix — tiers as columns, features as rows.
         Header row is sticky within the nearest scroll context so the tier
         labels stay visible while scanning through long feature sections. */}
      <div style={{ border:'1px solid rgba(0,0,0,0.08)', borderRadius:'10px', overflow:'hidden', background:'white' }}>
        {/* Sticky header — tier name + level + price stacked vertically */}
        <div style={{ display:'grid', gridTemplateColumns:gridCols, gap:'4px', background:'rgba(26,46,43,0.04)', borderBottom:'2px solid rgba(0,0,0,0.12)', position:'sticky', top:0, zIndex:5, paddingLeft:'12px', paddingRight:'10px' }}>
          <div style={{ display:'flex', alignItems:'flex-end', padding:'10px 0', fontSize:'9px', letterSpacing:'1px', textTransform:'uppercase', color:'#8a9e9a', fontWeight:700 }}>Capability</div>
          {tiers.map(t => (
            <div key={t.key} style={{ display:'flex', flexDirection:'column', alignItems:'center', gap:'3px', textAlign:'center', borderTop:`3px solid ${t.color}`, padding:'8px 2px 10px' }}>
              <span style={{ fontSize:'15px', lineHeight:1 }}>{t.icon}</span>
              <p style={{ fontSize:'9.5px', fontWeight:700, color:'#1a2e2b', fontFamily:'Georgia,serif', lineHeight:1.15 }}>{t.name}</p>
              <span style={{ fontSize:'7.5px', color:'#8a9e9a', letterSpacing:'0.5px', textTransform:'uppercase', fontWeight:700, padding:'1px 4px', background:'rgba(26,46,43,0.06)', borderRadius:'3px', lineHeight:1.2 }}>{t.level}</span>
              <p style={{ fontSize:'10px', fontWeight:700, color:'#1a2e2b', fontFamily:'Georgia,serif', marginTop:'1px' }}>${t.price}<span style={{ fontSize:'8px', color:'#8a9e9a', fontWeight:500 }}>/yr</span></p>
            </div>
          ))}
        </div>

        {/* Feature rows, grouped by section */}
        {sections.map(s => (
          <React.Fragment key={s.title}>
            <div style={{ padding:'8px 12px', background:'rgba(212,160,70,0.05)', borderLeft:'3px solid #d4a046', fontFamily:'Georgia,serif', fontSize:'11.5px', fontWeight:700, color:'#1a2e2b', borderBottom:'1px solid rgba(0,0,0,0.05)' }}>
              {s.title}
            </div>
            {s.rows.map((r, i) => (
              <div key={`${s.title}-${i}`} style={{ display:'grid', gridTemplateColumns:gridCols, gap:'4px', padding:'9px 10px 9px 12px', borderBottom:'1px solid rgba(0,0,0,0.04)', alignItems:'center' }}>
                <div>
                  <p style={{ fontSize:'10.5px', fontWeight:500, color:'#1a2e2b', lineHeight:1.3 }}>{r[0]}</p>
                  <p style={{ fontSize:'9.5px', color:'#8a9e9a', marginTop:'2px', lineHeight:1.3 }}>{r[1]}</p>
                </div>
                {r[2].map((v, ci) => (
                  <div key={ci} style={{ textAlign:'center' }}>{renderAccess(v)}</div>
                ))}
              </div>
            ))}
          </React.Fragment>
        ))}
      </div>

      {/* Multiple Owners note — second Zee Bee bills at the Hive Manager rate;
         total = first owner + manager (live from tier_prices). */}
      {(() => {
        const ownerPrice = getTierPrice('owner')
        const managerPrice = getTierPrice('manager')
        const coOwnedTotal = ownerPrice + managerPrice
        return (
          <div style={{ padding:'10px 13px', background:'rgba(212,160,70,0.07)', borderLeft:'3px solid #d4a046', borderRadius:'6px', marginTop:'14px', marginBottom:'8px' }}>
            <p style={{ fontSize:'9.5px', color:'#d4a046', letterSpacing:'1px', textTransform:'uppercase', fontWeight:700, marginBottom:'3px' }}>Multiple Owners</p>
            <p style={{ fontSize:'11px', color:'#4a5e5a', lineHeight:1.5 }}>
              Co-owners can add a second Zee Bee seat at <strong style={{ color:'#1a2e2b' }}>${managerPrice.toLocaleString()}/year</strong> — both get full access. Total: <strong style={{ color:'#1a2e2b' }}>${coOwnedTotal.toLocaleString()}/year</strong>.
            </p>
          </div>
        )
      })()}

      {/* Account Security note */}
      <div style={{ padding:'10px 13px', background:'rgba(168,201,196,0.12)', borderLeft:'3px solid #a8c9c4', borderRadius:'6px' }}>
        <p style={{ fontSize:'9.5px', color:'#4d7a72', letterSpacing:'1px', textTransform:'uppercase', fontWeight:700, marginBottom:'3px' }}>Account Security</p>
        <p style={{ fontSize:'11px', color:'#4a5e5a', lineHeight:1.5 }}>
          All logins require a verified <strong style={{ color:'#1a2e2b' }}>Bee Organized email</strong>. Seats are individual — credentials cannot be shared.
        </p>
      </div>
    </div>
  )
}

