// ═══════════════════════════════════════════════════════
//  ROOT APP - Role-aware shell
// ═══════════════════════════════════════════════════════

// ─── useSeatQuote ──────────────────────────────────────────────────────────
// issue 223 — ASK THE SERVER WHAT THIS SEAT COSTS AND WHETHER IT CHARGES.
//
// The confirm screen used to state both facts from client-side arithmetic and
// a hardcoded sentence, and it got both wrong: it multiplied the rate itself,
// and it claimed no card would be charged when /api/seats charges. Neither is
// the client's to know. issue 217 moved the figure to the server on purpose,
// so this fetches it rather than recomputing it — that recomputation is the
// class of bug issue 216 fixed and issue 217 closed.
//
// THE WAIT IS HANDLED BY NOT SHOWING A PRICE UNTIL IT ARRIVES. This is one
// round trip, entered when the owner leaves the form for the confirm step, so
// the modal shows a brief "working out your cost" state and no Confirm button
// at all until it resolves. There is no optimistic figure and no default
// notice, because every wrong guess available here is a guess about money.
//
// A FAILED QUOTE BLOCKS THE PURCHASE. If the server can't say what this
// costs, the honest move is to refuse to take the confirmation, not to fall
// back to a cheerful default — falling back to a cheerful default is exactly
// what issue 223 is.
//
// ── issue 224: THE PICKER ASKS TOO, SO THE ASKING IS CACHED ────────────────
// The price now sits beside each tier the owner is choosing between, not only
// on the confirm step, so the quote is fetched on the form step as well. That
// turns one round trip per purchase into one per tier considered, and an owner
// comparing Manager against Watcher will go back and forth.
//
// ONE AT A TIME, AND KEPT. Not all three up front: two of the picker's tiers
// are never looked at in most sessions (one is deferred and unselectable at
// all), most opens of this modal end without a purchase, and firing three
// billing reads — each of which walks the seat plan and the location's Stripe
// gate — to answer a question nobody asked is work spent on the wrong side of
// the trade. So a tier is quoted when it is first selected and the answer is
// held for the life of the modal. First visit to a tier waits; every visit
// after is instant; a tier never selected is never quoted.
//
// A LATE ANSWER CANNOT LAND ON THE WRONG TIER. Responses are filed under the
// key they were asked for and rendering reads only the CURRENT key, so a slow
// quote for Manager arriving after the owner has switched to Watcher lands in
// Manager's slot and is not on screen. The previous tier's figure is not
// merely overwritten — it is never addressable from the new selection, which
// is the property that matters: the thing this whole arc has been about is a
// wrong number on screen.
//
// Errors are cached too but do NOT block a re-ask: switching away and back
// re-fetches, because a failed quote is usually transient and a permanently
// stuck modal is worse than a second request.
const SEAT_QUOTE_IDLE    = { loading: false, error: '', cost: null, billing: null }
const SEAT_QUOTE_PENDING = { loading: true,  error: '', cost: null, billing: null }

function useSeatQuote({ locationId, tier, quantity = 1, active }) {
  const [byKey, setByKey] = useState({})
  // The cache the effect reads. Mirrored into state for rendering; the ref is
  // what makes "have I already asked this?" answerable without listing every
  // cached key as a dependency.
  const cacheRef   = useRef({})
  const inFlightRef = useRef({})
  const mountedRef  = useRef(true)
  useEffect(() => () => { mountedRef.current = false }, [])

  const key = active && locationId && tier ? `${locationId}|${tier}|${quantity}` : null

  useEffect(() => {
    if (!key) return
    const held = cacheRef.current[key]
    if (held && !held.error) return
    if (inFlightRef.current[key]) return
    inFlightRef.current[key] = true

    const put = (entry) => {
      cacheRef.current[key] = entry
      if (mountedRef.current) setByKey(prev => ({ ...prev, [key]: entry }))
    }
    put(SEAT_QUOTE_PENDING)
    ;(async () => {
      try {
        const qs = new URLSearchParams({ location_id: locationId, tier, quantity: String(quantity) })
        const res = await fetch(`/api/seats/quote?${qs}`, { cache: 'no-store' })
        const json = await res.json().catch(() => ({}))
        if (!res.ok) throw new Error(json.error || 'Could not work out the cost')
        put({ loading: false, error: '', cost: json.cost, billing: json.billing })
      } catch (err) {
        put({
          loading: false,
          error: err?.message || 'Could not work out the cost',
          cost: null,
          billing: null,
        })
      } finally {
        inFlightRef.current[key] = false
      }
    })()
  }, [key, locationId, tier, quantity])

  if (!key) return SEAT_QUOTE_IDLE
  // No entry yet means the effect has not run for this key — which is a wait,
  // not an answer. Never the previous key's entry.
  return byKey[key] || SEAT_QUOTE_PENDING
}

// Turn a resolved quote into the notice + the authoritative figure. Returns
// null until both halves are in hand, which is what gates the Confirm button.
function seatQuoteView(quoteState, seatWord) {
  if (!quoteState.cost || !quoteState.billing) return null
  const totalCents = quoteState.cost.total_cents
  return {
    totalCents,
    // Dollars, for the order-summary row. Straight from the server figure —
    // never re-derived from a rate and a quantity on this side.
    totalDollars: typeof totalCents === 'number' ? totalCents / 100 : null,
    renewalDate: quoteState.cost.renewal_date,
    notice: seatChargeNotice({
      quote: { totalCents, renewalDate: quoteState.cost.renewal_date },
      preview: { willCharge: quoteState.billing.will_charge, reason: quoteState.billing.reason },
      seatWord,
    }),
  }
}

// ─── SeatPickerPriceBlock ──────────────────────────────────────────────────
// issue 224 — THE PRICE OF THE TIER YOU ARE CHOOSING, BESIDE THE CHOICE.
//
// This replaces the block that named the annual rate and then said the real
// figure would appear on the next screen. Both figures are here now: what is
// charged today, prominently, and what renews each year, quietly underneath.
// Both come from the server's quote for the CURRENTLY SELECTED tier — this
// component multiplies nothing and looks no rate up.
//
// THE IN-BETWEEN STATE SHOWS NO NUMBER AT ALL. While a newly-selected tier is
// being quoted there is no honest figure to display, and the one figure that
// is conveniently to hand — the tier the owner just switched away from — is
// the single worst thing that could be on screen. So the amount slot carries
// the wait itself. Same rule as the confirm step (issue 223), same reason.
function SeatPickerPriceBlock({ quoteState, label }) {
  const price =
    quoteState.cost && quoteState.billing
      ? seatPickerPrice({
          quote: {
            totalCents: quoteState.cost.total_cents ?? null,
            annualTotalCents: quoteState.cost.annual_total_cents ?? null,
            renewalDate: quoteState.cost.renewal_date ?? null,
          },
          preview: {
            willCharge: quoteState.billing.will_charge,
            reason: quoteState.billing.reason,
          },
        })
      : null

  // Colour follows the tone, exactly as the confirm notice does, so the two
  // screens agree at a glance as well as in words.
  const TONE = {
    charge: '#1a2e2b',
    free:   '#15803d',
    later:  '#4a5e5a',
  }
  const today  = price ? price.today  : quoteState.loading ? 'Working out your cost…' : 'We couldn’t work this out'
  const renews = price
    ? price.renews
    : quoteState.loading
      ? 'One moment — we’ll show what you pay today and what it costs each year.'
      : 'You’ll see the amount before anything is charged.'
  const kind = price ? price.kind : quoteState.loading ? 'pending' : 'error'

  return (
    <div
      data-testid={`seat-picker-price-${kind}`}
      style={{ background:'rgba(26,46,43,0.03)', border:'1px solid rgba(0,0,0,0.06)', borderRadius:'10px', padding:'10px 12px' }}>
      <div style={{ display:'flex', justifyContent:'space-between', alignItems:'baseline', gap:'10px' }}>
        <span style={{ fontSize:'12px', color:'#4a5e5a' }}>{label}</span>
        <span
          data-testid="seat-picker-today"
          style={{ fontSize: price ? '14px' : '12px', fontWeight:700, fontFamily: price ? 'Georgia,serif' : 'inherit', color: price ? TONE[price.tone] || TONE.later : '#8a9e9a', textAlign:'right' }}>
          {today}
        </span>
      </div>
      <p data-testid="seat-picker-renews" style={{ fontSize:'11px', color:'#8a9e9a', lineHeight:1.5, marginTop:'4px' }}>
        {renews}
      </p>
    </div>
  )
}

// The two non-answer states, rendered the same way in both modals.
function SeatQuotePending({ onCancel }) {
  return (
    <div style={{ display:'flex', flexDirection:'column', gap:'14px', width:'100%', textAlign:'center', padding:'14px 0' }}>
      <div style={{ fontSize:'30px' }}>🧮</div>
      <div>
        <h3 style={{ fontSize:'16px', fontFamily:'Georgia,serif', color:'#1a2e2b', marginBottom:'4px' }}>Working out your cost…</h3>
        <p style={{ fontSize:'12.5px', color:'#8a9e9a', lineHeight:1.5 }}>One moment while we check what this will cost you.</p>
      </div>
      <button onClick={onCancel}
        style={{ padding:'10px', background:'transparent', border:'1.5px solid rgba(0,0,0,0.12)', borderRadius:'10px', fontSize:'13px', fontFamily:'inherit', color:'#4a5e5a', cursor:'pointer' }}>
        ← Back
      </button>
    </div>
  )
}

function SeatQuoteFailed({ message, onCancel }) {
  return (
    <div style={{ display:'flex', flexDirection:'column', gap:'14px', width:'100%' }}>
      <div>
        <h3 style={{ fontSize:'16px', fontFamily:'Georgia,serif', color:'#1a2e2b', marginBottom:'4px' }}>We couldn’t work out the cost</h3>
        <p style={{ fontSize:'12.5px', color:'#8a9e9a', lineHeight:1.5 }}>
          Nothing has been added and nothing has been charged. Please try again in a moment — if it keeps happening, contact Bee Organized and we’ll sort it out.
        </p>
      </div>
      {message && (
        <p style={{ padding:'8px 12px', background:'rgba(239,68,68,0.08)', border:'1px solid rgba(239,68,68,0.18)', borderRadius:'9px', color:'#b91c1c', fontSize:'12px' }}>{message}</p>
      )}
      <button onClick={onCancel}
        style={{ padding:'11px', background:'transparent', border:'1.5px solid rgba(0,0,0,0.12)', borderRadius:'10px', fontSize:'13px', fontFamily:'inherit', color:'#4a5e5a', cursor:'pointer' }}>
        ← Back
      </button>
    </div>
  )
}

// ─── PaymentConfirmStep ────────────────────────────────────────────────────
// Reusable payment-confirmation interstitial. Drops in between any
// "buy seats" form and its actual API call. Renders a heading, an
// order-summary card with line items + total, a stubbed payment-method
// placeholder ("Card on file: •••• 4242"), and a Back / Pay button
// row. The card-collection step itself is post-demo (real Stripe
// Elements); this component exists to make the demo feel deliberate
// rather than instant.
//
// Props:
//   title        — heading string ("Confirm payment")
//   lineItems    — Array<{ label, amount }> displayed as rows; amount in dollars
//   total        — number in dollars, shown in the bold total row
//   confirmLabel — primary button text ("Pay & Activate", "Pay & Send Invite")
//   onConfirm    — async fn run when user confirms; caller drives the API call
//   onCancel     — fn to return to the prior view
//   isProcessing — bool; disables the confirm button and swaps label to a busy state
//   error        — optional string rendered inline above the buttons
//   stripePayUrl — when set, this is a REAL Stripe checkout: the amber
//                  no-charge notice becomes a Stripe-checkout notice, the
//                  confirm button opens the link in a new tab and fires
//                  onStripeOpen() (caller switches to StripeCheckoutWait).
//                  onConfirm/isProcessing are unused in this variant. No
//                  card field ever renders in Bee Hub — checkout is
//                  entirely Stripe-hosted.
//   onStripeOpen — fired after window.open on the Stripe link
//   notice       — issue 223. A {kind,tone,heading,body,confirmLabel} from
//                  lib/seat-charge-notice: what will ACTUALLY happen when
//                  this is confirmed, decided server-side. When supplied it
//                  replaces the fixed notice below and supplies the confirm
//                  button's whole label, so a screen that charges says so on
//                  the button itself. Omitted by the onboarding pay step,
//                  which keeps the original two-branch behaviour untouched.
function PaymentConfirmStep({
  title = 'Confirm payment',
  lineItems = [],
  total = 0,
  confirmLabel = 'Confirm',
  onConfirm,
  onCancel,
  isProcessing = false,
  error = null,
  stripePayUrl = null,
  onStripeOpen = null,
  notice = null,
}) {
  // issue 223 — colour follows the TONE, never the wording: money leaving
  // now reads differently at a glance from nothing owed and from a bill
  // arriving later.
  const NOTICE_TONE = {
    charge: { border:'rgba(212,160,70,0.45)', bg:'rgba(212,160,70,0.07)', icon:'💳' },
    free:   { border:'rgba(34,197,94,0.35)',  bg:'rgba(34,197,94,0.07)',  icon:'✅' },
    later:  { border:'rgba(99,116,139,0.35)', bg:'rgba(99,116,139,0.07)', icon:'🧾' },
  }
  const noticeTone = notice ? (NOTICE_TONE[notice.tone] || NOTICE_TONE.later) : null
  return (
    <div style={{ display:'flex', flexDirection:'column', gap:'14px', width:'100%' }}>
      <div>
        <h3 style={{ fontSize:'17px', fontFamily:'Georgia,serif', color:'#1a2e2b', marginBottom:'2px' }}>{title}</h3>
        <p style={{ fontSize:'12px', color:'#8a9e9a' }}>Review your charge before we finalize it.</p>
      </div>

      {/* Order summary card */}
      <div style={{ borderRadius:'12px', border:'1px solid rgba(0,0,0,0.08)', overflow:'hidden', boxShadow:'0 1px 4px rgba(26,46,43,0.04)' }}>
        <div style={{ padding:'9px 14px', background:'rgba(26,46,43,0.03)', borderBottom:'1px solid rgba(0,0,0,0.06)' }}>
          <p style={{ fontSize:'10px', fontWeight:700, color:'#8a9e9a', textTransform:'uppercase', letterSpacing:'0.6px' }}>
            Order summary
          </p>
        </div>
        <div style={{ background:'white', padding:'10px 14px' }}>
          {lineItems.length === 0 ? (
            <p style={{ fontSize:'12px', color:'#8a9e9a', fontStyle:'italic' }}>No line items</p>
          ) : (
            <div style={{ display:'grid', gap:'6px' }}>
              {lineItems.map((li, i) => (
                <div key={i} style={{ display:'flex', justifyContent:'space-between', alignItems:'baseline', gap:'10px', fontSize:'12.5px', color:'#4a5e5a' }}>
                  <span style={{ flex:1, minWidth:0 }}>{li.label}</span>
                  <span style={{ fontWeight:600, color:'#1a2e2b', fontFamily:'Georgia,serif' }}>
                    {formatCurrency(li.amount, { showCents:'always' })}
                  </span>
                </div>
              ))}
            </div>
          )}
          {/* issue 225 — showCents:'always', for the reason issue 223 gave the
              notice: 'auto' drops cents above $100, so a $372.60 seat printed
              "$373" here while the notice under it said "about $372.60". Two
              different numbers for one purchase, on the screen where someone
              commits, and the rounded one was the bigger lie — 40c of Stripe
              proration is the gap this issue hedges, where this was 40c the
              other way from a display rule. 'auto' stays right for a headline
              annual price (see the confirm button below, and the onboarding
              hero); it is wrong for an amount about to be taken. */}
          <div style={{ borderTop:'1px solid rgba(0,0,0,0.08)', marginTop:'10px', paddingTop:'10px', display:'flex', justifyContent:'space-between', alignItems:'baseline' }}>
            <span style={{ fontSize:'13px', color:'#1a2e2b', fontWeight:700 }}>Order total</span>
            <span style={{ fontSize:'19px', fontWeight:700, color:'#d4a046', fontFamily:'Georgia,serif' }}>
              {formatCurrency(total, { showCents:'always' })}
            </span>
          </div>
        </div>
      </div>

      {notice ? (
        /* issue 223 — the server's verdict, in the owner's words. */
        <div data-testid={`seat-notice-${notice.kind}`}
          style={{ borderRadius:'12px', border:`1.5px solid ${noticeTone.border}`, background:noticeTone.bg, padding:'12px 14px' }}>
          <div style={{ display:'flex', alignItems:'center', gap:'10px', marginBottom:'6px' }}>
            <span style={{ fontSize:'18px' }}>{noticeTone.icon}</span>
            <p style={{ fontSize:'11px', fontWeight:700, color:'#1a2e2b', textTransform:'uppercase', letterSpacing:'0.6px' }}>
              {notice.heading}
            </p>
          </div>
          <p style={{ fontSize:'12.5px', color:'#4a5e5a', lineHeight:1.5 }}>{notice.body}</p>
        </div>
      ) : stripePayUrl ? (
        /* Real Stripe checkout — the honest replacement for the fake card
           form. Bee Hub never sees card details; the webhook activates the
           purchase when Stripe confirms payment. */
        <div style={{ borderRadius:'12px', border:'1.5px solid rgba(99,91,255,0.35)', background:'rgba(99,91,255,0.05)', padding:'12px 14px' }}>
          <div style={{ display:'flex', alignItems:'center', gap:'10px', marginBottom:'6px' }}>
            <span style={{ fontSize:'18px' }}>🔒</span>
            <p style={{ fontSize:'11px', fontWeight:700, color:'#1a2e2b', textTransform:'uppercase', letterSpacing:'0.6px' }}>
              Secure Stripe checkout
            </p>
          </div>
          <p style={{ fontSize:'12.5px', color:'#4a5e5a', lineHeight:1.5 }}>
            You'll complete payment on <strong>Stripe's secure checkout page</strong> — Bee Hub
            never sees your card details. The final amount is shown at checkout, and your
            purchase activates automatically once Stripe confirms the payment.
          </p>
        </div>
      ) : (
        /* No-charge notice. Online payment isn't configured for this tier —
           say so plainly instead of rendering a fake card. Confirming records
           the purchase; billing happens offline. */
        <div style={{ borderRadius:'12px', border:'1.5px solid rgba(212,160,70,0.45)', background:'rgba(212,160,70,0.07)', padding:'12px 14px' }}>
          <div style={{ display:'flex', alignItems:'center', gap:'10px', marginBottom:'6px' }}>
            <span style={{ fontSize:'18px' }}>💳</span>
            <p style={{ fontSize:'11px', fontWeight:700, color:'#1a2e2b', textTransform:'uppercase', letterSpacing:'0.6px' }}>
              No charge today
            </p>
          </div>
          <p style={{ fontSize:'12.5px', color:'#4a5e5a', lineHeight:1.5 }}>
            Online payment isn't set up yet, so <strong>no card will be charged</strong>.
            Confirming records this purchase and Bee Organized will invoice you for it separately.
          </p>
        </div>
      )}

      {error && (
        <p style={{ padding:'8px 12px', background:'rgba(239,68,68,0.08)', border:'1px solid rgba(239,68,68,0.18)', borderRadius:'9px', color:'#b91c1c', fontSize:'12px' }}>
          {error}
        </p>
      )}

      <div style={{ display:'flex', gap:'8px', marginTop:'2px' }}>
        <button onClick={onCancel} disabled={isProcessing}
          style={{ flex:1, padding:'12px', background:'transparent', border:'1.5px solid rgba(0,0,0,0.12)', borderRadius:'10px', fontSize:'13px', fontFamily:'inherit', color:'#4a5e5a', cursor:isProcessing?'not-allowed':'pointer', opacity:isProcessing?0.5:1 }}>
          ← Back
        </button>
        {stripePayUrl ? (
          <button onClick={() => { if (onStripeOpen) onStripeOpen(); navigateToStripeCheckout(stripePayUrl) }}
            style={{ flex:2, padding:'12px', background:'#635bff', border:'none', borderRadius:'10px', fontSize:'13px', fontFamily:'inherit', fontWeight:600, color:'white', cursor:'pointer' }}>
            Pay with Stripe →
          </button>
        ) : (
          <button onClick={onConfirm} disabled={isProcessing}
            style={{ flex:2, padding:'12px', background:isProcessing?'#8a9e9a':'#1a2e2b', border:'none', borderRadius:'10px', fontSize:'13px', fontFamily:'inherit', fontWeight:600, color:'white', cursor:isProcessing?'wait':'pointer' }}>
            {isProcessing
              ? 'Processing…'
              : notice
                /* issue 223 — the button carries the outcome too. It is the
                   last thing read before committing, so "Confirm & Pay
                   $219.45" and "Confirm & Add" must not look alike. */
                ? `${notice.confirmLabel} →`
                /* issue 225 — 'auto' KEPT here, deliberately. This branch runs
                   only when no notice is supplied, i.e. the onboarding pay
                   step, whose total is a full-year annual (issue 162: no
                   proration at signup) summed from whole-dollar tier_prices.
                   'auto' drops nothing from a whole-dollar figure, and forcing
                   ".00" onto a headline price is the churn this rule exists to
                   avoid. The seat modals reach the branch above instead, where
                   the cents are real and the label already carries them. */
                : `${confirmLabel} ${formatCurrency(total, { showCents:'auto' })} →`}
          </button>
        )}
      </div>
    </div>
  )
}

// ─── StripeCheckoutWait ────────────────────────────────────────────────────
// Shown after the owner returns from Stripe checkout in the same tab. Polls
// /api/locations/[id]/activation-status every 4s until `until(status)` says
// the webhook's writes are visible, then fires onPaid(status).
//
// issue 311 — the poll now has a DEADLINE and the copy tells the truth.
// Previously it re-armed forever under "usually within a few seconds", which
// is right for a card and five orders of magnitude wrong for a bank transfer:
// an ACH checkout completes with payment_status=unpaid, the webhook correctly
// declines to activate, and the owner watched a spinner for twenty minutes
// with no way to learn that the honest answer was "three to five days".
//
// The phase, the deadline and every line of copy live in lib/stripe-wait-phase
// — this file is not type-checked, and that module documents in full WHY the
// screen cannot tell a pending ACH from a slow webhook (short version: the
// return carries no session id, activation-status reads the location row which
// the pending path never touches, and the sync_log row that does record it is
// written with location_id NULL). It cannot know, so the copy names both
// outcomes rather than guessing at one.
//
// Timeout still never claims failure — the payment may genuinely still land.
// It just stops spinning and says something true.
function StripeCheckoutWait({ locationId, until, onPaid, onBack, payUrl }) {
  const [elapsed, setElapsed] = useState(0)
  const untilRef = useRef(until);  untilRef.current  = until
  const onPaidRef = useRef(onPaid); onPaidRef.current = onPaid

  React.useEffect(() => {
    let stopped = false
    let pollTimer = null
    // Wall-clock, not the `elapsed` state: the poll closure is created once and
    // would read a frozen 0 forever. The clock below only drives the copy.
    const startedAt = Date.now()
    const pastDeadline = () => (Date.now() - startedAt) / 1000 >= DEADLINE_SECONDS
    const poll = async () => {
      try {
        const res = await fetch(`/api/locations/${locationId}/activation-status`, { cache:'no-store' })
        if (res.ok) {
          const json = await res.json().catch(() => null)
          if (!stopped && json && untilRef.current(json)) {
            onPaidRef.current(json)
            return
          }
        }
      } catch {}
      // The deadline. Stop re-arming — a confirmation that has not arrived by
      // now is not arriving because we kept asking.
      if (!stopped && !pastDeadline()) pollTimer = setTimeout(poll, 4000)
    }
    pollTimer = setTimeout(poll, 3000)
    const clock = setInterval(() => setElapsed(s => s + 1), 1000)
    return () => { stopped = true; clearTimeout(pollTimer); clearInterval(clock) }
  }, [locationId])

  const phase = checkoutWaitPhase(elapsed)
  const copy  = checkoutWaitCopy(phase)
  const waiting = isPollingPhase(phase)
  // Controls sit at their natural width — the column is a flex container, whose
  // default `stretch` would otherwise pull every button edge-to-edge.
  const controlStyle = { alignSelf:'center', minWidth:'160px' }

  return (
    <div style={{ display:'flex', flexDirection:'column', gap:'14px', width:'100%', textAlign:'center', padding:'8px 0' }}>
      <div style={{ fontSize:'40px' }}>{waiting ? '🐝' : '✉️'}</div>
      <div>
        <h3 style={{ fontSize:'17px', fontFamily:'Georgia,serif', color:'#1a2e2b', marginBottom:'4px' }}>{copy.heading}</h3>
        <p style={{ fontSize:'12.5px', color:'#8a9e9a', lineHeight:1.5 }}>
          {copy.body}
        </p>
      </div>
      {copy.note && (
        <div style={{ borderRadius:'10px', border:'1px solid rgba(212,160,70,0.4)', background:'rgba(212,160,70,0.07)', padding:'10px 12px', textAlign:'left' }}>
          <p style={{ fontSize:'12px', color:'#4a5e5a', lineHeight:1.5 }}>
            {copy.note}
          </p>
        </div>
      )}
      {payUrl && showsReopenCheckout(phase) && (
        <button onClick={() => navigateToStripeCheckout(payUrl)}
          style={{ ...controlStyle, padding:'10px', background:'transparent', border:'none', fontSize:'12px', color:'#635bff', cursor:'pointer', fontFamily:'inherit', textDecoration:'underline' }}>
          Reopen Stripe checkout
        </button>
      )}
      <button onClick={onBack}
        style={{ ...controlStyle, padding:'10px 18px', background:'transparent', border:'1.5px solid rgba(0,0,0,0.12)', borderRadius:'10px', fontSize:'13px', fontFamily:'inherit', color:'#4a5e5a', cursor:'pointer' }}>
        ← Back
      </button>
    </div>
  )
}

// ─── ScheduleRemovalModal ──────────────────────────────────────────────────
// Owner schedules a seat for removal at renewal. No mid-cycle credits.
// PATCH /api/seats/[id] with { scheduled_removal_at: 'YYYY-MM-DD' }.
export function ScheduleRemovalModal({ seat, tierMeta, onClose, onScheduled, paidThroughDate=null }) {
  const currentLocationCtx = useContext(CurrentLocationContext)
  // issue 162: removal defaults to the LOCATION'S OWN renewal date
  // (paid_through_date — the anniversary its seat is billed through), not a
  // fixed March 1. Legacy fixed date only when no paid_through exists.
  const defaultRemovalDate = resolveLocationRenewalDate({
    paidThroughDate: paidThroughDate ?? currentLocationCtx?.paid_through_date ?? null,
  }).toISOString().slice(0, 10)
  const [date, setDate]       = useState(defaultRemovalDate)
  const [saving, setSaving]   = useState(false)
  const [error, setError]     = useState('')
  const hasUser = !!seat.user_id

  async function confirm() {
    setSaving(true)
    setError('')
    try {
      const res = await fetch(`/api/seats/${encodeURIComponent(seat.id)}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ scheduled_removal_at: date }),
      })
      const j = await res.json().catch(() => ({}))
      if (!res.ok) throw new Error(j.error || `HTTP ${res.status}`)
      onScheduled({ ...seat, scheduled_removal_at: date })
      onClose()
    } catch (err) {
      setError(err?.message || 'Could not schedule removal')
    } finally {
      setSaving(false)
    }
  }

  return (
    <div style={{ position:'fixed', inset:0, zIndex:9900, display:'flex', alignItems:'center', justifyContent:'center', padding:'16px', background:'rgba(26,46,43,0.55)', fontFamily:'"DM Sans",system-ui,sans-serif' }}>
      <div style={{ background:'white', borderRadius:'18px', width:'100%', maxWidth:'400px', boxShadow:'0 24px 80px rgba(0,0,0,0.25)', overflow:'hidden' }}>
        <div style={{ background:'#1a2e2b', padding:'14px 18px', display:'flex', alignItems:'center', justifyContent:'space-between' }}>
          <span style={{ fontSize:'14px', fontWeight:700, color:'white' }}>🕐 Schedule seat removal</span>
          <button onClick={onClose} style={{ background:'none', border:'none', color:'rgba(255,255,255,0.75)', cursor:'pointer', fontSize:'22px', padding:0, lineHeight:1, fontFamily:'inherit' }}>×</button>
        </div>
        <div style={{ padding:'20px 20px 8px' }}>
          <p style={{ fontSize:'13px', color:'#1a2e2b', fontWeight:600, marginBottom:'6px' }}>
            {tierMeta?.icon} {tierMeta?.name || seat.tier} seat
          </p>
          <p style={{ fontSize:'12px', color:'#4a5e5a', lineHeight:1.55, marginBottom:'16px' }}>
            This seat will stay active and billable until the scheduled date. On that date, a super admin will process removals and the seat will be deactivated.
            {hasUser && <span style={{ display:'block', marginTop:'6px', color:'#d97706', fontWeight:600 }}>⚠️ This seat is assigned — the user will lose access when the seat is removed.</span>}
          </p>
          <label style={{ display:'block', fontSize:'11px', fontWeight:700, color:'#8a9e9a', textTransform:'uppercase', letterSpacing:'0.5px', marginBottom:'6px' }}>
            Removal date
          </label>
          <input
            type="date"
            value={date}
            min={(() => { const d = new Date(); d.setDate(d.getDate()+1); return d.toISOString().slice(0,10) })()}
            onChange={e => { setDate(e.target.value); setError('') }}
            style={{ width:'100%', padding:'9px 12px', border:'1.5px solid rgba(0,0,0,0.12)', borderRadius:'8px', fontSize:'13px', fontFamily:'inherit', color:'#1a2e2b', boxSizing:'border-box' }}
          />
          <p style={{ fontSize:'11px', color:'#8a9e9a', marginTop:'6px' }}>Defaults to your location's renewal date.</p>
          {error && <p style={{ fontSize:'12px', color:'#ef4444', marginTop:'8px' }}>{error}</p>}
        </div>
        <div style={{ padding:'12px 20px 20px', display:'flex', gap:'10px', justifyContent:'flex-end' }}>
          <button onClick={onClose} style={{ padding:'9px 16px', background:'transparent', border:'1.5px solid rgba(0,0,0,0.12)', borderRadius:'9px', fontSize:'13px', fontFamily:'inherit', fontWeight:600, color:'#4a5e5a', cursor:'pointer' }}>
            Cancel
          </button>
          <button
            onClick={confirm}
            disabled={saving || !date}
            style={{ padding:'9px 18px', background: saving ? '#8a9e9a' : '#d97706', border:'none', borderRadius:'9px', fontSize:'13px', fontFamily:'inherit', fontWeight:700, color:'white', cursor: saving ? 'not-allowed' : 'pointer' }}>
            {saving ? 'Scheduling…' : 'Schedule removal'}
          </button>
        </div>
      </div>
    </div>
  )
}

// ─── CancelScheduledRemovalModal ───────────────────────────────────────────
// Clears scheduled_removal_at on a seat (PATCH with null).
function CancelScheduledRemovalModal({ seat, tierMeta, onClose, onCanceled }) {
  const [saving, setSaving]   = useState(false)
  const [error, setError]     = useState('')

  async function confirm() {
    setSaving(true)
    setError('')
    try {
      const res = await fetch(`/api/seats/${encodeURIComponent(seat.id)}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ scheduled_removal_at: null }),
      })
      const j = await res.json().catch(() => ({}))
      if (!res.ok) throw new Error(j.error || `HTTP ${res.status}`)
      onCanceled({ ...seat, scheduled_removal_at: null })
      onClose()
    } catch (err) {
      setError(err?.message || 'Could not cancel scheduled removal')
    } finally {
      setSaving(false)
    }
  }

  return (
    <div style={{ position:'fixed', inset:0, zIndex:9900, display:'flex', alignItems:'center', justifyContent:'center', padding:'16px', background:'rgba(26,46,43,0.55)', fontFamily:'"DM Sans",system-ui,sans-serif' }}>
      <div style={{ background:'white', borderRadius:'18px', width:'100%', maxWidth:'380px', boxShadow:'0 24px 80px rgba(0,0,0,0.25)', overflow:'hidden' }}>
        <div style={{ background:'#1a2e2b', padding:'14px 18px', display:'flex', alignItems:'center', justifyContent:'space-between' }}>
          <span style={{ fontSize:'14px', fontWeight:700, color:'white' }}>Cancel scheduled removal</span>
          <button onClick={onClose} style={{ background:'none', border:'none', color:'rgba(255,255,255,0.75)', cursor:'pointer', fontSize:'22px', padding:0, lineHeight:1, fontFamily:'inherit' }}>×</button>
        </div>
        <div style={{ padding:'20px' }}>
          <p style={{ fontSize:'13px', color:'#1a2e2b', lineHeight:1.55, marginBottom:'0' }}>
            Cancel the scheduled removal for this <strong>{tierMeta?.name || seat.tier}</strong> seat? It will remain active and billable as normal.
          </p>
          {error && <p style={{ fontSize:'12px', color:'#ef4444', marginTop:'10px' }}>{error}</p>}
        </div>
        <div style={{ padding:'4px 20px 20px', display:'flex', gap:'10px', justifyContent:'flex-end' }}>
          <button onClick={onClose} style={{ padding:'9px 16px', background:'transparent', border:'1.5px solid rgba(0,0,0,0.12)', borderRadius:'9px', fontSize:'13px', fontFamily:'inherit', fontWeight:600, color:'#4a5e5a', cursor:'pointer' }}>
            Dismiss
          </button>
          <button
            onClick={confirm}
            disabled={saving}
            style={{ padding:'9px 18px', background: saving ? '#8a9e9a' : '#22c55e', border:'none', borderRadius:'9px', fontSize:'13px', fontFamily:'inherit', fontWeight:700, color:'white', cursor: saving ? 'not-allowed' : 'pointer' }}>
            {saving ? 'Canceling…' : 'Keep seat active'}
          </button>
        </div>
      </div>
    </div>
  )
}

// ─── AddSeatsModal ─────────────────────────────────────────────────────────
// Real "+ Add seats" flow (Dispatch 3). Replaces the stub alert. Owner
// picks a tier + quantity, sees live prorated cost, POSTs a bulk insert
// to /api/seats. On success, pushes the new seats into SeatsContext so
// the billing card refreshes without a reload. No real Stripe yet —
// "Pay" just records the prorated_cost on each seat row.
// Exported for the issue 223 component tests, the way issue 216 exported
// ScheduleRemovalModal — a screen that quotes money is mounted for real.
// issue 224 — THE LAST CLIENT-SIDE RENEWAL DATE IN THE SEAT FLOW, REMOVED.
//
// This modal resolved the date itself, exactly as InviteTeamMemberModal did,
// and inherited the same fabrication: resolveLocationRenewalDate falls back to
// legacyFixedRenewalDate — March 1 — when a location has no paid_through_date.
// That fallback belongs to the pre-Stripe cohort and is nobody's default, so a
// location without an anchor was reading a renewal date that was not its own.
//
// That fallback has now been found in four places across issues 216, 217, 223
// and 224, which is three more times than a fallback should need finding. The
// rule is settled: NOTHING IN THE SEAT FLOW DERIVES A RENEWAL DATE. The server
// reads locations.paid_through_date when it prices the seat and returns it on
// the quote (cost.renewal_date), and the screen either states that date or
// states no date at all — never an invented one. resolveLocationRenewalDate
// keeps its one legitimate caller, ScheduleRemovalModal, which needs a
// pre-filled default in a date input before any quote exists.
//
// The paidThroughDate prop goes with it, as InviteTeamMemberModal's did. A
// prop whose only consumer is gone is an invitation to grow a second one.
export function AddSeatsModal({ locationId, onClose, onSeatsAdded }) {
  const tierPricesCtx  = useContext(TierPricesContext)
  const getTierPrice = tierPricesCtx?.getTierPrice ?? (() => 0)

  const [step, setStep]         = useState('form') // form | paymentConfirm
  const [tier, setTier]         = useState('manager')
  const [quantity, setQuantity] = useState(1)
  const [submitting, setSubmitting] = useState(false)
  const [error, setError]       = useState('')
  // issue 218 — this modal used to carry a second, parallel Stripe branch
  // built on Payment Links: a per-tier tier_prices.payment_link_url that
  // turned the confirm step into "Pay with Stripe", plus a stripeWait step
  // polling for the webhook's seat. Neither end of it was ever wired —
  // no tier has a link set, and /api/seats never returned the 402 + pay_url
  // that was its other trigger — so it was unreachable UI. It is gone
  // rather than wired because Payment Links compete with the Checkout
  // Sessions the live paths already use (onboarding, the issue 182 admin
  // link); one way to charge for a seat, not two. Seats bought here are
  // charged as subscription lines by /api/seats (issues 161/219).

  React.useEffect(() => {
    const prev = document.body.style.overflow
    document.body.style.overflow = 'hidden'
    return () => { document.body.style.overflow = prev }
  }, [])

  // Only Manager / Worker / Watcher — owner seats are seeded during
  // onboarding's co-owner flow and capped at 2; post-onboarding add-seat
  // doesn't touch them.
  const TIER_OPTIONS = SUBSCRIPTION_TIER_META.filter(t => t.key !== 'owner')

  // issue 216 — flat price × quantity is CORRECT here, and only because
  // TIER_OPTIONS above excludes 'owner'. The co-owner rule (2nd owner seat
  // bills at the manager rate) is the sole reason seat pricing can't be a
  // multiply, and it can never apply to a tier that isn't owner. If an owner
  // tier is ever added to this picker, this must move to calculateSeatTotal.
  //
  // issue 224 — the client's last money multiply is gone. This was the annual
  // RATE × quantity, which issue 223 left standing as "a fact about the tier".
  // It is a fact about the tier only for one seat: multiplying it is a claim
  // about a purchase, and it is the claim the co-owner rule contradicts. Both
  // figures the summary block names now come from the server's quote for the
  // selected tier (annual_total_cents and total_cents), so this modal derives
  // no money at all. The per-row "$400 /yr each" labels below are untouched —
  // those are the price list, one rate per tier, not a total.
  const tierMeta     = SUBSCRIPTION_TIER_META.find(t => t.key === tier)

  // issue 224 — quoted from the form step now, not only on the way to confirm,
  // because the picker names the figure. Cached per tier + quantity inside the
  // hook, so the confirm step almost always has its answer already.
  const quoteState = useSeatQuote({
    locationId,
    tier,
    quantity,
    active: step === 'form' || step === 'paymentConfirm',
  })
  // issue 224 — the renewal date for the header subtitle, from the SAME quote
  // that priced the seats. null until it lands, and null forever for a
  // location with no paid_through_date — in both cases the subtitle drops the
  // clause rather than naming a date nobody chose.
  const quotedRenewalLabel = (() => {
    const parsed = parsePaidThroughDate(quoteState.cost?.renewal_date ?? null)
    return parsed ? formatRenewalDate(parsed) : null
  })()
  const seatWord = quantity === 1
    ? `${tierMeta?.name || tier} seat`
    : `${quantity} ${tierMeta?.name || tier} seats`
  const quoteView = seatQuoteView(quoteState, seatWord)

  // Triggered by the form-step Pay button. Just transitions to the
  // payment-confirmation interstitial; the real /api/seats POST runs
  // from runAddSeats() when the user confirms there.
  function handleProceedToConfirm() {
    setError('')
    setStep('paymentConfirm')
  }

  async function runAddSeats() {
    if (submitting) return
    setSubmitting(true)
    setError('')
    try {
      const res = await fetch('/api/seats', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        // issue 223 — no prorated_cost. issue 217 already ignored the client's
        // figure; now the client doesn't have one to send. The server prices
        // the seat and the confirm screen showed that same price.
        body: JSON.stringify({
          location_id: locationId,
          tier,
          quantity,
        }),
      })
      const json = await res.json().catch(() => ({}))
      if (!res.ok) throw new Error(json.error || 'Failed to add seats')
      const inserted = Array.isArray(json) ? json : [json]
      onSeatsAdded(inserted)
      onClose()
    } catch (err) {
      setError(err?.message || 'Could not add seats')
    } finally {
      setSubmitting(false)
    }
  }

  return (
    <div style={{ position:'fixed', inset:0, zIndex:10020, display:'flex', alignItems:'center', justifyContent:'center', padding:'12px' }}>
      <div style={{ position:'absolute', inset:0, background:'rgba(26,46,43,0.5)' }} onClick={onClose} />
      <div style={{ position:'relative', background:'white', borderRadius:'14px', width:'100%', maxWidth:'440px', maxHeight:'90vh', display:'flex', flexDirection:'column', boxShadow:'0 16px 48px rgba(26,46,43,0.25)', overflow:'hidden', zIndex:1 }}>
        <div style={{ padding:'18px 22px 4px', borderBottom:'1px solid rgba(0,0,0,0.06)' }}>
          <div style={{ display:'flex', justifyContent:'space-between', alignItems:'flex-start' }}>
            <div>
              <h2 style={{ fontSize:'18px', fontFamily:'Georgia,serif', color:'#1a2e2b', marginBottom:'4px' }}>
                {step === 'paymentConfirm' ? 'Confirm payment' : 'Add seats to your plan'}
              </h2>
              <p style={{ fontSize:'12px', color:'#8a9e9a', lineHeight:1.5 }}>
                {step === 'paymentConfirm'
                  ? `Adds ${quantity} ${tierMeta?.name || tier} seat${quantity === 1 ? '' : 's'} to your pool. Each appears as an open seat on the team roster, ready to invite into.`
                  /* issue 223 — "prorated to your renewal date" is the jargon
                     this screen's audience doesn't use. Same fact, plainly.
                     issue 224 — the date is the QUOTE's, and the clause is
                     dropped entirely when there isn't one: before the quote
                     lands, and for a location with no paid_through_date. The
                     sentence reads fine without it, which is the whole reason
                     it is safe to omit rather than fill in. */
                  : `Billed once a year. Today you'd only pay for what's left before your renewal${quotedRenewalLabel ? ` on ${quotedRenewalLabel}` : ''}. Once added, you can invite team members anytime.`}
              </p>
            </div>
            <button onClick={onClose} style={{ background:'none', border:'none', fontSize:'22px', color:'#8a9e9a', cursor:'pointer', lineHeight:1, padding:'0 0 0 8px' }}>×</button>
          </div>
        </div>

        <div style={{ padding:'14px 22px', overflowY:'auto', flex:1 }}>
          {step === 'paymentConfirm' && (
            quoteState.loading ? (
              <SeatQuotePending onCancel={() => { setError(''); setStep('form') }} />
            ) : !quoteView ? (
              <SeatQuoteFailed message={quoteState.error} onCancel={() => { setError(''); setStep('form') }} />
            ) : (
              <PaymentConfirmStep
                title="Confirm pre-buy"
                lineItems={[{
                  label: quoteView.totalDollars === null
                    ? `${quantity} ${tierMeta?.name || tier} seat${quantity === 1 ? '' : 's'}`
                    : `${quantity} ${tierMeta?.name || tier} seat${quantity === 1 ? '' : 's'} (rest of your year)`,
                  // The SERVER's figure, not a client multiply — issue 223.
                  amount: quoteView.totalDollars ?? 0,
                }]}
                total={quoteView.totalDollars ?? 0}
                confirmLabel="Confirm & Add Seats"
                onConfirm={runAddSeats}
                onCancel={() => { setError(''); setStep('form') }}
                isProcessing={submitting}
                error={error || null}
                notice={quoteView.notice}
              />
            )
          )}

          {step === 'form' && (
            <>
          <p style={{ fontSize:'10px', fontWeight:700, color:'#8a9e9a', textTransform:'uppercase', letterSpacing:'0.5px', marginBottom:'8px' }}>Seat tier</p>
          <div style={{ display:'grid', gap:'8px', marginBottom:'18px' }}>
            {TIER_OPTIONS.map(t => {
              const isSelected = tier === t.key
              const price = getTierPrice(t.key)
              return (
                <button key={t.key} onClick={()=>setTier(t.key)}
                  style={{ padding:'12px 14px', background:isSelected?'rgba(26,46,43,0.04)':'white', border:`2px solid ${isSelected?'#1a2e2b':'rgba(0,0,0,0.08)'}`, borderRadius:'10px', cursor:'pointer', fontFamily:'inherit', textAlign:'left', display:'flex', alignItems:'center', gap:'12px' }}>
                  <span style={{ fontSize:'22px' }}>{t.icon}</span>
                  <div style={{ flex:1, minWidth:0 }}>
                    <p style={{ fontSize:'13px', fontWeight:600, color:'#1a2e2b' }}>{t.name}</p>
                    <p style={{ fontSize:'11px', color:'#8a9e9a' }}>{t.detail}</p>
                  </div>
                  <div style={{ textAlign:'right' }}>
                    <p style={{ fontSize:'13px', fontWeight:700, color:'#1a2e2b' }}>${price.toLocaleString()}</p>
                    <p style={{ fontSize:'10px', color:'#8a9e9a' }}>/yr each</p>
                  </div>
                  {isSelected && <span style={{ color:'#1a2e2b', fontSize:'15px' }}>✓</span>}
                </button>
              )
            })}
          </div>

          <p style={{ fontSize:'10px', fontWeight:700, color:'#8a9e9a', textTransform:'uppercase', letterSpacing:'0.5px', marginBottom:'8px' }}>Quantity</p>
          <div style={{ display:'flex', alignItems:'center', gap:'12px', marginBottom:'18px' }}>
            <button onClick={()=>setQuantity(q=>Math.max(1, q-1))} disabled={quantity<=1}
              style={{ width:'36px', height:'36px', borderRadius:'9px', background:'white', border:'1.5px solid rgba(0,0,0,0.1)', fontSize:'18px', color:quantity<=1?'#c8d8d4':'#1a2e2b', cursor:quantity<=1?'not-allowed':'pointer', fontFamily:'inherit' }}>−</button>
            <span style={{ fontSize:'20px', fontWeight:700, color:'#1a2e2b', minWidth:'30px', textAlign:'center' }}>{quantity}</span>
            <button onClick={()=>setQuantity(q=>Math.min(10, q+1))} disabled={quantity>=10}
              style={{ width:'36px', height:'36px', borderRadius:'9px', background:'white', border:'1.5px solid rgba(0,0,0,0.1)', fontSize:'18px', color:quantity>=10?'#c8d8d4':'#1a2e2b', cursor:quantity>=10?'not-allowed':'pointer', fontFamily:'inherit' }}>+</button>
            <span style={{ fontSize:'11px', color:'#b0c0bc', marginLeft:'6px' }}>Cap 10 per request</span>
          </div>

          {/* issue 224 — both numbers, here, where the tier is chosen. This
              used to state the annual rate and promise the real figure on
              the next screen; the promise was kept, but choosing a tier
              against a price that isn't the price is the confusion Kevin
              hit. The server answers for the selected tier and quantity. */}
          <SeatPickerPriceBlock
            quoteState={quoteState}
            label={`${quantity} ${tierMeta?.name || tier} seat${quantity === 1 ? '' : 's'}`}
          />

          {error && (
            <p style={{ marginTop:'12px', padding:'8px 12px', background:'rgba(239,68,68,0.08)', border:'1px solid rgba(239,68,68,0.15)', borderRadius:'8px', color:'#ef4444', fontSize:'12px' }}>{error}</p>
          )}
            </>
          )}
        </div>

        {step === 'form' && (
          <div style={{ padding:'12px 22px', borderTop:'1px solid rgba(0,0,0,0.06)', display:'flex', gap:'8px' }}>
            <button onClick={onClose} style={{ flex:1, padding:'11px', background:'transparent', border:'1.5px solid rgba(0,0,0,0.1)', borderRadius:'10px', fontSize:'13px', fontFamily:'inherit', color:'#4a5e5a', cursor:'pointer' }}>Cancel</button>
            {/* issue 223 — no figure on this button. It used to quote a
                client-computed prorated total; the real one is on the next
                step and comes from the server. */}
            <button onClick={handleProceedToConfirm}
              style={{ flex:2, padding:'11px', background:'#1a2e2b', border:'none', borderRadius:'10px', fontSize:'13px', fontFamily:'inherit', fontWeight:600, color:'white', cursor:'pointer' }}>
              Review order →
            </button>
          </div>
        )}
      </div>
    </div>
  )
}

// ─── InviteTeamMemberModal ─────────────────────────────────────────────────
// Unified "+ Invite Team Member" entry point. Owner picks an email +
// tier; modal detects whether a seat at that tier is already available
// (factoring in pending invites — the API gates on the same math). If a
// seat exists, POST /api/hub_users/invite. If not, POST
// /api/seats/buy-and-invite, which creates the seat and the invite
// server-side in one step with rollback on partial failure.
//
// AddSeatsModal still exists for pre-buying ahead of inviting — see
// Settings > Billing.
// issue 224 — THE paidThroughDate PROP IS GONE, AND ITS ABSENCE IS THE POINT.
// This modal used to resolve the location's renewal date itself, to write the
// sentence "…before your renewal on <date>". The picker now names the date
// beside the figure, and both arrive together on the server's quote
// (cost.renewal_date, from the same read that priced the seat), so the date
// and the amount cannot come from different places.
//
// It also drops a fabrication. resolveLocationRenewalDate falls back to
// legacyFixedRenewalDate — March 1 — when a location has no
// paid_through_date, so a location with no anchor was shown a renewal date
// that is not its own. issue 217 refuses to invent that anchor server-side;
// the screen now refuses too, and says "at your renewal" with no date rather
// than naming the wrong one. issue 162's rule is unchanged and now lives in
// exactly one place.
export function InviteTeamMemberModal({ locationId, onClose, onInviteCreated, initialTier=null }) {
  const seatsCtx = useContext(SeatsContext)
  const tierPricesCtx = useContext(TierPricesContext)
  const getTierPrice = tierPricesCtx?.getTierPrice ?? (() => 0)

  const [step, setStep] = useState('form') // form | paymentConfirm | success
  const [email, setEmail] = useState('')
  const [fullName, setFullName] = useState('')
  // PURCHASABLE tiers. Owner is deliberately absent and must stay absent:
  // /api/seats/buy-and-invite rejects it, and lib/seat-stripe-sync maps a
  // tier to its own price 1:1 — so buying a co-owner seat would charge the
  // owner rate ($550) where the co-owner rule says manager rate ($400).
  // Selling an owner seat from here is therefore never correct (issue 216).
  const TIER_OPTIONS = SUBSCRIPTION_TIER_META.filter(t => t.key !== 'owner')

  // issue 216 — FILLING an existing owner seat is a different operation from
  // BUYING one, and only the second is unsafe. A location that already paid
  // for a co-owner seat has an unassigned owner row sitting in the pool; the
  // ghost row hands us initialTier='owner' for exactly that seat, and
  // /api/hub_users/invite has always accepted tier 'owner'.
  //
  // The old guard tested initialTier against TIER_OPTIONS — a list that
  // exists to describe what may be SOLD — so 'owner' failed a purchase test
  // it was never meant to take and silently fell through to TIER_OPTIONS[0],
  // Hive Manager. That made a paid co-owner seat uninvitable and put a wrong
  // -tier purchase prompt behind its Invite button.
  //
  // So owner is honoured here, and ONLY here, under three conditions:
  //   1. it was handed to us (never user-selectable — owner is not in the picker),
  //   2. a free owner seat actually exists right now, pending-aware,
  //   3. the location is within the 2-owner cap.
  // Every purchase seam below re-checks tier !== 'owner' independently.
  const counts = seatsCtx?.seatCountsByTier?.() || {}
  const freeOwnerSeats = seatsCtx?.availableSeatsByTierWithPending?.('owner') ?? 0
  const withinOwnerCap = (counts.owner?.total ?? 0) <= MAX_OWNER_SEATS
  const fillingOwnerSeat =
    initialTier === 'owner' && freeOwnerSeats >= 1 && withinOwnerCap

  // initialTier: preselect when opened from an open-seat ghost row. Ignored
  // if it isn't a real selectable tier (deferred tiers stay unselectable).
  const [tier, setTier] = useState(
    fillingOwnerSeat
      ? 'owner'
      : initialTier && TIER_OPTIONS.some(t => t.key === initialTier) && !isDeferredTier(initialTier)
        ? initialTier
        : (TIER_OPTIONS[0]?.key || 'manager')
  )
  // In owner-fill mode the tier is locked. Re-opening the picker would let a
  // click turn "fill the seat I own" into "buy a different seat" — the exact
  // confusion this fix removes.
  const tierLocked = fillingOwnerSeat && tier === 'owner'
  const [submitting, setSubmitting] = useState(false)
  const [error, setError] = useState('')
  const [createdInvite, setCreatedInvite] = useState(null)
  const [copied, setCopied] = useState(false)
  // issue 218 — the Payment-Link Stripe branch (pay → webhook seat →
  // invite, with a stripeWait step polling for the seat) is gone. It could
  // never run: no tier carries a payment_link_url, and
  // /api/seats/buy-and-invite never returned the 402 + pay_url that was its
  // other trigger. Deleted rather than wired — Payment Links are a second
  // charging mechanism competing with the Checkout Sessions the live paths
  // use. buy-and-invite bills the seat as a subscription line (issue 161).

  React.useEffect(() => {
    const prev = document.body.style.overflow
    document.body.style.overflow = 'hidden'
    return () => { document.body.style.overflow = prev }
  }, [])

  // Live availability for the currently-picked tier. Uses the same math
  // the server-side invite check uses (unassigned active seats minus
  // pending invites) so the UI never claims a seat is free when the API
  // would 409.
  const availableForTier = seatsCtx?.availableSeatsByTierWithPending?.(tier) ?? 0
  const isAvailable = availableForTier >= 1

  const tierMeta = SUBSCRIPTION_TIER_META.find(t => t.key === tier)

  // issue 224 — a seat must actually be BOUGHT for a price to be worth
  // naming. Filling a free seat costs nothing and never reaches the confirm
  // step, and an owner seat can be filled here but never bought (issue 216),
  // so neither is quoted: a price beside a tier that cannot be purchased is a
  // question nobody asked answered wrongly.
  const needsPurchase = !isAvailable && tier !== 'owner'
  const quoteState = useSeatQuote({
    locationId,
    tier,
    quantity: 1,
    active: needsPurchase || step === 'paymentConfirm',
  })
  const quoteView = seatQuoteView(quoteState, `${tierMeta?.name || tier} seat`)

  function isValidEmail(s) {
    return typeof s === 'string' && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(s.trim())
  }

  // Form-side submit. When the chosen tier has a free seat, fires
  // /api/hub_users/invite directly — no payment step needed. When a
  // purchase is required, hands off to the PaymentConfirmStep view;
  // the actual buy + invite POST runs from runBuyAndInvite() below.
  async function handleSubmit() {
    if (submitting) return
    if (!isValidEmail(email)) {
      setError('Enter a valid email address')
      return
    }
    if (!tier) {
      setError('Pick a tier')
      return
    }
    setError('')

    if (!isAvailable) {
      // issue 216 — PURCHASE GATE 1 of 3. Owner seats are fillable, never
      // buyable, from this modal. If the seat that got us here is gone (a
      // co-owner accepted while this was open, or someone else claimed it),
      // fail with an explanation rather than sliding into a purchase the
      // co-owner rule would misprice.
      if (tier === 'owner') {
        setError(
          'That co-owner seat is no longer free. Owner seats can be filled here but not bought — ask a Bee Organized admin to add one.',
        )
        return
      }
      setStep('paymentConfirm')
      return
    }

    await sendInvite()
  }

  // The invite half, against an available seat — the direct path, where
  // the seat is already pooled.
  async function sendInvite() {
    setSubmitting(true)
    try {
      const res = await fetch('/api/hub_users/invite', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          email: email.trim().toLowerCase(),
          full_name: fullName.trim() || null,
          location_id: locationId,
          tier,
        }),
      })
      const json = await res.json().catch(() => ({}))
      if (!res.ok) throw new Error(json.error || 'Failed to create invite')
      if (json.invite) {
        seatsCtx?.setPendingInvites?.(prev => [...prev, json.invite])
      }
      setCreatedInvite(json)
      setStep('success')
      if (onInviteCreated) onInviteCreated(json)
    } catch (err) {
      setError(err?.message || 'Could not complete invite')
      // Back to the form so the error is shown beside the fields that can
      // fix it, with the availability line re-read on the retry.
      setStep('form')
    } finally {
      setSubmitting(false)
    }
  }

  // Runs from PaymentConfirmStep's onConfirm. Single combined endpoint
  // so the seat + invite are written together with server-side rollback
  // on partial failure.
  async function runBuyAndInvite() {
    if (submitting) return
    // issue 216 — PURCHASE GATE 2 of 3. The last client-side thing standing
    // between an owner tier and a charge. /api/seats/buy-and-invite already
    // refuses tier 'owner' (its VALID_TIERS is manager/light/readonly), so
    // this is belt-and-braces — but it keeps the refusal legible here rather
    // than surfacing as an opaque 400 after a confirm click.
    if (tier === 'owner') {
      setError('Owner seats cannot be purchased here.')
      setStep('form')
      return
    }
    setSubmitting(true)
    setError('')
    try {
      const res = await fetch('/api/seats/buy-and-invite', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        // issue 223 — no prorated_cost. The server prices the seat (issue
        // 217) and the confirm screen showed that same price.
        body: JSON.stringify({
          location_id: locationId,
          tier,
          email: email.trim().toLowerCase(),
          full_name: fullName.trim() || null,
        }),
      })
      const json = await res.json().catch(() => ({}))
      if (!res.ok) throw new Error(json.error || 'Failed to buy seat and invite')
      if (json.seat) {
        seatsCtx?.setSeats?.(prev => [...prev, json.seat])
      }
      if (json.invite) {
        seatsCtx?.setPendingInvites?.(prev => [...prev, json.invite])
      }
      setCreatedInvite(json)
      setStep('success')
      if (onInviteCreated) onInviteCreated(json)
    } catch (err) {
      setError(err?.message || 'Could not complete invite')
    } finally {
      setSubmitting(false)
    }
  }

  async function copyLink() {
    if (!createdInvite?.invite_url) return
    try {
      await navigator.clipboard.writeText(createdInvite.invite_url)
      setCopied(true)
      setTimeout(() => setCopied(false), 1500)
    } catch {}
  }

  const mailto = createdInvite
    ? `mailto:${encodeURIComponent(createdInvite.invite?.email || '')}?subject=${encodeURIComponent('You’re invited to Bee Hub')}&body=${encodeURIComponent(`Join our team on Bee Hub: ${createdInvite.invite_url}`)}`
    : ''

  const submitLabel = submitting
    ? (isAvailable ? 'Sending…' : 'Buying…')
    : isAvailable
      ? 'Send Invite →'
      // issue 223 — no client-computed figure on the button; the real one is
      // on the confirm step, from the server.
      : 'Buy & Send Invite →'

  return (
    <div style={{ position:'fixed', inset:0, zIndex:10020, display:'flex', alignItems:'center', justifyContent:'center', padding:'12px' }}>
      <div style={{ position:'absolute', inset:0, background:'rgba(26,46,43,0.5)' }} onClick={onClose} />
      <div style={{ position:'relative', background:'white', borderRadius:'14px', width:'100%', maxWidth:'440px', maxHeight:'90vh', display:'flex', flexDirection:'column', boxShadow:'0 16px 48px rgba(26,46,43,0.25)', overflow:'hidden', zIndex:1 }}>
        <div style={{ padding:'18px 22px 4px', borderBottom:'1px solid rgba(0,0,0,0.06)' }}>
          <div style={{ display:'flex', justifyContent:'space-between', alignItems:'flex-start' }}>
            <div>
              <h2 style={{ fontSize:'18px', fontFamily:'Georgia,serif', color:'#1a2e2b', marginBottom:'4px' }}>
                {step === 'success' ? 'Invitation created'
                  : step === 'paymentConfirm' ? 'Confirm payment'
                  : 'Invite a team member'}
              </h2>
              <p style={{ fontSize:'12px', color:'#8a9e9a', lineHeight:1.5 }}>
                {step === 'success'
                  ? 'The link below expires in 7 days.'
                  : step === 'paymentConfirm'
                    ? `Buys 1 ${tierMeta?.name || tier} seat and sends the invite to ${email}.`
                    : 'They’ll sign in with Google to claim their seat.'}
              </p>
            </div>
            <button onClick={onClose} style={{ background:'none', border:'none', fontSize:'22px', color:'#8a9e9a', cursor:'pointer', lineHeight:1, padding:'0 0 0 8px' }}>×</button>
          </div>
        </div>

        <div style={{ padding:'16px 22px', overflowY:'auto', flex:1 }}>
          {step === 'form' && (
            <>
              <p style={{ fontSize:'10px', fontWeight:700, color:'#8a9e9a', textTransform:'uppercase', letterSpacing:'0.5px', marginBottom:'6px' }}>Email *</p>
              <input
                type="email" value={email} onChange={e=>setEmail(e.target.value)}
                placeholder="teammate@example.com"
                style={{ width:'100%', padding:'10px 12px', border:'1.5px solid rgba(0,0,0,0.1)', borderRadius:'9px', fontSize:'14px', fontFamily:'inherit', color:'#1a2e2b', outline:'none', boxSizing:'border-box', marginBottom:'14px' }}
              />
              <p style={{ fontSize:'10px', fontWeight:700, color:'#8a9e9a', textTransform:'uppercase', letterSpacing:'0.5px', marginBottom:'6px' }}>Full name (optional)</p>
              <input
                type="text" value={fullName} onChange={e=>setFullName(e.target.value)}
                placeholder="Jane Doe"
                style={{ width:'100%', padding:'10px 12px', border:'1.5px solid rgba(0,0,0,0.1)', borderRadius:'9px', fontSize:'14px', fontFamily:'inherit', color:'#1a2e2b', outline:'none', boxSizing:'border-box', marginBottom:'14px' }}
              />
              <p style={{ fontSize:'10px', fontWeight:700, color:'#8a9e9a', textTransform:'uppercase', letterSpacing:'0.5px', marginBottom:'6px' }}>Tier *</p>
              {/* issue 216 — owner-fill mode. The seat is already bought and
                  already the right tier; showing a picker here would only
                  offer ways to turn filling it into buying something else.
                  Render the seat being filled instead. */}
              {tierLocked ? (
                <div
                  data-testid="invite-tier-locked"
                  style={{ padding:'11px 12px', background:'rgba(26,46,43,0.04)', border:'2px solid #1a2e2b', borderRadius:'10px', display:'flex', alignItems:'center', gap:'10px', marginBottom:'10px' }}>
                  <span style={{ fontSize:'18px' }}>{tierMeta?.icon || '👑'}</span>
                  <div style={{ flex:1, minWidth:0 }}>
                    <p style={{ fontSize:'13px', fontWeight:600, color:'#1a2e2b' }}>{tierMeta?.name || 'Zee Bee'}</p>
                    <p style={{ fontSize:'10.5px', color:'#8a9e9a' }}>Filling the open co-owner seat you already pay for</p>
                  </div>
                  <span style={{ fontSize:'9px', fontWeight:700, color:'#15803d', background:'rgba(34,197,94,0.1)', border:'1px solid rgba(34,197,94,0.28)', padding:'2px 8px', borderRadius:'10px', textTransform:'uppercase', letterSpacing:'0.4px', flexShrink:0 }}>Paid</span>
                </div>
              ) : (
              <div style={{ display:'grid', gap:'8px', marginBottom:'10px' }}>
                {TIER_OPTIONS.map(t => {
                  const isSelected = tier === t.key
                  const deferred = isDeferredTier(t.key)
                  const availAtT = seatsCtx?.availableSeatsByTierWithPending?.(t.key) ?? 0
                  return (
                    <button key={t.key} onClick={()=>{ if (!deferred) setTier(t.key) }}
                      disabled={deferred}
                      aria-disabled={deferred}
                      style={{ padding:'11px 12px', background:isSelected?'rgba(26,46,43,0.04)':'white', border:`2px solid ${isSelected?'#1a2e2b':'rgba(0,0,0,0.08)'}`, borderRadius:'10px', cursor:deferred?'not-allowed':'pointer', fontFamily:'inherit', textAlign:'left', display:'flex', alignItems:'center', gap:'10px', opacity: deferred ? 0.55 : 1 }}>
                      <span style={{ fontSize:'18px' }}>{t.icon}</span>
                      <div style={{ flex:1, minWidth:0 }}>
                        <p style={{ fontSize:'13px', fontWeight:600, color:'#1a2e2b' }}>{t.name}</p>
                        <p style={{ fontSize:'10.5px', color:'#8a9e9a' }}>
                          {/* issue 223 — the RATE, not a prorated figure.
                              This quoted a browser-computed amount for a
                              purchase the server prices; the real cost is
                              shown on the confirm step. */}
                          {deferred
                            ? 'Coming soon'
                            : availAtT > 0
                              ? `${availAtT} available`
                              : `none available — ${formatCurrency(getTierPrice(t.key), { showCents:'never' })}/yr`}
                        </p>
                      </div>
                      {deferred ? (
                        <span style={{ fontSize:'9px', fontWeight:700, color:'#d4a046', background:'rgba(212,160,70,0.12)', border:'1px solid rgba(212,160,70,0.3)', padding:'2px 8px', borderRadius:'10px', textTransform:'uppercase', letterSpacing:'0.4px', flexShrink:0 }}>Coming Soon</span>
                      ) : (
                        isSelected && <span style={{ color:'#1a2e2b', fontSize:'15px' }}>✓</span>
                      )}
                    </button>
                  )
                })}
              </div>
              )}

              {/* Live status line — recalculates as the tier changes. Green
                  when a seat is already pooled, amber when a purchase is
                  required to send this invite. */}
              {isAvailable ? (
                <div style={{ marginBottom:'10px', padding:'9px 12px', background:'rgba(34,197,94,0.06)', border:'1px solid rgba(34,197,94,0.18)', borderRadius:'9px' }}>
                  <p style={{ fontSize:'12px', color:'#15803d', fontWeight:500 }}>
                    ✓ {availableForTier} {tierMeta?.name || tier} seat{availableForTier === 1 ? '' : 's'} available at this location
                  </p>
                </div>
              ) : (
                <>
                  <div style={{ marginBottom:'10px', padding:'9px 12px', background:'rgba(245,158,11,0.07)', border:'1px solid rgba(245,158,11,0.22)', borderRadius:'9px' }}>
                    <p style={{ fontSize:'12px', color:'#92400e', fontWeight:500 }}>
                      No {tierMeta?.name || tier} seats available — purchase 1 to invite
                    </p>
                  </div>

                  {/* issue 224 — THE BLOCK KEVIN WAS LOOKING AT. It read
                      "1 Hive Manager seat / $400/yr" over "you only pay for
                      the part of the year that's left … we'll show you that
                      amount before anything is charged": a price that was
                      not the price, attached to a choice, with the real
                      figure held back a screen. Now it names what is charged
                      today and what renews each year, both from the server's
                      quote for THIS tier. */}
                  {needsPurchase && (
                    <div style={{ marginBottom:'10px' }}>
                      <SeatPickerPriceBlock quoteState={quoteState} label={`1 ${tierMeta?.name || tier} seat`} />
                    </div>
                  )}

                  <p style={{ fontSize:'11px', color:'#8a9e9a', lineHeight:1.5, marginBottom:'8px' }}>
                    Pays for 1 seat and sends the invitation in one step. Seat returns to your pool if the invitation expires or is removed.
                  </p>
                </>
              )}

              {error && (
                <p style={{ marginTop:'12px', padding:'8px 12px', background:'rgba(239,68,68,0.08)', border:'1px solid rgba(239,68,68,0.15)', borderRadius:'8px', color:'#ef4444', fontSize:'12px' }}>{error}</p>
              )}
            </>
          )}

          {step === 'paymentConfirm' && (
            quoteState.loading ? (
              <SeatQuotePending onCancel={() => { setError(''); setStep('form') }} />
            ) : !quoteView ? (
              <SeatQuoteFailed message={quoteState.error} onCancel={() => { setError(''); setStep('form') }} />
            ) : (
              <PaymentConfirmStep
                title="Confirm seat purchase"
                lineItems={[{
                  label: quoteView.totalDollars === null
                    ? `1 ${tierMeta?.name || tier} seat`
                    : `1 ${tierMeta?.name || tier} seat (rest of your year)`,
                  // The SERVER's figure — issue 223.
                  amount: quoteView.totalDollars ?? 0,
                }]}
                total={quoteView.totalDollars ?? 0}
                confirmLabel="Confirm & Send Invite"
                onConfirm={runBuyAndInvite}
                onCancel={() => { setError(''); setStep('form') }}
                isProcessing={submitting}
                error={error || null}
                notice={quoteView.notice}
              />
            )
          )}

          {step === 'success' && createdInvite && (
            <>
              {/* Email delivery outcome — both invite endpoints return
                  email_sent. Green = delivered, amber = the owner must share
                  the link themselves or the invite silently goes nowhere. */}
              {createdInvite.email_sent ? (
                <div style={{ marginBottom:'14px', padding:'9px 12px', background:'rgba(34,197,94,0.06)', border:'1px solid rgba(34,197,94,0.18)', borderRadius:'9px' }}>
                  <p style={{ fontSize:'12px', color:'#15803d', fontWeight:500 }}>
                    ✓ Invitation email sent to {createdInvite.invite?.email}
                  </p>
                </div>
              ) : (
                <div style={{ marginBottom:'14px', padding:'9px 12px', background:'rgba(245,158,11,0.07)', border:'1px solid rgba(245,158,11,0.22)', borderRadius:'9px' }}>
                  <p style={{ fontSize:'12px', color:'#92400e', fontWeight:600, marginBottom:'2px' }}>
                    ⚠️ Invitation email could not be sent
                  </p>
                  <p style={{ fontSize:'11.5px', color:'#92400e', lineHeight:1.5 }}>
                    The invite was created, but no email went out — share the link below with them directly.
                  </p>
                </div>
              )}
              <div style={{ marginBottom:'14px' }}>
                <p style={{ fontSize:'12px', color:'#8a9e9a', marginBottom:'4px' }}>Share with</p>
                <p style={{ fontSize:'14px', fontWeight:600, color:'#1a2e2b', wordBreak:'break-all' }}>{createdInvite.invite?.email}</p>
              </div>
              <p style={{ fontSize:'10px', fontWeight:700, color:'#8a9e9a', textTransform:'uppercase', letterSpacing:'0.5px', marginBottom:'6px' }}>Invite link</p>
              <div style={{ display:'flex', gap:'6px', alignItems:'stretch', marginBottom:'12px' }}>
                <input readOnly value={createdInvite.invite_url}
                  style={{ flex:1, padding:'10px 12px', border:'1.5px solid rgba(0,0,0,0.08)', borderRadius:'9px', fontSize:'12px', fontFamily:'inherit', color:'#1a2e2b', outline:'none', background:'rgba(26,46,43,0.02)', boxSizing:'border-box' }}
                  onClick={e=>e.currentTarget.select()}
                />
                <button onClick={copyLink}
                  style={{ padding:'10px 14px', background:copied?'#22c55e':'#1a2e2b', border:'none', borderRadius:'9px', fontSize:'12px', fontFamily:'inherit', fontWeight:600, color:'white', cursor:'pointer', flexShrink:0 }}>
                  {copied ? 'Copied ✓' : 'Copy'}
                </button>
              </div>
              <a href={mailto}
                style={{ display:'block', textAlign:'center', padding:'10px', background:'rgba(26,46,43,0.04)', border:'1px solid rgba(26,46,43,0.08)', borderRadius:'9px', fontSize:'12px', color:'#1a2e2b', textDecoration:'none', fontWeight:500 }}>
                Open in mail client →
              </a>
            </>
          )}
        </div>

        {step !== 'paymentConfirm' && (
          <div style={{ padding:'12px 22px', borderTop:'1px solid rgba(0,0,0,0.06)', display:'flex', gap:'8px' }}>
            {step === 'form' && (
              <>
                <button onClick={onClose} style={{ flex:1, padding:'11px', background:'transparent', border:'1.5px solid rgba(0,0,0,0.1)', borderRadius:'10px', fontSize:'13px', fontFamily:'inherit', color:'#4a5e5a', cursor:'pointer' }}>Cancel</button>
                <button onClick={handleSubmit} disabled={submitting}
                  style={{ flex:2, padding:'11px', background:submitting?'#8a9e9a':'#1a2e2b', border:'none', borderRadius:'10px', fontSize:'13px', fontFamily:'inherit', fontWeight:600, color:'white', cursor:submitting?'wait':'pointer' }}>
                  {submitLabel}
                </button>
              </>
            )}
            {step === 'success' && (
              <button onClick={onClose} style={{ flex:1, padding:'11px', background:'#1a2e2b', border:'none', borderRadius:'10px', fontSize:'13px', fontFamily:'inherit', fontWeight:600, color:'white', cursor:'pointer' }}>
                Done
              </button>
            )}
          </div>
        )}
      </div>
    </div>
  )
}

// ROUTE_TO_NAV, NAV_TO_URL, parseHubUrl, clientPath now live in
// @/components/hive/shared/hubUrl (imported above) so the pure URL↔state
// mapping is unit-testable. nextRecordOverlay there drives the beta
// board's URL→overlay sync.

export default function App({
  currentUser,
  initialRoute,              // URL-derived route slug ('clients', 'reports', etc.) — maps to activeNav via ROUTE_TO_NAV
  initialSelectedLeadId,     // /clients/[id] deep link — opens the client overlay on mount
  initialSelectedEngagementId, // /clients/[id]?e=<engagementId> deep link — opens EngagementPanel on mount (server-validated: belongs to the scoped client)
  notFoundToast,             // /clients?notfound=1 — fired by HubPage when /clients/[bad-id] redirects here
  initialRole,
  initialFranchiseRole,
  initialLocFilter,
  initialGuideSlides,        // server-rendered slides from page.tsx (Supabase guide_slides table)
  initialManualSlides,       // server-rendered manual slides from page.tsx (Supabase manual_slides table)
  initialTierPrices,         // server-rendered seat pricing from page.tsx (Supabase tier_prices table)
  initialLocations,          // accepted; not yet consumed — ALL_LOCATIONS mock still drives the picker
  initialUsers,              // real hub_users roster from Supabase; null → fall back to USERS_DATA mock
  initialSeats,              // server-rendered subscription_seats for the current location (empty array for elevated users)
 initialPendingInvites,     // server-rendered pending_invites for the current location (empty array for elevated users)
  initialLookups,            // server-rendered admin-managed lookups grouped by category (Sitting 1A)
  initialPeople,             // server-rendered Supabase leads → Person shape (Phase 3A); null/empty → fall back to ALL_PEOPLE mock
  initialBinPeople,          // server-rendered is_junk=true leads (Recycle Bin)
  initialAllOverview,        // Fix 2 Phase 4: server-reduced corporate overview for 'All Locations' (null on a scoped load) — replaces the people graph on that scope
  initialLeadsTruncated,     // true when the leads load hit MAX_LEADS; rendered as a banner so a short count is never presented as complete
  initialNetworkTruncated,   // true when the partners/companies load hit MAX_NETWORK_ROWS; the Network screen states the shortfall
  initialTransferPeople,     // loc_other unrouted leads — fetched OUTSIDE the selected scope so the routing queue survives a location switch (Fix 2 Phase 2). Elevated only; [] for franchise.
  initialScopeLocationId,    // the location the SERVER actually scoped to (null = all) — the client reconciles its cookie to this after hydration
  initialEngagements,        // Phase 1 step 4: open engagements for the new board (dual-read; super_admin-flagged)
  initialEngagementsClosedCount, // Phase 1 step 4: 'Closed · N' chip count (List lens; rows page in lazily)
  initialEngagementsClosedWonCount, // won share of the closed count (Won/Lost chips; lost = closed − won)
  initialPartners,           // server-rendered partners+contacts (Supabase partners table); replaces PARTNERS_DATA mock
  initialCompanies,          // server-rendered companies (Supabase companies table); replaces COMPANIES_DATA mock
  currentSubscription,
  currentLocation,           // real Supabase row for franchise owners; null for elevated users
} = {}) {
  const router = useRouter()
  const [role, setRole]                     = useState(initialRole ?? 'super_admin')
  const [toast, setToast]                   = useState(null)
  useEffect(() => {
    if (!toast) return
    const t = setTimeout(() => setToast(null), 3000)
    return () => clearTimeout(t)
  }, [toast])
  // Hive Hub Guide: slides come from Supabase via page.tsx → initialGuideSlides.
  // No client-side defaults — empty array stays empty, modal stays hidden.
  const [guideSlides, setGuideSlides]       = useState(Array.isArray(initialGuideSlides) ? initialGuideSlides : [])
  const [showGuide, setShowGuide]           = useState(false) // SSR-safe: open only after client-side localStorage check
  const [showHelpChat, setShowHelpChat]     = useState(false) // "Ask Bee Hub" screen-aware help chat panel
  // First-time discovery hint pointing at the Ask Bee Hub pill. Replaces the
  // old auto-open-the-Guide-on-first-visit behavior — instead of shoving the
  // full modal in a new owner's face, we nudge them toward the help icon.
  const [showGuideHint, setShowGuideHint]   = useState(false)
  useEffect(() => {
    // Skip while the user is still in onboarding — let them finish setup first.
    // For Invite-Owner launches this naturally fires post-launch (lifecycle
    // flips to 'active', the hint shows on the next mount).
    if (currentLocation?.lifecycle_status === 'onboarding') return
    try {
      if (guideSlides.length > 0 && !localStorage.getItem('bee_guide_dismissed')) setShowGuideHint(true)
    } catch (e) { /* private mode / disabled storage */ }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])
  // Mark the guide intro as seen (reuses the same key the Guide modal sets on
  // dismiss) so the first-time hint never shows again for this user.
  function dismissGuideHint() {
    setShowGuideHint(false)
    try { localStorage.setItem('bee_guide_dismissed', '1') } catch (e) { /* private mode */ }
  }
  // Persistent entry point for the Hive Hub Guide — the "Quick Start Guide"
  // link in the Ask Bee Hub panel footer. Opening it also retires the
  // first-time hint.
  function openGuide() {
    dismissGuideHint()
    setShowGuide(true)
  }

  // Hydrate admin-managed lookups from DB on mount (Sitting 1A).
  // initialLookups comes from page.tsx server-side fetch keyed by category.
  // Each branch reshapes to the legacy in-memory format expected by existing
  // getters so UI call sites (getSpecialties, getPartnerTiers, etc.) keep
  // working without changes. ConfigureTab edits remain in-memory in 1A —
  // Sitting 1B wires the writes through to the lookups API.
  useEffect(() => {
    if (!initialLookups || typeof initialLookups !== 'object') return

    const toStageShape = (rows) => rows.map(r => ({
      key:   (r.attrs && r.attrs.key) || r.label,
      label: r.label,
      color: r.color || '#8a9e9a',
      bg:    r.bg_color || 'rgba(138,158,154,0.08)',
      dot:   r.color || '#8a9e9a',
      icon:  r.icon || '',
    }))
    const toTagShape = (rows) => rows.map(r => ({
      id:    (r.attrs && r.attrs.key) || r.id,
      label: r.icon ? `${r.icon} ${r.label}` : r.label,
      color: r.color || '#8a9e9a',
      bg:    r.bg_color || 'rgba(138,158,154,0.1)',
    }))
    const toSpecialtyShape = (rows) => rows.map(r => ({
      id:    (r.attrs && r.attrs.key) || r.id,
      label: r.icon ? `${r.icon} ${r.label}` : r.label,
      color: r.color || '#8a9e9a',
      bg:    r.bg_color || 'rgba(138,158,154,0.1)',
    }))
    const toTierShape = (rows) => rows.map(r => ({
      id:    (r.attrs && r.attrs.key) || r.id,
      label: r.label,
      color: r.color || '#8a9e9a',
      bg:    r.bg_color || 'rgba(138,158,154,0.15)',
      desc:  r.description || '',
    }))
    const toTouchpointShape = (rows) => rows.map(r => ({
      key:   (r.attrs && r.attrs.key) || r.id,
      icon:  r.icon || '',
      label: r.label,
    }))

    if (Array.isArray(initialLookups.partner_stages))      setAdminPartnerStages(toStageShape(initialLookups.partner_stages))
    if (Array.isArray(initialLookups.client_tags)) {
      setAdminClientTags(toTagShape(initialLookups.client_tags))
      setAdminClientTagsRaw(initialLookups.client_tags)
    }
    if (Array.isArray(initialLookups.partner_specialties)) setAdminSpecialties(toSpecialtyShape(initialLookups.partner_specialties))
    if (Array.isArray(initialLookups.partner_tiers))       setAdminPartnerTiers(toTierShape(initialLookups.partner_tiers))
    if (Array.isArray(initialLookups.touchpoint_types))    setAdminTouchpointTypes(toTouchpointShape(initialLookups.touchpoint_types))

    if (Array.isArray(initialLookups.lead_sources)) {
      setAdminLeadSources(initialLookups.lead_sources.map(r => r.label))
    }

    if (Array.isArray(initialLookups.closed_lost_reasons)) {
      setCloseLostReasons(initialLookups.closed_lost_reasons.map(r => r.label))
    }

    if (Array.isArray(initialLookups.project_types)) {
      setAdminProjectTypes(
        initialLookups.project_types.map(r => ({
          label: r.label,
          drip_category: (r.attrs && r.attrs.drip_category) || 'general',
        }))
      )
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  // Hive Hub Manual: reference-only, never auto-opens, no dismiss flag.
  const [manualSlides, setManualSlides]     = useState(Array.isArray(initialManualSlides) ? initialManualSlides : [])
  const [showManual, setShowManual]         = useState(false)
  // Feedback / bug-report modal — false | true | 'submit'. The "? Help"
  // pill's 3rd option sets true (modal opens on its My Items default);
  // the Feedback screen's composer button sets 'submit' (lands on the
  // Submit tab). One modal, one state, two entry intents.
  const [showFeedback, setShowFeedback]     = useState(false)
  // Deep link from the reply email (issue 233): /?feedback=1 opens My Items on
  // top of whatever screen the app restores. That tab is the one surface that
  // renders a reply AS a reply, and it works for every role — the owner/manager
  // Feedback nav does not exist for anyone else. Applied once, on mount.
  useEffect(() => {
    try {
      if (new URLSearchParams(window.location.search).get('feedback')) setShowFeedback(true)
    } catch {}
  }, [])
  // Record-context seed for the feedback modal — set when the modal is opened
  // FROM a record (e.g. "Report a problem with this client"). Carries the
  // pre-fill + the id-only context; cleared when the modal closes.
  const [feedbackSeed, setFeedbackSeed]     = useState(null)
  // Open the feedback modal on the Submit tab, seeded from a record. Called by
  // the client profile's "···" menu (threaded through HiveScreen / DashboardScreen
  // → HiveShell → ClientProfile). type is always 'bug' from this path.
  const openRecordReport = (seed) => {
    setFeedbackSeed({ type: 'bug', title: seed?.title || '', context: seed?.context || null })
    setShowFeedback('submit')
  }
  // Seat pricing: single source of truth from Supabase tier_prices. Falls back
  // to DEFAULT_TIER_PRICES synthetic rows if the table is empty / unmigrated,
  // so renders never crash on a fresh environment.
  const [tierPrices, setTierPricesState]    = useState(
    Array.isArray(initialTierPrices) && initialTierPrices.length > 0
      ? initialTierPrices
      : Object.entries(DEFAULT_TIER_PRICES).map(([id, price_annual], i) => ({
          id,
          display_name: id,
          price_annual,
          description: null,
          sort_order: i + 1,
          updated_at: null,
        }))
  )
  const getTierPrice = (tierId) => {
    const row = tierPrices.find(t => t.id === tierId)
    return row?.price_annual ?? DEFAULT_TIER_PRICES[tierId] ?? 0
  }
  const livePrices = {
    owner:    getTierPrice('owner'),
    manager:  getTierPrice('manager'),
    light:    getTierPrice('light'),
    readonly: getTierPrice('readonly'),
  }
  // Stripe Payment Link per tier — null until Kevin pastes links in
  // Admin > Pricing (and the tier_prices_payment_links migration is
  // applied; pre-migration rows simply lack the column → null → every
  // pay surface falls back to the record-only flow).
  const getTierLink = (tierId) => {
    const row = tierPrices.find(t => t.id === tierId)
    return row?.payment_link_url || null
  }
  const tierPricesValue = {
    tierPrices,
    setTierPrices: setTierPricesState,
    getTierPrice,
    getTierLink,
    livePrices,
  }
  // Subscription seats — pool model. Onboarding Activate seeds the first
  // owner seat; "+ Add seats" (Dispatch 3) and team invite assignment mutate
  // this state. Defaults to [] so renders never crash on a pre-migration env.
  const [seats, setSeats] = useState(Array.isArray(initialSeats) ? initialSeats : [])
  // prop→state sync after router.refresh() — see the partners/companies/users
  // effects below for why these were missing. Seats are per-location, so a
  // scope switch that didn't refresh this would show the previous location's
  // seat counts in Settings → Billing.
  useEffect(() => {
    if (Array.isArray(initialSeats)) setSeats(initialSeats)
  }, [initialSeats])
  // Pending (unaccepted) invites — kept in context so InviteTeamMemberModal
  // can subtract them from raw seat counts to match the server-side check
  // in /api/hub_users/invite (which would otherwise return 409 after the
  // UI claimed a seat was free).
  const [pendingInvites, setPendingInvites] = useState(
    Array.isArray(initialPendingInvites) ? initialPendingInvites : []
  )
  // Seats with scheduled_removal_at are still active and billable, but they
  // are NOT available for invite — a new member seated there would lose
  // access on the removal date. They count toward total (and `scheduled`),
  // never toward available. Mirrors the server gates in /api/hub_users/invite
  // and /api/hub_users/accept.
  // issue 216 — every one of these delegates to lib/seat-availability, which
  // is the single definition of "is a seat free at this tier?" and mirrors
  // the server gate in /api/hub_users/invite. The roster, the seat card and
  // the invite modal previously each answered that question their own way
  // and disagreed about the same rows; keeping the math in one tested module
  // is what stops that recurring.
  function seatCountsByTier() {
    return seatCounts(seats, pendingInvites)
  }
  function availableSeatsByTier() {
    return availableSeatRows(seats, pendingInvites)
  }
  function availableSeatsByTierWithPending(tier) {
    return availableSeatsForTier(seats, pendingInvites, tier)
  }
  function pendingInviteCount(tier) {
    return pendingInvitesAtTier(pendingInvites, tier)
  }
  function invitableSeatIds() {
    return invitableIds(seats, pendingInvites)
  }
  const seatsValue = {
    seats,
    setSeats,
    pendingInvites,
    setPendingInvites,
    seatCountsByTier,
    availableSeatsByTier,
    availableSeatsByTierWithPending,
    pendingInviteCount,
    invitableSeatIds,
  }
  const [franchiseRole, setFranchiseRole]   = useState(initialFranchiseRole ?? 'owner') // owner|manager|light|readonly
  const [activeNav, setActiveNav]           = useState(ROUTE_TO_NAV[initialRoute] || 'home')
  // Deep link: /admin?adminTab=webhooks (the Slack failure digest links land
  // here). The legacy AdminScreen parses this param itself, but elevated users
  // render SuperAdminLayout instead — map it to the layout's initial section.
  // super_admin only: webhook internals aren't a corporate surface, matching
  // the legacy showWebhooksTab gate.
  const [adminDeepLinkSection, setAdminDeepLinkSection] = useState(null)
  useEffect(() => {
    try {
      const t = new URLSearchParams(window.location.search).get('adminTab')
      // issue 226 step 8 — the retired keys are mapped explicitly rather than
      // left to fall through to the dashboard default. 'conversions' lands on
      // Locations, where finding those locations now happens; 'removals' on
      // the Dashboard, where the processor card lives. SuperAdminLayout
      // re-resolves these too, so a stale value from anywhere is caught.
      if (t === 'conversions' && (role === 'super_admin' || role === 'corporate')) setAdminDeepLinkSection('locations')
      else if (t === 'removals' && (role === 'super_admin' || role === 'corporate')) setAdminDeepLinkSection('dashboard')
      else if (t === 'pricing' && role === 'super_admin') setAdminDeepLinkSection('pricing')
      else if (t === 'webhooks' && role === 'super_admin') setAdminDeepLinkSection('webhooks')
      // Feedback is a broader surface than webhooks — both elevated roles,
      // mirroring the legacy AdminScreen showFeedbackTab gate.
      else if (t === 'feedback' && (role === 'super_admin' || role === 'corporate')) setAdminDeepLinkSection('feedback')
      // System Health — same elevated gate as Feedback (super_admin + admin/
      // corporate). The digest's Slack liveness link can land here.
      else if (t === 'health' && (role === 'super_admin' || role === 'corporate')) setAdminDeepLinkSection('health')
    } catch {}
  }, []) // eslint-disable-line react-hooks/exhaustive-deps
  const [viewAsTarget, setViewAsTarget]     = useState(null)
  const [viewAsUser, setViewAsUser]         = useState(null) // full user object when viewing as specific user
  const [locFilter, setLocFilter]           = useState(initialLocFilter ?? 'all')
  // ── Scope switch (Fix 2, Phase 1) ──────────────────────────────────────────
  // locFilter used to be a purely client-side array filter, so the server never
  // learned which location was selected and shipped the whole tenant every
  // load. `applyLocScope` is now the ONLY way locFilter changes: it writes the
  // scope cookie the server reads, then router.refresh()es so the RSC re-runs
  // its queries narrowed to that location.
  //
  // Every setLocFilter call site goes through here — including the view-as
  // enter/exit paths. That is load-bearing, not tidiness: view-as points
  // locFilter at the impersonated user's location, and if the cookie did not
  // follow, the server would keep shipping the PREVIOUS scope while the client
  // filtered for the new one — intersecting to an empty screen.
  //
  // Failure is non-fatal by construction: if the cookie write throws (private
  // mode, disabled storage) the client-side filter still applies and the server
  // simply keeps its previous scope — the pre-Phase-1 behavior. Never let a
  // cookie failure block the scope change the user asked for.
  // ── Switch feedback ────────────────────────────────────────────────────────
  // router.refresh() re-fetches the RSC payload and reconciles it into the
  // EXISTING tree: nothing unmounts, no Suspense boundary engages, no
  // loading.tsx fires. So the old location's content sat there fully rendered
  // and fully interactive for the whole round trip with no acknowledgment that
  // the click had registered — there was simply no loading state in the tree
  // for a loader to attach to.
  //
  // useTransition is what React provides for exactly this: isPending goes true
  // synchronously on click and false when the refreshed payload has committed.
  // It is the only thing that knows the refresh is still in flight.
  const [isScopePending, startScopeTransition] = React.useTransition()
  const applyLocScope = React.useCallback((next) => {
    setLocFilter(next)
    try {
      document.cookie = scopeCookieString(next === 'all' ? SCOPE_ALL : next)
    } catch (e) {
      console.error('[scope] cookie write failed, server scope unchanged:', e)
    }
    // Re-runs the server component with the new cookie. React state (open
    // panels, selections, scroll) is preserved; only the initial* props change,
    // which the prop-sync effects below fold into state.
    //
    // Inside a transition so the pending state above tracks it. The refresh
    // itself is unchanged — this wraps it, it does not replace it.
    try {
      startScopeTransition(() => { router.refresh() })
    } catch (e) {
      console.error('[scope] refresh failed:', e)
    }
  }, [router])
  // ── Cookie reconcile (Fix 2, Phase 2) ──────────────────────────────────────
  // Make the cookie say what the server ACTUALLY scoped to. A Server Component
  // cannot write cookies (see the try/catch in lib/supabase-server.ts), so when
  // the server overrides the requested scope the correction has to land here,
  // after hydration.
  //
  // The case that needs it: a /clients/<id> deep link to a lead outside the
  // selected location. The server switches scope to that lead's location and
  // renders the page around it — but the cookie still names the old one, so the
  // NEXT navigation would bounce the user back and the lead they just opened
  // would fall out of scope again. Writing it here makes the switch stick.
  //
  // It also self-heals a cookie naming a deleted location (server fell back to
  // 'all', cookie still points at the dead id), which would otherwise re-log a
  // warning on every single request.
  //
  // Deliberately NO router.refresh(): the render in front of the user is
  // already the correct one. This only records it. Refreshing here would be an
  // infinite loop.
  //
  // `undefined` and `null` mean DIFFERENT things here and the distinction is
  // load-bearing: null is the server saying "I used all locations" (reconcile
  // to that), undefined is no server prop at all — a demo/test mount — where
  // writing the cookie would silently reset a real user's scope to 'all'.
  const serverScope = initialScopeLocationId === undefined ? null : (initialScopeLocationId || SCOPE_ALL)
  useEffect(() => {
    if (serverScope === null) return
    try {
      const current = document.cookie
        .split('; ')
        .find(c => c.startsWith(`${SCOPE_COOKIE_NAME}=`))
        ?.slice(SCOPE_COOKIE_NAME.length + 1) || SCOPE_ALL
      if (current === serverScope) return
      document.cookie = scopeCookieString(serverScope)
      console.log(`[scope] cookie reconciled ${current} → ${serverScope} (server-resolved scope)`)
    } catch (e) {
      // Non-fatal: the current render is already correct, only persistence is
      // lost. Degrades to the pre-Phase-2 behavior for the next navigation.
      console.error('[scope] cookie reconcile failed:', e)
    }
  }, [serverScope])
  // ── [view-as] lifecycle instrumentation — OBSERVATION ONLY (868kaxm20).
  // Logs the state delta at every enter / cancel / exit transition so a
  // strand (a transition that flips role+scope but never restores) is
  // greppable in both the browser console and Vercel runtime logs. This
  // does NOT change behavior — the fix is a follow-up off these logs.
  // `before` is the live closure snapshot at the moment the handler fires
  // (setters are async, so these still hold pre-transition values);
  // `after` is what the handler is about to apply. Remove once fixed.
  const logViewAs = (event, after = {}) => {
    try {
      console.log(`[view-as] ${event}`, {
        before: {
          role,
          franchiseRole,
          viewAsUser: viewAsUser ? { id: viewAsUser.id, name: viewAsUser.name, role: viewAsUser.role } : null,
          viewAsTarget,
          locFilter,
        },
        after,
      })
    } catch {}
  }
  // ── [view-as] cancel-revert (fix for the 868kaxm20 strand).
  // Sidebar & mobile "View as user…" pre-flip role→'franchise' when the picker
  // OPENS (before a user is chosen); location-card entries pre-flip nothing.
  // Every entry snapshots the real identity BEFORE pre-flipping, and cancel
  // restores that snapshot — so dismissing the picker can never leave a
  // franchise-with-no-user strand, no matter which entry opened it. Single
  // shared open/cancel path so a future entry can't reintroduce the strand.
  const [viewAsSnapshot, setViewAsSnapshot] = useState(null)
  const snapshotIdentityForViewAs = () => {
    setViewAsSnapshot(captureViewAsSnapshot({ role, franchiseRole, viewAsUser, locFilter }))
  }
  const cancelViewAsPicker = () => {
    const next = revertViewAsCancel(viewAsSnapshot, { role, franchiseRole, viewAsUser, locFilter })
    logViewAs('cancel', {
      source: 'picker',
      restored: !!viewAsSnapshot,
      role: next.role,
      franchiseRole: next.franchiseRole,
      viewAsUser: next.viewAsUser ? { id: next.viewAsUser.id, name: next.viewAsUser.name } : null,
      locFilter: next.locFilter,
      viewAsTarget: null,
    })
    setRole(next.role)
    setFranchiseRole(next.franchiseRole)
    setViewAsUser(next.viewAsUser)
    applyLocScope(next.locFilter)
    setViewAsSnapshot(null)
    setViewAsTarget(null)
  }
  const [showLocPicker, setShowLocPicker]   = useState(false)
  const [showRolePicker, setShowRolePicker] = useState(false)
  const [showGlobalSearch, setShowGlobalSearch] = useState(false)
  // id → name for the REAL locations roster. Declared here, not inline in the
  // GlobalSearch JSX: that subtree renders conditionally, and a hook inside it
  // would run only while the search is open — a hooks-order violation.
  const locationNameById = useMemo(
    () => Object.fromEntries((initialLocations || []).map(l => [l.id, l.name])),
    [initialLocations]
  )
  const [globalSelectedPerson, setGlobalSelectedPerson]   = useState(() => {
    if (!initialSelectedLeadId || !Array.isArray(initialPeople)) return null
    return initialPeople.find(p => p.id === initialSelectedLeadId) || null
  })
  // /clients/<id>?e=<engagementId> deep-link: the engagement to open on mount.
  // Already validated SERVER-side (HubPage: belongs to the location-scoped
  // client) so it's a bare id here. Flows down to HiveScreen alongside the
  // selected person and stays in sync with browser back/forward via popstate.
  const [globalSelectedEngagementId, setGlobalSelectedEngagementId] = useState(initialSelectedEngagementId || null)
  const [globalSelectedPartner, setGlobalSelectedPartner] = useState(null)
  // Home "Needs attention" deep-link intent — a one-shot { tab, view?, group?,
  // section? } the Dashboard hands up (onOpenHive) to land the Clients shell on
  // the right tab + filtered/expanded target. Cleared when HiveShell consumes
  // it (onHiveIntentConsumed). Ephemeral triage jump — deliberately NOT
  // URL-persisted (same as the board's listInitialView one-shot); a refresh
  // returns to the remembered lens, which is the right default.
  const [hiveIntent, setHiveIntent] = useState(null)
const [people, setPeople]                 = useState(Array.isArray(initialPeople) ? initialPeople : ALL_PEOPLE)
 // Extend with randomized mock data post-mount. Module-level Math.random
  // would diverge between SSR and client → hydration mismatch.
  // Skipped when initialPeople has real Supabase data — mocks are mock-only.
  useEffect(() => {
if (Array.isArray(initialPeople)) return
    setPeople(prev => [...prev, ...generateExtraPeople()])
  }, [])
  // Sync prop → state after router.refresh() (e.g. post-import) so new leads appear without a reload.
  useEffect(() => {
    if (Array.isArray(initialPeople)) setPeople(initialPeople)
  }, [initialPeople])

  // Supabase Realtime: push lead changes that land with no client event — a
  // Jobber webhook, MAKE, website intake, another user — into the Hive without
  // a refresh. This `people` state is the single seam every lens derives from
  // (HiveScreen, the Inbox via HiveShell's patchedPeople, Reports), so an
  // INSERT landing here surfaces as a new Inbox row that buckets through the
  // same deriveClientStatus as every other row — no special-casing.
  //
  // The event is a SIGNAL: its payload is the flat leads row, so INSERT/UPDATE
  // refetch the full person (with all relations) via GET /api/leads/:id.
  // Dedupe is by id — a lead already present (created locally this session, or
  // a duplicate event) is REPLACED, never appended twice.
  const handleLeadsRealtime = React.useCallback(async ({ type, leadId }) => {
    if (type === 'DELETE') {
      setPeople(prev => removeRealtimePerson(prev, leadId))
      return
    }
    try {
      const res = await fetch(`/api/leads/${leadId}`, { credentials: 'include' })
      if (!res.ok) return
      const { person } = await res.json()
      if (!person) return
      const pulseMs = Date.now()
      setPeople(prev => upsertRealtimePerson(prev, person, pulseMs))
    } catch (e) {
      console.error('[realtime] lead refetch failed:', e)
    }
  }, [])

  // Subscribe on the board's own location vocabulary, NOT a resolved
  // currentLocation: the hook filters for a real locFilter and subscribes
  // unfiltered for 'all' (RLS scopes delivery). The old
  // currentLocation?.id || currentUser?.locationId resolution pinned an 'all'
  // view to one arbitrary location — or, for an admin with no location at all,
  // to nothing — which is why new leads never landed live for admins.
  useLeadsRealtime(locFilter, handleLeadsRealtime)

  // Recycle Bin — is_junk=true leads loaded server-side. Kept in its own
  // state so the main `people` array stays bin-free for HiveScreen / Reports.
  const [binPeople, setBinPeople] = useState(Array.isArray(initialBinPeople) ? initialBinPeople : [])
  useEffect(() => {
    if (Array.isArray(initialBinPeople)) setBinPeople(initialBinPeople)
  }, [initialBinPeople])
  // loc_other unrouted leads (Fix 2 Phase 2). Kept OUT of `people` on purpose:
  // every people consumer filters by the selected location, which is exactly
  // what used to make this queue vanish. Held separately so the two surfaces
  // that need it (Home's transfer card, the Inbox's "Needs transfer" section)
  // can render it in EVERY scope while nothing else changes.
  const [transferPeople, setTransferPeople] = useState(Array.isArray(initialTransferPeople) ? initialTransferPeople : [])
  useEffect(() => {
    if (Array.isArray(initialTransferPeople)) setTransferPeople(initialTransferPeople)
  }, [initialTransferPeople])
  // Follow-up reminders are client-side ephemeral state (added via the
  // "+ Reminder" button; not yet persisted server-side). Previously seeded
  // with a mock loc_kc array, which surfaced fake clients (Lisa Patel, etc.)
  // in the home-tab Needs Attention widget for any view without a real
  // effectiveLocId — same bug class as the D_UPCOMING leak fixed in 176c909.
  // Start empty so a fresh/cleared DB shows the real empty state.
  const [followUps, setFollowUps]           = useState([])
  const [partners, setPartners]             = useState(Array.isArray(initialPartners) ? initialPartners : [])
  const [companies, setCompanies]           = useState(Array.isArray(initialCompanies) ? initialCompanies : [])
  const [users, setUsers]                   = useState(initialUsers ?? USERS_DATA)
  // ── prop→state sync after router.refresh() (Fix 2, Phase 1) ────────────────
  // `people` and `binPeople` already did this; these four did not, because
  // before Phase 1 nothing re-fetched them with a DIFFERENT scope — the server
  // always shipped the whole tenant, so the mount-time snapshot stayed right
  // forever. A scope switch changes that: the RSC re-runs with a new location
  // and hands down new props, and without these the Contacts tab, the admin
  // user list and the seat counts would keep rendering the PREVIOUS location's
  // rows with no visible cue.
  //
  // Same guarded shape as the people/binPeople effects: only adopt a real
  // array, so a demo/mock mount (initial* undefined → USERS_DATA etc.) is never
  // clobbered with an empty list.
  useEffect(() => {
    if (Array.isArray(initialPartners)) setPartners(initialPartners)
  }, [initialPartners])
  useEffect(() => {
    if (Array.isArray(initialCompanies)) setCompanies(initialCompanies)
  }, [initialCompanies])
  useEffect(() => {
    if (Array.isArray(initialUsers)) setUsers(initialUsers)
  }, [initialUsers])
  // Track CRM status overrides from admin panel
  const [locStatuses, setLocStatuses]       = useState({})
  // Mobile nav (hamburger drawer + profile menu). isMobile drives the
  // responsive TOTAL_TOP offset. Hydration-safe: windowWidth=0 on SSR and
  // first client render makes isMobile=false on both, matching the server
  // output exactly. Post-hydration useEffect measures the real viewport and
  // re-renders. Without this gate, a flipped isMobile during hydration
  // triggers React errors 425/418/423 and strips mobile-conditional
  // subtrees (including MobileTopBar, MobileNavDrawer, MobileProfileMenu)
  // from the DOM entirely.
  const [windowWidth, setWindowWidth]       = useState(0)
  const [showMobileNav, setShowMobileNav]   = useState(false)
  const [showMobileProfile, setShowMobileProfile] = useState(false)
  useEffect(() => {
    function check() { setWindowWidth(window.innerWidth) }
    check()
    window.addEventListener('resize', check)
    return () => window.removeEventListener('resize', check)
  }, [])
  const isMobile = windowWidth > 0 && windowWidth < 768
  // Lock body scroll behind the drawer so the page underneath doesn't slide too.
  useEffect(() => {
    if (!showMobileNav) return
    const prev = document.body.style.overflow
    document.body.style.overflow = 'hidden'
    return () => { document.body.style.overflow = prev }
  }, [showMobileNav])

  const roleConf    = ROLES.find(r=>r.key===role)
  // Shared with the view-as mapping (lib/view-as-identity) so the role a
  // picked identity lands on and the role that unlocks the corporate transfer
  // queue are read from ONE definition, not two that can drift apart.
  const isElevated  = isElevatedRole(role)
  const selectedLoc = locFilter==='all' ? null : (initialLocations || ALL_LOCATIONS).find(l=>l.id===locFilter)

  // ─── CRM persistence (partners + companies) ─────────────────────────────────
  // State lives in the useState above; these helpers wrap setPartners/setCompanies
  // with API calls so writes reach Supabase. Creates are server-first (we need the
  // real uuid for referral linkage). Partner UPDATES go through lib/partner-writes
  // (makeUpdatePartner): optimistic apply → field-level PATCH of the diff only →
  // on failure REVERT + toast, so a failed save never sits on screen looking
  // saved. Deletes/restores stay optimistic + fire the API.
  const crmLocationId = (obj) => {
    if (isUuidStr(obj?.locationId)) return obj.locationId
    if (isUuidStr(currentLocation?.id)) return currentLocation.id
    if (isUuidStr(locFilter)) return locFilter
    if (isUuidStr(currentUser?.locationId)) return currentUser.locationId
    return obj?.locationId || currentLocation?.id || (locFilter !== 'all' ? locFilter : null) || currentUser?.locationId || null
  }
  async function addPartner(obj) {
    const location_id = crmLocationId(obj)
    try {
      const res = await fetch('/api/partners', { method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify({ ...obj, location_id }) })
      const json = await res.json().catch(() => ({}))
      if (res.ok && json?.id) { setPartners(prev => [json, ...prev]); return json }
      console.error('[partners] create failed:', json?.error || res.status)
    } catch (e) { console.error('[partners] create error:', e) }
    const local = { ...obj, locationId: location_id || obj?.locationId }
    setPartners(prev => [local, ...prev]); return local
  }
  // State-only merge for a partner row persisted OUTSIDE this context —
  // the onPartnerCreated seam (beta ReferrerPicker's inline create, which
  // can't call addPartner under §8.5). The row is the CONFIRMED POST
  // response, never an optimistic stub; dedup + prepend via mergePartnerRow.
  function mergePartner(row) {
    setPartners(prev => mergePartnerRow(prev, row))
  }
  // Live ref so the diff baseline is read at CALL time, not the render that
  // built the closure — two quick edits in a row diff against each other,
  // not both against the same stale snapshot.
  const partnersLiveRef = useRef(partners)
  partnersLiveRef.current = partners
  const updatePartner = makeUpdatePartner({
    getPartners: () => partnersLiveRef.current,
    applyRow: (row) => setPartners(prev => prev.map(p => p.id === row.id ? row : p)),
    setToast,
  })
  function deletePartner(id) {
    setPartners(prev => prev.map(p => p.id === id ? { ...p, isDeleted:true, deletedAt:new Date().toISOString() } : p))
    if (isUuidStr(id)) fetch(`/api/partners/${id}`, { method:'DELETE' }).catch(e => console.error('[partners] delete error:', e))
  }
  function restorePartner(id) {
    setPartners(prev => prev.map(p => p.id === id ? { ...p, isDeleted:false, deletedAt:null } : p))
    if (isUuidStr(id)) fetch(`/api/partners/${id}`, { method:'PATCH', headers:{'Content-Type':'application/json'}, body: JSON.stringify({ restore:true }) }).catch(e => console.error('[partners] restore error:', e))
  }
  function purgePartner(id) {
    setPartners(prev => prev.filter(p => p.id !== id))
    if (isUuidStr(id)) fetch(`/api/partners/${id}?purge=1`, { method:'DELETE' }).catch(e => console.error('[partners] purge error:', e))
  }
  async function addCompany(obj) {
    const location_id = crmLocationId(obj)
    try {
      const res = await fetch('/api/companies', { method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify({ ...obj, location_id }) })
      const json = await res.json().catch(() => ({}))
      if (res.ok && json?.id) { setCompanies(prev => [json, ...prev]); return json }
      console.error('[companies] create failed:', json?.error || res.status)
    } catch (e) { console.error('[companies] create error:', e) }
    const local = { ...obj, locationId: location_id || obj?.locationId }
    setCompanies(prev => [local, ...prev]); return local
  }
  function updateCompany(updated) {
    // SOURCE OF TRUTH (Phase 3): partners.company_id is the link;
    // partners.company (the string) is a DISPLAY CACHE. A rename must
    // refresh the cache on every linked person or the two drift — each
    // refresh rides updatePartner (diff PATCH), so only the one changed
    // field travels per row.
    const prevName = companies.find(c => c.id === updated.id)?.name
    setCompanies(prev => prev.map(c => c.id === updated.id ? updated : c))
    if (isUuidStr(updated?.id)) {
      fetch(`/api/companies/${updated.id}`, { method:'PATCH', headers:{'Content-Type':'application/json'}, body: JSON.stringify(updated) })
        .then(r => { if (!r.ok) console.error('[companies] update failed:', r.status) })
        .catch(e => console.error('[companies] update error:', e))
    }
    if (prevName && updated?.name && prevName !== updated.name) {
      for (const p of partnersLiveRef.current.filter(p => p.companyId === updated.id)) {
        updatePartner({ ...p, company: updated.name })
      }
    }
  }
  // DELETE /api/companies/:id soft-deletes server-side (sets deleted_at).
  // Non-optimistic on purpose: the API call must succeed before we mutate
  // local state, so a failure can be surfaced inline without the row already
  // having vanished from the list. On success we drop the company and unlink
  // any partners/contacts that pointed at it (the confirmation copy promises
  // this). UUID guard skips local-only (un-persisted) rows. Throws on failure.
  async function deleteCompany(id) {
    if (isUuidStr(id)) {
      const r = await fetch(`/api/companies/${id}`, { method:'DELETE' })
      if (!r.ok) { console.error('[companies] delete failed:', r.status); throw new Error('delete_failed') }
    }
    setCompanies(prev => prev.filter(c => c.id !== id))
    setPartners(prev => prev.map(p => p.companyId === id ? { ...p, companyId:null, company:'' } : p))
  }
  const partnersCtxValue = { partners, addPartner, mergePartner, updatePartner, deletePartner, restorePartner, purgePartner }
  const companiesCtxValue = { companies, addCompany, updateCompany, deleteCompany }

  // For franchise users, use their location's status
  const franchiseLoc = !isElevated && viewAsUser?.locationId
    ? (initialLocations || ALL_LOCATIONS).find(l=>l.id===viewAsUser.locationId)
    : selectedLoc

  // Real franchise user: lifecycle_status is the source of truth for
  // onboarding vs active routing. subscription_status is a billing concern
  // and only overrides AFTER launch (lifecycle_status='active') to surface
  // past_due / inactive UI states. super_admin / corporate sign in with
  // currentSubscription=null and fall through to the view-as path below.
  //
  // 'deferred' must NOT route to 'onboarding' — corp-sponsored locations
  // (payment_source='corporate_sponsored') stay subscription_status='deferred'
  // through the sponsorship window (currently March 2027). Pre-fix, a
  // launched corp-sponsored location would be stuck in onboarding mode
  // forever because the OR-clause treated 'deferred' as an onboarding signal.
  const effectiveCrmStatus = (() => {
    if (!isElevated && currentSubscription) {
      if (currentLocation?.lifecycle_status === 'onboarding') return 'onboarding'
      const s = currentSubscription.subscription_status
      if (s === 'past_due') return 'pastdue'
      if (s === 'inactive') return 'inactive'
      return 'active'
    }
    if (franchiseLoc) return locStatuses[franchiseLoc.id] || franchiseLoc.crmStatus
    return 'active'
  })()

  // Read-only mode for the beta Hive surface (868kawwmh). Single policy
  // point in betaGate.js: read-only for lite_user (viewer/light/readonly)
  // and paused/inactive locations; past_due keeps FULL access during its
  // grace window; elevated roles always write. Threaded into HiveScreen →
  // HiveShell; the server (lib/read-only-access) enforces independently.
  const betaReadOnly = resolveBetaReadOnly({ role, franchiseRole, crmStatus: effectiveCrmStatus })

  function nav(key) {
    setActiveNav(key)
    window.scrollTo(0,0)
    // Leaving the Clients tab — drop the open lead (and any open engagement)
    // so a later nav('hive') opens to the list, not back into a stale panel.
    if (key !== 'hive') { setGlobalSelectedPerson(null); setGlobalSelectedEngagementId(null) }
    // Sync URL with the tab the user picked. Use window.history.pushState
    // (not Next.js router.push) so BeeHub stays mounted — a real route
    // navigation would unmount and reset all in-app state (filters,
    // scroll position, edit drafts). Refreshing still works because
    // each route's page.tsx → HubPage SSR matches the URL.
    const url = NAV_TO_URL[key]
    if (!url || typeof window === 'undefined') return
    const current = window.location.pathname
    // For the Clients tab, /clients and /clients/[id] are both "on Clients" —
    // don't disturb an open detail panel just because the user re-clicked the tab.
    const alreadyOn = key === 'hive' ? current.startsWith('/clients') : current === url
    if (!alreadyOn) window.history.pushState({}, '', url)
  }
  // Toast for /clients/[bad-uuid] → /clients?notfound=1 redirect.
  useEffect(() => {
    if (notFoundToast) setToast({ kind: 'error', msg: 'Client not found' })
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])
  // Browser back/forward — re-derive activeNav + open client from the URL.
  // Click-driven URL updates go through pushState (above) and lead-panel
  // open/close (HiveScreen below); popstate handles the user-driven case.
  // globalSelectedPerson flows down as HiveScreen's `selected` → its
  // urlClientId/urlEngagementId → HiveShell's overlay (nextRecordOverlay),
  // so back/forward now OPENS and CLOSES the beta overlay too — not just
  // the classic PersonPanel. Fall back to a minimal {id} when the client
  // isn't in local `people` (forward-nav to a not-yet-loaded record): the
  // overlay loads it server-side, so the URL still opens the right panel.
  useEffect(() => {
    function onPop() {
      const { nav: navKey, leadId, engagementId } = parseHubUrl(window.location.pathname, window.location.search)
      setActiveNav(navKey)
      if (leadId) {
        const lead = people.find(p => p.id === leadId)
        setGlobalSelectedPerson(lead || { id: leadId })
        // ?e= only resolves under a /clients/<id> path (parseHubUrl drops it
        // otherwise). No server round-trip on back/forward: a stale/foreign id
        // is 403'd by the panel's own location-scoped fetch, never leaking.
        setGlobalSelectedEngagementId(engagementId || null)
      } else if (navKey === 'hive') {
        setGlobalSelectedPerson(null)
        setGlobalSelectedEngagementId(null)
      }
    }
    window.addEventListener('popstate', onPop)
    return () => window.removeEventListener('popstate', onPop)
  }, [people])
  function addPersonFromPartner(p) {
    setPeople(prev=>[{...p,id:`n${Date.now()}`,stage:'New',tags:['returning'],buzzNotes:[{id:`bn${Date.now()}`,text:'Was a partner',ts:'Just now',user:'System'}],jobNotes:[],invoices:[],jobs:[],finalProcessed:false,isJunk:false,activity:[],outreachTimeline:[]},...prev])
  }
  function updateLocStatus(id, status) {
    setLocStatuses(prev=>({...prev,[id]:status}))
  }

  // ── Nav ────────────────────────────────────────────────────────────────────
  // `action:'openManual'` is a soft route — sidebar/bottom-nav buttons call
  // setShowManual(true) instead of nav(key). No activeNav highlight either.
  const navItems = [
    { key:'home',     icon:'🏠', label:'Home'    },
    { key:'hive',     icon:'🐝', label:'Clients'    },
    { key:'partners', icon:'👥', label:'Network'},
    { key:'reports',  icon:'📊', label:'Reports' },
    // issue 140: Back Office sits alongside Reports/Settings and is shown to
    // EVERY role on purpose (build anticipation, don't hide). The render split
    // lives in screen(): super_admin gets the real BackOfficeScreen build-out
    // surface, everyone else gets the shared ComingSoonPlaceholder.
    { key:'backoffice', icon:'🗂️', label:'Back Office' },
    { key:'settings', icon:'⚙️', label:'Settings'},
    // 'Manual' moved out of the nav — the Guide and the Manual both open
    // from the Ask Bee Hub panel footer (issue 132).
    ...(isElevated ? [{ key:'admin', icon:'🏢', label:role==='super_admin'?'Admin':'Corp' }] : []),
    // Franchise owner + manager get their own read-only history of what they
    // have reported (OwnerFeedbackScreen, server-scoped to their location_id).
    // Elevated users reach the triage console via the Admin screen's Feedback
    // tab instead. The label is the issue 235 point: nothing in the product was
    // named for "what happened to the things I reported", so the one nav item
    // that could have said it said "Feedback" and opened a triage queue.
    ...(role==='franchise' && ['owner','manager'].includes(franchiseRole)
      ? [{ key:'feedback', icon:'💬', label:"What you've told us" }]
      : []),
  ]

  // Heights — the old top demo/super-admin strip is GONE (its identity,
  // View-as, and badge moved into the sidebar-bottom IdentityScopeControl);
  // the 32px it held is reclaimed by the content below.
  // Location banner is MOBILE-ONLY since the picker moved to the sidebar
  // footer on desktop (sidebar doesn't exist on mobile, so the banner stays
  // there). Every TOTAL_TOP-derived offset collapses automatically on desktop.
  const LOC_BAR_H   = (isElevated && isMobile) ? 36 : 0
  // MobileTopBar (hamburger + profile) only shows on mobile and pushes everything
  // below it down by 48px. TOTAL_TOP threads through every sticky/padding calc.
  const MOBILE_NAV_H = isMobile ? 48 : 0
  const TOTAL_TOP   = LOC_BAR_H + MOBILE_NAV_H

  // ── Location banner (MOBILE-ONLY) ──────────────────────────────────────────
  // Desktop elevated users pick locations from the sidebar footer control;
  // mobile keeps this banner (no sidebar exists below 768px).
  const LocBanner = () => {
    if (!isElevated || !isMobile) return null
    const sc = selectedLoc ? (CRM_STATUS_CONF[locStatuses[selectedLoc.id]||selectedLoc.crmStatus]) : null
    return (
      <div className="bee-loc-banner" style={{ position:'fixed', top:0, left:0, right:0, height:'36px', background:'#0f1f1c', borderBottom:'1px solid rgba(168,201,196,0.12)', zIndex:10000, display:'flex', alignItems:'center', padding:'0 12px', gap:'8px' }}>
        <span style={{ fontSize:'11px', color:'rgba(168,201,196,0.5)' }}>📍</span>
        <button onClick={()=>setShowLocPicker(!showLocPicker)} style={{ flex:1, display:'flex', alignItems:'center', gap:'6px', background:'none', border:'none', cursor:'pointer', fontFamily:'inherit', textAlign:'left', padding:0 }}>
          <span style={{ fontSize:'12px', fontWeight:600, color:selectedLoc?'white':'rgba(168,201,196,0.8)' }}>
            {selectedLoc ? `${selectedLoc.name}, ${selectedLoc.state}` : 'All Locations'}
          </span>
          {selectedLoc&&sc&&<span style={{ fontSize:'10px', padding:'1px 6px', borderRadius:'10px', background:sc.bg, color:sc.color, fontWeight:600 }}>{sc.icon}</span>}
          <span style={{ fontSize:'10px', color:'rgba(168,201,196,0.4)' }}>▼</span>
        </button>
        {locFilter!=='all'&&(
          <button onClick={()=>applyLocScope('all')} style={{ fontSize:'10px', color:'rgba(168,201,196,0.6)', background:'rgba(168,201,196,0.08)', border:'none', borderRadius:'6px', padding:'2px 7px', cursor:'pointer', fontFamily:'inherit', flexShrink:0 }}>All ×</button>
        )}
      </div>
    )
  }

  // ── Mobile top bar (hamburger + brand + profile) ───────────────────────────
  // Renders only below 768px (via .bee-mobile-topbar CSS class). Sits directly
  // below the LocBanner. Provides the entry points to the hamburger drawer
  // (left) and the profile menu (right).
  const MobileTopBar = () => {
    const tbTop = LOC_BAR_H
    const profileName = viewAsUser?.name || currentUser?.name || 'Kevin Shaw'
    const profileInitials = viewAsUser?.initials || (profileName ? getInitials(profileName) : 'KS')
    const screenTitle = (() => {
      if (activeNav === 'home') return 'Home'
      if (activeNav === 'hive') return 'Clients'
      if (activeNav === 'partners') return 'Network'
      if (activeNav === 'reports') return 'Reports'
      if (activeNav === 'backoffice') return 'Back Office' // issue 140
      if (activeNav === 'settings') return 'Settings'
      if (activeNav === 'admin') return role === 'super_admin' ? 'Admin' : 'Corp'
      return 'Bee Hub'
    })()
    return (
      <div className="bee-mobile-topbar" style={{ position:'fixed', top:`${tbTop}px`, left:0, right:0, height:'48px', background:'#1a2e2b', borderBottom:'1px solid rgba(168,201,196,0.12)', zIndex:9000, alignItems:'center', padding:'0 4px', gap:'4px' }}>
        <button
          onClick={()=>setShowMobileNav(true)}
          aria-label="Open menu"
          style={{ width:'44px', height:'44px', display:'flex', alignItems:'center', justifyContent:'center', background:'none', border:'none', cursor:'pointer', flexShrink:0 }}>
          <span style={{ display:'inline-flex', flexDirection:'column', gap:'4px' }}>
            <span style={{ width:'20px', height:'2px', background:'rgba(168,201,196,0.95)', borderRadius:'1px', display:'block' }} />
            <span style={{ width:'20px', height:'2px', background:'rgba(168,201,196,0.95)', borderRadius:'1px', display:'block' }} />
            <span style={{ width:'20px', height:'2px', background:'rgba(168,201,196,0.95)', borderRadius:'1px', display:'block' }} />
          </span>
        </button>
        <div style={{ flex:1, display:'flex', alignItems:'center', gap:'8px', minWidth:0 }}>
          <span style={{ fontSize:'18px', lineHeight:1, flexShrink:0 }}>🐝</span>
          <span style={{ fontSize:'15px', fontWeight:600, color:'white', fontFamily:'Georgia,serif', overflow:'hidden', textOverflow:'ellipsis', whiteSpace:'nowrap' }}>{screenTitle}</span>
        </div>
        <button
          onClick={()=>setShowGlobalSearch(true)}
          aria-label="Search"
          style={{ width:'44px', height:'44px', display:'flex', alignItems:'center', justifyContent:'center', background:'none', border:'none', cursor:'pointer', flexShrink:0, color:'rgba(168,201,196,0.85)', fontSize:'18px' }}>
          🔍
        </button>
        <AskBeeHubButton onOpen={()=>{ dismissGuideHint(); setShowHelpChat(true) }} compact />
        <button
          onClick={()=>setShowMobileProfile(v=>!v)}
          aria-label="Profile menu"
          style={{ width:'44px', height:'44px', display:'flex', alignItems:'center', justifyContent:'center', background:'none', border:'none', cursor:'pointer', flexShrink:0, padding:0 }}>
          <span style={{ width:'32px', height:'32px', borderRadius:'50%', background:'linear-gradient(135deg,#d4a046,#b07a20)', display:'flex', alignItems:'center', justifyContent:'center', fontSize:'11px', fontWeight:700, color:'white' }}>
            {profileInitials}
          </span>
        </button>
      </div>
    )
  }

  // ── Hamburger drawer (mobile only) ─────────────────────────────────────────
  // Slide-in from left, ~280px wide, full-height. Backdrop tap closes.
  // Reuses the same navItems gating logic as the desktop sidebar.
  const MobileNavDrawer = () => {
    if (!showMobileNav) return null
    const isOnboardingState = effectiveCrmStatus === 'onboarding'
    const sidebarName = viewAsUser?.name || currentUser?.name || 'Kevin Shaw'
    const sidebarInitials = viewAsUser?.initials || (sidebarName ? getInitials(sidebarName) : 'KS')
    const sidebarRoleLabel = viewAsUser
      ? (FRANCHISE_ROLES.find(r => r.key === viewAsUser.role)?.label || 'Corporate')
      : role === 'super_admin' ? 'Super Admin'
      : role === 'corporate'   ? 'Corporate'
      : role === 'franchise' && franchiseRole === 'owner'   ? 'Zee Bee'
      : role === 'franchise' && franchiseRole === 'manager' ? 'Hive Manager'
      : role === 'franchise' && franchiseRole === 'viewer'  ? 'Honey Watcher'
      : ''
    return (
      <div style={{ position:'fixed', inset:0, zIndex:10003, display:'flex' }}>
        <div onClick={()=>setShowMobileNav(false)} style={{ position:'absolute', inset:0, background:'rgba(0,0,0,0.45)' }} />
        <div style={{ position:'relative', width:'280px', maxWidth:'85vw', background:'#1a2e2b', height:'100%', display:'flex', flexDirection:'column', boxShadow:'4px 0 24px rgba(0,0,0,0.3)', overflowY:'auto', borderRight:'1px solid rgba(168,201,196,0.1)' }}>
          {/* Header */}
          <div style={{ padding:'18px 18px 14px', borderBottom:'1px solid rgba(168,201,196,0.08)', display:'flex', alignItems:'center', justifyContent:'space-between', gap:'10px' }}>
            <div style={{ display:'flex', alignItems:'center', gap:'10px' }}>
              <span style={{ fontSize:'22px' }}>🐝</span>
              <div>
                <p style={{ fontSize:'14px', fontWeight:700, color:'white', fontFamily:'Georgia,serif', lineHeight:1 }}>Bee Hub</p>
                <p style={{ fontSize:'10px', color:'rgba(168,201,196,0.5)', marginTop:'2px' }}>Bee Organized</p>
              </div>
            </div>
            <button onClick={()=>setShowMobileNav(false)} aria-label="Close menu" style={{ width:'44px', height:'44px', background:'none', border:'none', color:'rgba(168,201,196,0.85)', fontSize:'22px', cursor:'pointer', display:'flex', alignItems:'center', justifyContent:'center' }}>×</button>
          </div>
          {/* Nav items */}
          <div style={{ flex:1, padding:'10px 10px 16px', display:'flex', flexDirection:'column', gap:'4px' }}>
            {navItems.map(item=>{
              // issue 139: Reports has NO role lock — every role that sees the
              // tab gets the identical Coming Soon screen (one behavior, no
              // branch). Settings nav is likewise open to EVERY role —
              // SettingsScreen itself allowlists the sections (owner:
              // everything; manager and lite_user: Profile only, a self-edit).
              // Don't reintroduce a nav-level role denylist for either.
              // issue 140: Back Office is exempt from the onboarding lock too —
              // it's meant to build anticipation, so it stays clickable (never
              // dimmed) for every role, even mid-setup.
              const isLocked = (isOnboardingState && !isElevated && !['home','backoffice'].includes(item.key))
              const isActive = activeNav===item.key
              return (
                <button
                  key={item.key}
                  onClick={()=>{
                    if (isLocked) return
                    if (item.action==='openManual') { setShowManual(true); setShowMobileNav(false); return }
                    nav(item.key)
                    setShowMobileNav(false)
                  }}
                  style={{ width:'100%', minHeight:'48px', padding:'10px 14px', borderRadius:'10px', border:'none', cursor:isLocked?'default':'pointer', fontFamily:'inherit', display:'flex', alignItems:'center', gap:'14px', textAlign:'left', background:isActive?'rgba(168,201,196,0.14)':'transparent', opacity:isLocked?0.3:1 }}>
                  <span style={{ fontSize:'20px', lineHeight:1, flexShrink:0 }}>{item.icon}</span>
                  <span style={{ fontSize:'14px', fontWeight:isActive?600:500, color:isActive?'#a8c9c4':'rgba(168,201,196,0.75)' }}>{item.label}</span>
                  {isActive&&<div style={{ marginLeft:'auto', width:'5px', height:'5px', borderRadius:'50%', background:'#a8c9c4' }} />}
                </button>
              )
            })}
          </div>
          {/* User card */}
          <div style={{ padding:'14px 16px', borderTop:'1px solid rgba(168,201,196,0.08)' }}>
            <div style={{ display:'flex', alignItems:'center', gap:'10px' }}>
              <div style={{ width:'36px', height:'36px', borderRadius:'50%', background:'linear-gradient(135deg,#d4a046,#b07a20)', display:'flex', alignItems:'center', justifyContent:'center', fontSize:'12px', fontWeight:700, color:'white', flexShrink:0 }}>
                {sidebarInitials}
              </div>
              <div style={{ minWidth:0, flex:1 }}>
                <p style={{ fontSize:'13px', fontWeight:600, color:'white', overflow:'hidden', textOverflow:'ellipsis', whiteSpace:'nowrap' }}>{sidebarName}</p>
                {sidebarRoleLabel && (
                  <p style={{ fontSize:'11px', color:'rgba(168,201,196,0.55)', overflow:'hidden', textOverflow:'ellipsis', whiteSpace:'nowrap' }}>{sidebarRoleLabel}</p>
                )}
              </div>
            </div>
            <a href="/api/auth/signout"
              style={{ display:'block', marginTop:'12px', minHeight:'44px', padding:'11px 12px', background:'rgba(168,201,196,0.1)', border:'1px solid rgba(168,201,196,0.18)', borderRadius:'10px', textAlign:'center', fontSize:'13px', fontWeight:600, color:'rgba(168,201,196,0.9)', textDecoration:'none', fontFamily:'inherit' }}>
              Sign Out
            </a>
          </div>
        </div>
      </div>
    )
  }

  // ── Mobile profile menu (top-right popover) ────────────────────────────────
  const MobileProfileMenu = () => {
    if (!showMobileProfile) return null
    const profileName = viewAsUser?.name || currentUser?.name || 'Kevin Shaw'
    const profileEmail = viewAsUser?.email || currentUser?.email || ''
    const profileRole = viewAsUser
      ? (FRANCHISE_ROLES.find(r => r.key === viewAsUser.role)?.label || 'Corporate')
      : role === 'super_admin' ? 'Super Admin'
      : role === 'corporate'   ? 'Corporate'
      : role === 'franchise' && franchiseRole === 'owner'   ? 'Zee Bee'
      : role === 'franchise' && franchiseRole === 'manager' ? 'Hive Manager'
      : role === 'franchise' && franchiseRole === 'viewer'  ? 'Honey Watcher'
      : ''
    const menuTop = LOC_BAR_H + 48 + 4
    return (
      <>
        <div onClick={()=>setShowMobileProfile(false)} style={{ position:'fixed', inset:0, zIndex:9001, background:'transparent' }} />
        <div style={{ position:'fixed', top:`${menuTop}px`, right:'8px', zIndex:9002, width:'240px', background:'white', borderRadius:'12px', boxShadow:'0 10px 30px rgba(0,0,0,0.2)', border:'1px solid rgba(0,0,0,0.08)', overflow:'hidden' }}>
          <div style={{ padding:'14px 14px', borderBottom:'1px solid rgba(0,0,0,0.06)' }}>
            <p style={{ fontSize:'13px', fontWeight:600, color:'#1a2e2b', overflow:'hidden', textOverflow:'ellipsis', whiteSpace:'nowrap' }}>{profileName}</p>
            {profileEmail && <p style={{ fontSize:'11px', color:'#8a9e9a', marginTop:'2px', overflow:'hidden', textOverflow:'ellipsis', whiteSpace:'nowrap' }}>{profileEmail}</p>}
            {profileRole && <p style={{ fontSize:'10px', color:'#a8c9c4', marginTop:'4px', fontWeight:600, textTransform:'uppercase', letterSpacing:'0.4px' }}>{profileRole}</p>}
          </div>
          {role === 'super_admin' && !viewAsUser && (
            <button onClick={()=>{ logViewAs('enter:open-picker', { source:'mobile', roleFlip:'super_admin→franchise', viewAsTarget:true }); setShowMobileProfile(false); snapshotIdentityForViewAs(); setRole('franchise'); setViewAsTarget(true) }}
              style={{ width:'100%', minHeight:'44px', padding:'12px 14px', background:'white', border:'none', borderBottom:'1px solid rgba(0,0,0,0.05)', fontSize:'13px', color:'#1a2e2b', fontFamily:'inherit', cursor:'pointer', textAlign:'left' }}>
              👁 View as user…
            </button>
          )}
          {role === 'super_admin' && viewAsUser && (
            <button onClick={()=>{ logViewAs('exit:restore', { source:'mobile', role:'super_admin', viewAsUser:null, locFilter:'all' }); setShowMobileProfile(false); setViewAsUser(null); setRole('super_admin'); applyLocScope('all') }}
              style={{ width:'100%', minHeight:'44px', padding:'12px 14px', background:'white', border:'none', borderBottom:'1px solid rgba(0,0,0,0.05)', fontSize:'13px', color:'#ef4444', fontFamily:'inherit', cursor:'pointer', textAlign:'left' }}>
              Exit view-as
            </button>
          )}
          <a href="/api/auth/signout"
            style={{ display:'flex', alignItems:'center', minHeight:'44px', padding:'12px 14px', fontSize:'13px', color:'#1a2e2b', fontFamily:'inherit', textDecoration:'none' }}>
            Sign Out
          </a>
        </div>
      </>
    )
  }

  // ── Location picker dropdown ────────────────────────────────────────────────
  const LocPickerDropdown = () => {
    const [locSearch, setLocSearch] = React.useState('')
    if (!showLocPicker) return null

    const q = locSearch.toLowerCase()
const allLocs = (initialLocations || ALL_LOCATIONS).filter(l =>
      !q || l.name.toLowerCase().includes(q) || (l.owner||'').toLowerCase().includes(q) || l.state.toLowerCase().includes(q)
    )
    const active     = allLocs.filter(l=>(locStatuses[l.id]||l.crmStatus)==='active')
    const onboarding = allLocs.filter(l=>(locStatuses[l.id]||l.crmStatus)==='onboarding')
    const pastdue    = allLocs.filter(l=>(locStatuses[l.id]||l.crmStatus)==='pastdue')
    const inactive   = allLocs.filter(l=>(locStatuses[l.id]||l.crmStatus)==='inactive')

    const Group = ({label, locs}) => locs.length===0 ? null : (
      <>
        <div style={{ padding:'6px 16px 4px', background:'#f7f5f0', borderBottom:'1px solid rgba(0,0,0,0.05)' }}>
          <p style={{ fontSize:'10px', fontWeight:700, color:'#8a9e9a', textTransform:'uppercase', letterSpacing:'0.4px' }}>{label}</p>
        </div>
        {locs.map((loc,i)=>{
          const st  = locStatuses[loc.id]||loc.crmStatus
          const lsc = CRM_STATUS_CONF[st]
          const sel = locFilter===loc.id
          return (
            <button key={loc.id} onClick={()=>{ applyLocScope(loc.id); setShowLocPicker(false) }} style={{ width:'100%', padding:'10px 16px', background:sel?'rgba(26,46,43,0.05)':'white', border:'none', borderBottom:'1px solid rgba(0,0,0,0.04)', cursor:'pointer', fontFamily:'inherit', display:'flex', alignItems:'center', gap:'10px', textAlign:'left' }}>
              <div style={{ flex:1, minWidth:0 }}>
                <p style={{ fontSize:'13px', fontWeight:sel?700:500, color:'#1a2e2b', marginBottom:'1px' }}>{loc.name}, {loc.state}</p>
                <p style={{ fontSize:'11px', color:'#8a9e9a' }}>{loc.owner||'Unassigned'}</p>
              </div>
              <span style={{ fontSize:'10px', padding:'2px 7px', borderRadius:'20px', background:lsc.bg, color:lsc.color, fontWeight:600, flexShrink:0 }}>{lsc.icon}</span>
              {sel&&<span style={{ fontSize:'13px', color:'#a8c9c4', flexShrink:0 }}>✓</span>}
            </button>
          )
        })}
      </>
    )

    return (
      <>
        <div style={{ position:'fixed', inset:0, zIndex:9998 }} onClick={()=>setShowLocPicker(false)} />
        <div style={{ position:'fixed', ...(isMobile
          ? { top:`${TOTAL_TOP}px`, left:0, right:0, borderBottom:'1px solid rgba(0,0,0,0.1)' }
          // Desktop: the trigger lives in the sidebar footer (lower left),
          // so the sheet anchors there as a popover instead of a top sheet.
          : { bottom:'16px', left:'228px', width:'360px', borderRadius:'14px', border:'1px solid rgba(0,0,0,0.08)' }
        ), background:'white', zIndex:9999, boxShadow:'0 4px 20px rgba(0,0,0,0.12)', maxHeight:'70vh', display:'flex', flexDirection:'column' }}>
          {/* Search */}
          <div style={{ padding:'10px 12px', borderBottom:'1px solid rgba(0,0,0,0.06)', flexShrink:0 }}>
            <input
              autoFocus
              value={locSearch}
              onChange={e=>setLocSearch(e.target.value)}
              placeholder="Search locations…"
              style={{ width:'100%', padding:'8px 12px', border:'1.5px solid rgba(0,0,0,0.1)', borderRadius:'8px', fontSize:'13px', fontFamily:'inherit', color:'#1a2e2b', outline:'none', boxSizing:'border-box' }}
            />
          </div>
          <div style={{ overflowY:'auto', flex:1 }}>
            {/* All locations option */}
            <button onClick={()=>{ applyLocScope('all'); setShowLocPicker(false) }} style={{ width:'100%', padding:'12px 16px', background:locFilter==='all'?'rgba(26,46,43,0.05)':'white', border:'none', borderBottom:'1px solid rgba(0,0,0,0.05)', cursor:'pointer', fontFamily:'inherit', display:'flex', alignItems:'center', gap:'10px', textAlign:'left' }}>
              <span style={{ fontSize:'18px' }}>🌐</span>
              <span style={{ fontSize:'14px', fontWeight:locFilter==='all'?700:500, color:'#1a2e2b', flex:1 }}>All Locations</span>
              {locFilter==='all'&&<span style={{ color:'#a8c9c4' }}>✓</span>}
            </button>
            <Group label="Active" locs={active} />
            <Group label="Past Due" locs={pastdue} />
            <Group label="Onboarding" locs={onboarding} />
            <Group label="Inactive" locs={inactive} />
            {allLocs.length===0&&<p style={{ padding:'1.5rem', textAlign:'center', color:'#b0c0bc', fontSize:'13px' }}>No locations found</p>}
          </div>
        </div>
      </>
    )
  }

  const pageStyle = { paddingTop:`${TOTAL_TOP}px` }

  // ── Screen routing ─────────────────────────────────────────────────────────
  // ⌘K / Ctrl+K to open global search
  React.useEffect(()=>{
    function onKey(e) { if ((e.metaKey||e.ctrlKey) && e.key==='k') { e.preventDefault(); setShowGlobalSearch(true) } }
    window.addEventListener('keydown', onKey)
    return ()=>window.removeEventListener('keydown', onKey)
  }, [])

  const screen = () => {
    // Elevated users (super_admin / corporate) get the unified SuperAdminLayout
    // for the Admin nav destination. /settings continues to show the franchise-style
    // SettingsScreen for all roles so elevated users retain access to Profile /
    // Location / Team / Billing / Communication / Templates / Jobber.
    if (isElevated && activeNav==='admin') return (
      <div style={{ paddingTop:`${TOTAL_TOP}px` }}>
        <SuperAdminLayout
          key="super-admin-layout"
          role={role}
          locFilter={locFilter}
          locStatuses={locStatuses}
          onStatusChange={updateLocStatus}
          onViewLocation={(id)=>{ logViewAs('enter:open-picker', { source:'location-card', locationId:id, roleFlip:'none', viewAsTarget:id }); snapshotIdentityForViewAs(); setViewAsTarget(id) }}
          users={users}
          setUsers={setUsers}
          people={people}
          setPeople={setPeople}
          binPeople={binPeople}
          setBinPeople={setBinPeople}
          partners={partners}
          setPartners={setPartners}
          guideSlides={guideSlides}
          setGuideSlides={setGuideSlides}
          manualSlides={manualSlides}
          setManualSlides={setManualSlides}
          initialLocations={initialLocations}
          isMobile={isMobile}
          topOffset={TOTAL_TOP}
          initialSection={adminDeepLinkSection || 'dashboard'}
          onExitAdmin={()=>nav('hive')}
        />
      </div>
    )
    // Non-elevated users reaching /admin (shouldn't happen, but fallback)
    if (activeNav==='admin') return (
      <div style={pageStyle}>
        <AdminScreen
          role={role}
          locFilter={locFilter}
          locStatuses={locStatuses}
          onStatusChange={updateLocStatus}
          onViewLocation={(id)=>{ logViewAs('enter:open-picker', { source:'location-card-admin', locationId:id, roleFlip:'none', viewAsTarget:id }); snapshotIdentityForViewAs(); setViewAsTarget(id) }}
          users={users}
          setUsers={setUsers}
          people={people}
          setPeople={setPeople}
          binPeople={binPeople}
          setBinPeople={setBinPeople}
          partners={partners}
          setPartners={setPartners}
          guideSlides={guideSlides}
          setGuideSlides={setGuideSlides}
          manualSlides={manualSlides}
          setManualSlides={setManualSlides}
          initialLocations={initialLocations}
        />
      </div>
    )
    if (activeNav==='reports') return <div style={pageStyle}><ReportsScreen /></div>
    // issue 140: deliberate render split. super_admin lands on the real
    // BackOfficeScreen (the build-out surface — a visibly-distinct work-in-
    // progress stub, NOT the placeholder), every other role lands on the shared
    // ComingSoonPlaceholder. Two paths, two different screens — the anti-#136
    // rule: never let both paths render the same thing.
    if (activeNav==='backoffice') return <div style={pageStyle}>{role==='super_admin' ? <BackOfficeScreen /> : <BackOfficeComingSoon />}</div>
    if (activeNav==='settings') return (
      <div style={pageStyle}>
        {/* locationId: was `locFilter==='all' ? 'loc_kc' : locFilter` — a
            hardcoded slug papering over the fact that an elevated user on 'all'
            had no resolved location. Since Phase 3 they land on a real one, so
            the literal is gone; on 'all' this is null and SettingsScreen falls
            through to its own context/selectedLoc resolution rather than
            silently showing Kansas City's team to whoever is looking. */}
        <SettingsScreen onStatusChange={()=>{}} selectedLoc={selectedLoc} locationId={viewAsUser?.locationId || (locFilter==='all' ? null : locFilter)} franchiseRole={franchiseRole} isSuperAdmin={role==='super_admin'&&!viewAsUser} onOpenManual={()=>setShowManual(true)} />
      </div>
    )
    if (activeNav==='hive') return (
      <div style={pageStyle}>
        {/* Sample-now/bulk-later gap state: the Clients surface must explain a
            partial book ("rest arrives tonight"), or it reads as data loss. */}
        <ImportGapBanner locationId={viewAsUser?.locationId || (locFilter==='all' ? null : locFilter)} />
        <HiveScreen onNavigate={nav} people={people} setPeople={setPeople} transferPeople={transferPeople} locationRequired={!!initialAllOverview} onOpenLocationPicker={()=>setShowLocPicker(true)} readOnly={betaReadOnly} locFilter={locFilter} isElevated={isElevated} locations={initialLocations || ALL_LOCATIONS} initialSelected={globalSelectedPerson} initialSelectedEngagementId={globalSelectedEngagementId} onInitialSelectedConsumed={()=>setGlobalSelectedPerson(null)} onSelectedChange={(p)=>setGlobalSelectedPerson(p)} onEngagementChange={(id)=>setGlobalSelectedEngagementId(id)} onAddFollowUp={fu=>setFollowUps(prev=>[...prev,fu])} currentUserId={viewAsUser?.id||'u11'} setToast={setToast} engagements={Array.isArray(initialEngagements)?initialEngagements:[]} newBoardAllowed={canSeeBetaBoard(role)} engagementsClosedCount={Number(initialEngagementsClosedCount)||0} engagementsClosedWonCount={Number(initialEngagementsClosedWonCount)||0} initialHiveIntent={hiveIntent} onHiveIntentConsumed={()=>setHiveIntent(null)} onReportProblem={openRecordReport} />
        {toast && <InlineToast {...toast} />}
      </div>
    )
    if (activeNav==='partners') return (
      <div style={pageStyle}>
        {/* locationRequired mirrors HiveScreen above: server truth
            (!!initialAllOverview), so Network prompts on 'all' exactly when
            the record lenses do — never for a franchise user. */}
        <PartnersScreen onNavigate={nav} partners={partners} setPartners={setPartners} companies={companies} setCompanies={setCompanies} locFilter={locFilter} isElevated={isElevated} people={people} initialSelected={globalSelectedPartner} onInitialSelectedConsumed={()=>setGlobalSelectedPartner(null)} onAddToHive={(partner)=>{ addPersonFromPartner(partner); nav('hive') }} readOnly={role==='franchise' && isReadOnlyFranchiseRole(franchiseRole)} setToast={setToast} locationRequired={!!initialAllOverview} onOpenLocationPicker={()=>setShowLocPicker(true)} networkTruncated={!!initialNetworkTruncated} />
        {toast && <InlineToast {...toast} />}
      </div>
    )
    // Franchise owner/manager: "What you've told us" (issue 235). This used to
    // mount AdminFeedbackScreen — the corp triage console — with one prop
    // flipped, so an owner saw our queue metrics and could mark their own bug
    // Fixed. OwnerFeedbackScreen is read-only and built for the person who
    // filed the report; the triage screen keeps every control this one drops.
    //
    // It reads the same location-scoped /api/admin/feedback list, which the
    // server auto-scopes to the caller's location_id for owner/manager — so
    // this view only ever shows their own location's items. Under view-as the
    // session is still the super_admin (elevated → org-wide), so pass the
    // IMPERSONATED owner's location for parity; the route honors
    // ?location_id= for elevated callers and ignores it for real owners.
    // onReportSomething opens the existing composer on its Submit tab — that
    // entry point, and the record-menu "Report a problem" one, are unchanged.
    if (activeNav==='feedback') return (
      <div style={pageStyle}>
        <OwnerFeedbackScreen
          locationId={viewAsUser?.locationId || null}
          onReportSomething={() => setShowFeedback('submit')}
        />
      </div>
    )
    return (
      <div style={pageStyle}>
        {/* ownerName carries the FULL stored name (full_name || email).
            Onboarding's profile step splits it into First/Last prefill;
            greeting sites apply getFirstName themselves. Do NOT wrap in
            getFirstName here — that blanked invited users' last names
            on the onboarding profile step. */}
        <DashboardScreen
          startNav='home'
          onReportProblem={openRecordReport}
          role={role}
          franchiseRole={role==='franchise'?franchiseRole:'owner'}
          locFilter={locFilter}
          selectedLoc={selectedLoc}
          locationName={selectedLoc?.name || null}
          onClickLocation={()=>setShowLocPicker(true)}
          isElevated={isElevated}
          crmStatus={effectiveCrmStatus}
          ownerName={(viewAsUser?.name || selectedLoc?.owner || currentUser?.name || '').trim() || 'Kevin Shaw'}
          ownerEmail={viewAsUser?.email || currentUser?.email || ''}
          topOffset={TOTAL_TOP}
          partners={partners}
          setPartners={setPartners}
          companies={companies}
          setCompanies={setCompanies}
          people={people}
          setPeople={setPeople}
          transferPeople={transferPeople}
          allOverview={initialAllOverview}
          leadsTruncated={!!initialLeadsTruncated}
          networkTruncated={!!initialNetworkTruncated}
          locations={initialLocations || ALL_LOCATIONS}
          activeNav={activeNav}
          nav={nav}
          onOpenRecord={(person)=>{
            setGlobalSelectedPerson(person)
            setActiveNav('hive')
            if (typeof window !== 'undefined') {
              window.history.pushState({}, '', '/clients/' + person.id)
              window.scrollTo(0, 0)
            }
          }}
          onOpenHive={(intent)=>{
            // Home "Needs attention" deep-link: stash the intent, switch to the
            // Clients tab, and drive the URL to /clients (bare tab). HiveShell
            // consumes the intent on mount to land on the right tab + target.
            setHiveIntent(intent || null)
            setActiveNav('hive')
            if (typeof window !== 'undefined') {
              if (window.location.pathname !== '/clients') window.history.pushState({}, '', '/clients')
              window.scrollTo(0, 0)
            }
          }}
          onOpenSystemHealth={()=>{
            // The Home health panel's "View full system health →" (and its
            // look-list rows) jump to Admin → System Health, the deep view.
            // Same deep-link the Slack digest uses (?section=health) — set the
            // section, then switch to the admin tab.
            setAdminDeepLinkSection('health')
            nav('admin')
          }}
          followUps={followUps}
          engagements={Array.isArray(initialEngagements)?initialEngagements:[]}
          engagementsClosedCount={Number(initialEngagementsClosedCount)||0}
          engagementsClosedWonCount={Number(initialEngagementsClosedWonCount)||0}
          newBoardAllowed={canSeeBetaBoard(role)}
          onCompleteOnboarding={()=>{
            // Real franchise owners have franchiseLoc=null (no selectedLoc,
            // no viewAsUser) — fall back to their currentUser.locationId so
            // the dismissal works in both view-as and real-sign-in cases.
            const locId = franchiseLoc?.id || currentUser?.locationId || null
            if (locId) updateLocStatus(locId, 'active')
            setActiveNav('home')
            // Persist to DB so refreshing doesn't resurface onboarding.
            // Fire and forget — the launch animation's onSkipOnboarding already
            // dismisses client-side, so a failed write only impacts next session.
            if (locId) {
              fetch('/api/locations/' + locId + '/complete-onboarding', { method: 'POST' })
                .then(() => router.refresh())
                .catch(e => console.error('[onboarding complete] server write failed:', e))
            }
          }}
          setFollowUps={setFollowUps}
          currentUserId={viewAsUser?.id || currentUser?.id || 'u11'}
          currentLocation={currentLocation}
          isCoOwner={role==='franchise' && franchiseRole==='owner' && currentUser?.isPrimaryOwner===false && !viewAsUser}
          currentUserProfile={currentUser ? { id: currentUser.id, email: currentUser.email, first_name: currentUser.first_name, last_name: currentUser.last_name, phone: currentUser.phone } : null}
        />
      </div>
    )
  }

  // Responsive sidebar / topbar / loc-banner visibility is owned by
  // app/globals.css media queries (.bee-sidebar / .bee-mobile-topbar /
  // .bee-main / .bee-loc-banner). The runtime <style> injection that
  // duplicated those rules has been removed — one source of truth.

  return (
    <CurrentUserContext.Provider value={currentUser || null}>
    <CurrentLocationContext.Provider value={currentLocation || null}>
    <LocationUsersContext.Provider value={users}>
    <TierPricesContext.Provider value={tierPricesValue}>
    <SeatsContext.Provider value={seatsValue}>
    <PartnersContext.Provider value={partnersCtxValue}>
    <CompaniesContext.Provider value={companiesCtxValue}>
    <div>
      <LocBanner />
      <MobileTopBar />
      <MobileNavDrawer />
      <MobileProfileMenu />
      {/* First-time discovery hint pointing at the Ask Bee Hub pill. One fixed
          popover, positioned under whichever top-bar icon is visible (mobile
          top bar vs desktop sidebar header). Retires via bee_guide_dismissed. */}
      {showGuideHint && (
        <div style={{
          position:'fixed', zIndex:10010,
          background:'white', borderRadius:'12px', boxShadow:'0 12px 40px rgba(26,46,43,0.28)', padding:'14px',
          ...(isMobile
            ? { top:`${TOTAL_TOP + 48 + 6}px`, right:'10px', width:'min(260px, calc(100vw - 20px))' }
            : { top:`${TOTAL_TOP + 62}px`, left:'12px', width:'196px' }),
        }}>
          {/* up-arrow toward the icon */}
          {/* Arrow offsets account for the wider "? Help" pill (vs the old circle). */}
          <div style={{ position:'absolute', top:'-7px', ...(isMobile ? { right:'56px' } : { right:'30px' }), width:'14px', height:'14px', background:'white', transform:'rotate(45deg)', boxShadow:'-2px -2px 5px rgba(26,46,43,0.05)' }} />
          <p style={{ fontSize:'13px', color:'#1a2e2b', lineHeight:1.5, marginBottom:'12px', fontWeight:500 }}>
            👋 New here? Tap Ask Bee Hub for instant help — plus the Quick Start Guide and Manual.
          </p>
          <div style={{ display:'flex', gap:'8px', justifyContent:'flex-end' }}>
            <button onClick={dismissGuideHint} style={{ padding:'7px 12px', background:'#1a2e2b', border:'none', borderRadius:'8px', fontSize:'12px', fontFamily:'inherit', fontWeight:600, color:'white', cursor:'pointer' }}>Got it</button>
          </div>
        </div>
      )}
      {showGuide && (
        <HowToGuideModal
          onClose={() => setShowGuide(false)}
          onDismiss={() => {
            try { localStorage.setItem('bee_guide_dismissed', '1') } catch (e) { /* private mode */ }
            setShowGuide(false)
          }}
          slides={guideSlides}
          canEdit={(role === 'super_admin' || role === 'corporate') && !viewAsUser}
          onPersist={async newSlides => {
            const res = await fetch('/api/guide-slides', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ slides: newSlides }),
            })
            if (!res.ok) {
              const err = await res.json().catch(() => ({}))
              throw new Error(err.error || `HTTP ${res.status}`)
            }
            setGuideSlides(newSlides)
          }}
        />
      )}
      <ManualModal
        slides={manualSlides}
        open={showManual}
        onClose={() => setShowManual(false)}
      />
      {/* ambientContext (issue 249) — the screen + route the user was on when
          they opened this. Computed HERE because the modal cannot see it: it
          receives no router and no shell state, only `seed`. activeNav lives in
          this component (the same value the Ask Bee Hub panel below reads for
          its screenName) and the address bar is kept in sync by the pushState
          nav, so both halves are already to hand. Recomputed per render while
          the modal is open — a pure string build over state we already hold. */}
      {showFeedback && <FeedbackModal initialTab={showFeedback === 'submit' ? 'submit' : 'mine'} viewAsUserId={viewAsUser?.id || null} seed={feedbackSeed} ambientContext={buildAmbientContext({ nav: activeNav, role, pathname: typeof window !== 'undefined' ? window.location.pathname : null, search: typeof window !== 'undefined' ? window.location.search : null })} onClose={() => { setShowFeedback(false); setFeedbackSeed(null) }} />}
      {showHelpChat && (
        <AskBeeHubPanel
          isMobile={isMobile}
          screenName={
            activeNav === 'hive' ? 'Clients'
            : activeNav === 'partners' ? 'Network'
            : activeNav === 'reports' ? 'Reports'
            : activeNav === 'backoffice' ? 'Back Office' /* issue 140 */
            : activeNav === 'settings' ? 'Settings'
            : activeNav === 'admin' ? (role === 'super_admin' ? 'Admin' : 'Corp')
            : 'Home'
          }
          onClose={() => setShowHelpChat(false)}
          onOpenGuide={() => { setShowHelpChat(false); openGuide() }}
          onOpenManual={() => { setShowHelpChat(false); setShowManual(true) }}
          onOpenFeedback={() => { setShowHelpChat(false); setShowFeedback(true) }}
        />
      )}
      <LocPickerDropdown />

      {/* Sidebar nav - desktop only. The column itself no longer scrolls —
          the NAV LIST is the scroll region (flex:1 + overflowY:auto below),
          so everything after it (search + identity/scope control) is a
          PINNED footer that stays visible however tall the board gets, and
          the identity popover isn't clipped by a scrolling ancestor. */}
      <div className="bee-sidebar" style={{ position:'fixed', top:0, left:0, bottom:0, width:'220px', background:'#1a2e2b', flexDirection:'column', zIndex:99, borderRight:'1px solid rgba(168,201,196,0.1)' }}>
        {/* Logo + Ask Bee Hub — stacked so the 220px sidebar gives the logo
            lockup full width (title never wraps) and the Ask button sits on
            its own clean row below, no crowding. */}
        <div style={{ padding:'20px 20px 16px', borderBottom:'1px solid rgba(168,201,196,0.08)', flexShrink:0 }}>
          <div style={{ display:'flex', alignItems:'center', gap:'10px', marginBottom:'12px' }}>
            <span style={{ fontSize:'22px', flexShrink:0 }}>🐝</span>
            <div style={{ flex:1, minWidth:0 }}>
              <p style={{ fontSize:'14px', fontWeight:700, color:'white', fontFamily:'Georgia,serif', lineHeight:1, whiteSpace:'nowrap' }}>Bee Hub</p>
              <p style={{ fontSize:'10px', color:'rgba(168,201,196,0.5)', marginTop:'2px', whiteSpace:'nowrap' }}>Bee Organized</p>
            </div>
          </div>
          <AskBeeHubButton onOpen={()=>{ dismissGuideHint(); setShowHelpChat(true) }} />
        </div>
        {/* Nav items — THE scroll region; footer below stays pinned */}
        <div style={{ flex:1, minHeight:0, overflowY:'auto', padding:'12px 10px', display:'flex', flexDirection:'column', gap:'2px' }}>
          {navItems.map(item=>{
            const isOnboardingState = effectiveCrmStatus==='onboarding'
            // Franchise sub-role gating
            // issue 139: Reports has NO role lock — every role that sees the tab
            // gets the identical Coming Soon screen (one behavior, no branch).
            // Settings nav is likewise open to EVERY role — SettingsScreen itself
            // allowlists the sections (owner: everything; manager and lite_user:
            // Profile only, a self-edit). Don't reintroduce a nav-level role
            // denylist for either. Onboarding lockdown only applies to franchise
            // users mid-setup — super_admin / corporate are always elevated and
            // never "onboarding."
            // issue 140: Back Office is exempt from the onboarding lock (see the
            // sidebar block above) — always clickable for every role.
            const isLocked = (isOnboardingState && !isElevated && !['home','backoffice'].includes(item.key))
            const isActive = activeNav===item.key
            return (
              <button key={item.key} onClick={()=>{ if (isLocked) return; if (item.action==='openManual') setShowManual(true); else nav(item.key) }} style={{ width:'100%', padding:'10px 14px', borderRadius:'10px', border:'none', cursor:isLocked?'default':'pointer', fontFamily:'inherit', display:'flex', alignItems:'center', gap:'12px', textAlign:'left', background:isActive?'rgba(168,201,196,0.12)':'transparent', opacity:isLocked?0.3:1, transition:'background 0.15s' }}>
                <span style={{ fontSize:'18px', lineHeight:1, flexShrink:0 }}>{item.icon}</span>
                <span style={{ fontSize:'13px', fontWeight:isActive?600:400, color:isActive?'#a8c9c4':'rgba(168,201,196,0.6)' }}>{item.label}</span>
                {isActive&&<div style={{ marginLeft:'auto', width:'4px', height:'4px', borderRadius:'50%', background:'#a8c9c4' }} />}
              </button>
            )
          })}
        </div>
        {/* Search button in sidebar (pinned footer starts here) */}
        <div style={{ padding:'8px 10px', borderTop:'1px solid rgba(168,201,196,0.08)', flexShrink:0 }}>
          <button onClick={()=>setShowGlobalSearch(true)} style={{ width:'100%', padding:'9px 12px', background:'rgba(168,201,196,0.08)', border:'1px solid rgba(168,201,196,0.15)', borderRadius:'10px', cursor:'pointer', fontFamily:'inherit', display:'flex', alignItems:'center', gap:'8px', color:'rgba(168,201,196,0.6)', fontSize:'12px' }}>
            <span style={{ fontSize:'14px' }}>🔍</span>
            <span style={{ flex:1, textAlign:'left' }}>Search…</span>
            <span style={{ fontSize:'10px', background:'rgba(168,201,196,0.12)', padding:'1px 5px', borderRadius:'4px', color:'rgba(168,201,196,0.4)' }}>⌘K</span>
          </button>
        </div>
        {/* Identity + scope control — PINNED sidebar footer. The merge of
            the old top super-admin strip (View as / name / badge), the
            footer location switcher, and the footer avatar/sign-out block.
            All props passed DOWN (§8.5); the handlers are the SAME code
            paths those three controls called — relocated, not forked. */}
        {(() => {
          const isRealSuperAdmin = (initialRole ?? 'super_admin') === 'super_admin'
          const realName = currentUser?.name || 'Kevin Shaw'
          const realRoleLabel = isRealSuperAdmin ? 'Super Admin'
            : role === 'corporate' ? 'Corporate'
            : franchiseRole === 'owner'   ? 'Zee Bee'
            : franchiseRole === 'manager' ? 'Hive Manager'
            : franchiseRole === 'light'   ? 'Worker Bee'
            : franchiseRole === 'readonly' ? 'Honey Watcher'
            : ''
          const locationLabel = locFilter === 'all'
            ? 'All locations'
            : selectedLoc ? `${selectedLoc.name}, ${selectedLoc.state}`
            : currentLocation?.name || 'Your location'
          return (
            <div style={{ padding:'10px', borderTop:'1px solid rgba(168,201,196,0.08)', flexShrink:0 }}>
              <IdentityScopeControl
                name={realName}
                email={currentUser?.email || ''}
                initials={getInitials(realName)}
                roleLabel={realRoleLabel}
                roleBadgeTint={isRealSuperAdmin ? 'warning' : 'accent'}
                isSuperAdmin={isRealSuperAdmin}
                viewingAs={viewAsUser ? {
                  name: viewAsUser.name,
                  roleLabel: FRANCHISE_ROLES.find(r => r.key === viewAsUser.role)?.label || 'Corporate',
                } : null}
                locationLabel={locationLabel}
                locationCount={(initialLocations || ALL_LOCATIONS).length}
                canSwitchLocation={isElevated}
                onOpenViewAs={()=>{ logViewAs('enter:open-picker', { source:'sidebar', roleFlip: !viewAsUser ? 'super_admin→franchise' : 'none', viewAsTarget:true }); snapshotIdentityForViewAs(); if (!viewAsUser) setRole('franchise'); setViewAsTarget(true) }}
                onExitViewAs={()=>{ logViewAs('exit:restore', { source:'sidebar', role:'super_admin', viewAsUser:null, locFilter:'all' }); setViewAsUser(null); setRole('super_admin'); applyLocScope('all') }}
                onOpenLocationPicker={()=>setShowLocPicker(true)}
                signOutHref="/api/auth/signout"
              />
            </div>
          )
        })()}
      </div>

      {/* Scope-switch feedback (immediate, no delay gate).
          BeeLoader's 350ms threshold is right for a SECTION load, where the
          question is "is this slow enough to be worth a loader". This is a
          different question — "did my click land" — and the answer has to be
          instant or the button feels dead. A thin bar appearing for 150ms is
          not the flash problem; a full loader would be. */}
      <ScopeSwitchProgress active={isScopePending} />

      {/* Main content - offset by sidebar on desktop */}
      <div className="bee-main" style={{ marginLeft:0 }}>
        {/* While the switch is in flight this content is the PREVIOUS
            location's — correct-looking and completely stale. Dimming says so,
            and pointer-events:none stops a click landing on a row that is
            about to be replaced by a different location's record. The chrome
            (sidebar, picker, nav) stays live, so the switch can be changed or
            repeated mid-flight. */}
        <div
          aria-busy={isScopePending || undefined}
          style={isScopePending
            ? { opacity: 0.45, pointerEvents: 'none', transition: 'opacity 140ms ease-out' }
            : { transition: 'opacity 140ms ease-out' }}
        >
          {screen()}
        </div>
      </div>

      {showGlobalSearch&&(
        <GlobalSearch
          people={people}
          partners={partners}
          // ⌘K scans the LOADED people array, which since Phase 1 holds one
          // location for an elevated user. Naming the scope is the Phase 2
          // fix: the search silently narrowing with no cue is the same
          // failure class as MAX_LEADS dropping leads without an error. The
          // real cross-location search endpoint is Phase 4.
          scopeLabel={locFilter === 'all' ? 'all locations' : (selectedLoc?.name || currentLocation?.name || 'this location')}
          locationsById={locationNameById}
          onSelectPerson={(p)=>{
            setShowGlobalSearch(false)
            // router.push, NOT pushState. A search hit can now live at ANOTHER
            // location (the server searches all of them), and only a real
            // navigation re-runs the server component — which is what triggers
            // the Phase 2 deep-link override and loads the page around that
            // lead. A pushState would change the URL while leaving the scope
            // and the loaded data behind, and the record would never open.
            setActiveNav('hive')
            router.push(clientPath(p.id))
          }}
          onSelectPartner={(p)=>{ setActiveNav('partners'); setGlobalSelectedPartner(p); setShowGlobalSearch(false) }}
          onClose={()=>setShowGlobalSearch(false)}
        />
      )}
      {viewAsTarget&&(
        <ViewAsUserSheet
          users={users}
          locations={initialLocations || ALL_LOCATIONS}
          onConfirm={(user)=>{
            // One source of truth for the mapping (lib/view-as-identity), so
            // the log line and the setters cannot describe different identities
            // — and so "a corporate target stays elevated" is unit-testable.
            // That property is what keeps the transfer queue visible to a corp
            // identity like Leslie: elevated role → HiveScreen passes it down.
            const next = viewAsIdentityFor(user)
            logViewAs('enter:confirm', { source:'picker', chosen:{ id:user.id, name:user.name, role:user.role }, role: next.role, franchiseRole: next.franchiseRole, locFilter: next.locFilter, viewAsUser:{ id:user.id, name:user.name }, viewAsTarget:null })
            applyLocScope(next.locFilter)
            setRole(next.role)
            setFranchiseRole(next.franchiseRole)
            setViewAsUser(user)
            setActiveNav('home')
            setViewAsTarget(null)
            setViewAsSnapshot(null)
            window.scrollTo(0,0)
          }}
          onClose={cancelViewAsPicker}
        />
      )}
    </div>
    </CompaniesContext.Provider>
    </PartnersContext.Provider>
    </SeatsContext.Provider>
    </TierPricesContext.Provider>
    </LocationUsersContext.Provider>
    </CurrentLocationContext.Provider>
    </CurrentUserContext.Provider>
  )
}
